def parse_ocr_psms(raw):
    value = (raw or "").strip()
    if not value:
        return (6, 11)
    psms = []
    for item in value.split(","):
        item = item.strip()
        if not item:
            continue
        try:
            psm = int(item)
        except ValueError:
            continue
        if 0 <= psm <= 13 and psm not in psms:
            psms.append(psm)
    return tuple(psms) if psms else (6, 11)


OCR_TESSERACT_PSMS = parse_ocr_psms(os.environ.get("OCR_TESSERACT_PSMS", "6,11"))


def parse_ocr_dpis(raw, base_dpi):
    value = (raw or "").strip()
    dpis = []
    if value:
        for item in value.split(","):
            item = item.strip()
            if not item:
                continue
            try:
                dpi = int(item)
            except ValueError:
                continue
            if dpi >= 120 and dpi not in dpis:
                dpis.append(dpi)
    if base_dpi not in dpis:
        dpis.insert(0, base_dpi)
    if not dpis:
        dpis = [base_dpi, 340]
    return tuple(dpis)


