def upsert_seguro_comision_contabilidad(conn, seguro_row, now, movimiento="emision", fecha=None, importe=None):
    if not seguro_row:
        return None
    seguro_id = (seguro_row.get("id") if isinstance(seguro_row, dict) else seguro_row["id"]) or ""
    empresa_id = (seguro_row.get("empresa_id") if isinstance(seguro_row, dict) else seguro_row["empresa_id"]) or ""
    if not seguro_id or not empresa_id:
        return None
    cliente_id = (seguro_row.get("cliente_id") if isinstance(seguro_row, dict) else seguro_row["cliente_id"]) or None
    cliente_ids_json = json.dumps([cliente_id], ensure_ascii=False) if cliente_id else None
    poliza_numero = (seguro_row.get("poliza_numero") if isinstance(seguro_row, dict) else seguro_row["poliza_numero"]) or ""
    comision_src = importe
    if comision_src in (None, ""):
        comision_src = seguro_row.get("comision") if isinstance(seguro_row, dict) else seguro_row["comision"]
    comision = round(parse_money_value(comision_src), 2)
    if abs(comision) < 0.005:
        return None
    fecha_base = fecha
    if not fecha_base:
        fecha_base = seguro_row.get("fecha_efecto") if isinstance(seguro_row, dict) else seguro_row["fecha_efecto"]
    fecha_iso = ""
    parsed_fecha = parse_iso_date(fecha_base)
    if parsed_fecha:
        fecha_iso = parsed_fecha.isoformat()
    if not fecha_iso:
        return None
    is_renovacion = normalize_lookup_text(movimiento) in ("RENOVACION", "RENOVAR", "RENEW")
    if not is_renovacion:
        estado = normalize_seguro_estado_value(
            seguro_row.get("estado") if isinstance(seguro_row, dict) else seguro_row["estado"]
        )
        if estado != "En vigor":
            return None
    gestion = "Comisión renovación" if is_renovacion else "Comisión emisión"
    concepto = "Comisión renovación póliza" if is_renovacion else "Comisión emisión póliza"
    if poliza_numero:
        concepto = f"{concepto} {poliza_numero}"
    existing = conn.execute(
        """
        SELECT id
        FROM gestoria_contabilidad
        WHERE seguro_id = ?
          AND fecha = ?
          AND LOWER(COALESCE(gestion, '')) = LOWER(?)
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (seguro_id, fecha_iso, gestion),
    ).fetchone()
    notas = f"Auto CRM Seguros · {gestion.lower()}."
    if existing:
        conn.execute(
            """
            UPDATE gestoria_contabilidad
            SET empresa_id = ?, cliente_id = ?, cliente_ids_json = ?, poliza_numero = ?, concepto = ?, tipo = ?, importe = ?, notas = ?,
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                empresa_id,
                cliente_id,
                cliente_ids_json,
                poliza_numero,
                concepto,
                "Ingreso",
                comision,
                notas,
                now,
                existing["id"],
            ),
        )
        return existing["id"]
    record_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_contabilidad (
          id, empresa_id, cliente_id, cliente_ids_json, seguro_id, poliza_numero, fecha, concepto, gestion, tipo, importe, notas,
          created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            record_id,
            empresa_id,
            cliente_id,
            cliente_ids_json,
            seguro_id,
            poliza_numero,
            fecha_iso,
            concepto,
            gestion,
            "Ingreso",
            comision,
            notas,
            now,
            now,
        ),
    )
    return record_id


def resolve_seguro_contabilidad_link(conn, seguro_id):
    seguro_id = str(seguro_id or "").strip()
    if not seguro_id:
        return "", None
    row = conn.execute(
        "SELECT poliza_numero, cliente_id FROM seguros WHERE id = ? LIMIT 1",
        (seguro_id,),
    ).fetchone()
    if not row:
        return "", None
    poliza_numero = (row["poliza_numero"] or "").strip()
    cliente_id = (row["cliente_id"] or "").strip() or None
    return poliza_numero, cliente_id


def parse_cliente_ids_payload(raw_value):
    if raw_value in (None, ""):
        return []
    items = raw_value
    if isinstance(raw_value, str):
        text = raw_value.strip()
        if not text:
            return []
        if text.startswith("["):
            try:
                parsed = json.loads(text)
                if isinstance(parsed, list):
                    items = parsed
                else:
                    items = [parsed]
            except Exception:
                items = [part.strip() for part in text.split(",")]
        else:
            items = [part.strip() for part in text.split(",")]
    elif not isinstance(raw_value, (list, tuple, set)):
        items = [raw_value]
    out = []
    for item in items:
        value = str(item or "").strip()
        if value and value not in out:
            out.append(value)
    return out


def seguros_contabilidad_where_clause(alias="gc"):
    p = alias.strip() or "gc"
    return (
        f"(({p}.seguro_id IS NOT NULL AND TRIM({p}.seguro_id) <> '') "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE 'AUTO CRM SEGUROS%' "
        f"OR UPPER(COALESCE({p}.notas, '')) LIKE '[SEGUROS]%' "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) IN ('COMISION EMISION', 'COMISION RENOVACION', 'REGULARIZACION', 'REGULARIZACIÓN', 'EXTORNO') "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) LIKE 'COMISI% EMISI%' "
        f"OR UPPER(TRIM(COALESCE({p}.gestion, ''))) LIKE 'COMISI% RENOVA%')"
    )


def compute_seguros_contabilidad_totals(conn, empresa_id, year=None):
    where = [ "gc.empresa_id = ?", seguros_contabilidad_where_clause("gc") ]
    values = [empresa_id]
    if year:
        where.append("STRFTIME('%Y', gc.fecha) = ?")
        values.append(str(year))
    rows = conn.execute(
        f"""
        SELECT gc.tipo, gc.importe, gc.gestion
        FROM gestoria_contabilidad gc
        WHERE {' AND '.join(where)}
        """,
        values,
    ).fetchall()
    ingresos = 0.0
    gastos = 0.0
    for row in rows:
        amount = parse_money_value(row["importe"])
        if normalize_lookup_text(row["tipo"]) == "GASTO":
            gastos += amount
        else:
            ingresos += amount
    return {"ingresos": round(ingresos, 2), "gastos": round(gastos, 2)}


def normalize_auto_seguro_commission_assignments(conn, now=None):
    now = now or datetime.now(timezone.utc).isoformat()
    try:
        rows = conn.execute(
            """
            SELECT gc.id, gc.cliente_id, gc.cliente_ids_json, gc.notas, gc.seguro_id, s.cliente_id AS seguro_cliente_id
            FROM gestoria_contabilidad gc
            LEFT JOIN seguros s ON s.id = gc.seguro_id
            WHERE gc.seguro_id IS NOT NULL AND TRIM(gc.seguro_id) <> ''
              AND UPPER(COALESCE(gc.notas, '')) LIKE 'AUTO CRM SEGUROS%'
            """
        ).fetchall()
    except sqlite3.Error:
        return 0
    updated = 0
    for row in rows:
        seguro_cliente_id = str(row["seguro_cliente_id"] or "").strip()
        if not seguro_cliente_id:
            continue
        assigned = parse_cliente_ids_payload(row["cliente_ids_json"])
        if not assigned and row["cliente_id"]:
            assigned = [str(row["cliente_id"]).strip()]
        if len(assigned) == 1 and assigned[0] == seguro_cliente_id:
            continue
        conn.execute(
            """
            UPDATE gestoria_contabilidad
            SET cliente_id = ?, cliente_ids_json = ?, updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                seguro_cliente_id,
                json.dumps([seguro_cliente_id], ensure_ascii=False),
                now,
                row["id"],
            ),
        )
        updated += 1
    return updated


def find_existing_seguro_id(conn, empresa_id, poliza_numero, compania, exclude_id=None):
    poliza_norm = normalize_poliza_key(poliza_numero)
    if not poliza_norm:
        return ""
    compania_norm = normalize_company_key(compania)
    rows = conn.execute(
        "SELECT id, poliza_numero, compania, estado FROM seguros WHERE empresa_id = ?",
        (empresa_id,),
    ).fetchall()
    for row in rows:
        row_id = row["id"]
        if exclude_id and row_id == exclude_id:
            continue
        estado_key = normalize_lookup_text(row["estado"] or "")
        if "MIGRADO LEGADO" in estado_key or "LEGACY" in estado_key:
            continue
        row_poliza = normalize_poliza_key(row["poliza_numero"])
        if not row_poliza or row_poliza != poliza_norm:
            continue
        row_comp = normalize_company_key(row["compania"])
        if compania_norm and row_comp and compania_norm != row_comp:
            continue
        return row_id
    return ""


def normalize_lookup_text(value):
    if not value:
        return ""
    text = str(value)
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = text.upper()
    text = re.sub(r"[^A-Z0-9]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def normalize_workspace_slug(value):
    text = normalize_lookup_text(value or "").lower().replace(" ", "-")
    text = re.sub(r"[^a-z0-9\-]+", "", text)
    text = re.sub(r"\-+", "-", text).strip("-")
    return text or "workspace"


def normalize_service_key(value):
    text = normalize_lookup_text(value)
    aliases = {
        "GESTORIA": "gestoria",
        "SEGUROS": "seguros",
        "INMOBILIARIA": "inmobiliaria",
        "FINANCIACIONES": "financiaciones",
        "HIPOTECAS": "financiaciones",
        "ADMINISTRACION FINCAS": "administracion fincas",
        "ADMINISTRACION DE FINCAS": "administracion fincas",
    }
    return aliases.get(text, text.lower().strip())


def ensure_workspace_core_tables(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspaces (
          id TEXT PRIMARY KEY,
          nombre TEXT NOT NULL UNIQUE,
          slug TEXT NOT NULL UNIQUE,
          estado TEXT NOT NULL DEFAULT 'Activo',
          plan TEXT NOT NULL DEFAULT 'Enterprise',
          descripcion TEXT,
          logo_url TEXT,
          primary_color TEXT,
          accent_color TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_empresas (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          rol TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, empresa_id)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS workspace_modulos (
          id TEXT PRIMARY KEY,
          workspace_id TEXT NOT NULL,
          modulo_key TEXT NOT NULL,
          modulo_nombre TEXT NOT NULL,
          categoria TEXT,
          enabled INTEGER NOT NULL DEFAULT 1,
          sort_order INTEGER NOT NULL DEFAULT 0,
          config_json TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          UNIQUE (workspace_id, modulo_key)
        )
        """
    )
    ensure_column(conn, "workspaces", "descripcion", "descripcion TEXT")
    ensure_column(conn, "workspaces", "logo_url", "logo_url TEXT")
    ensure_column(conn, "workspaces", "primary_color", "primary_color TEXT")
    ensure_column(conn, "workspaces", "accent_color", "accent_color TEXT")
    ensure_column(conn, "workspace_modulos", "config_json", "config_json TEXT")


def bootstrap_default_workspace(conn):
    now = datetime.now(timezone.utc).isoformat()
    workspace = conn.execute(
        "SELECT id FROM workspaces WHERE nombre = ? OR slug = ? LIMIT 1",
        (DEFAULT_WORKSPACE_NAME, normalize_workspace_slug(DEFAULT_WORKSPACE_NAME)),
    ).fetchone()
    if workspace:
        workspace_id = workspace["id"] if isinstance(workspace, sqlite3.Row) else workspace[0]
        conn.execute(
            """
            UPDATE workspaces
            SET descripcion = COALESCE(NULLIF(descripcion, ''), ?),
                estado = COALESCE(NULLIF(estado, ''), 'Activo'),
                plan = COALESCE(NULLIF(plan, ''), 'Enterprise'),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                f"Tenant inicial del producto {PLATFORM_NAME} y primer caso operativo del grupo.",
                now,
                workspace_id,
            ),
        )
    else:
        workspace_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO workspaces (
              id, nombre, slug, estado, plan, descripcion, primary_color, accent_color, created_at, updated_at
            ) VALUES (?, ?, ?, 'Activo', 'Enterprise', ?, ?, ?, datetime(?), datetime(?))
            """,
            (
                workspace_id,
                DEFAULT_WORKSPACE_NAME,
                normalize_workspace_slug(DEFAULT_WORKSPACE_NAME),
                f"Tenant inicial del producto {PLATFORM_NAME} y primer caso operativo del grupo.",
                "#3C6E71",
                "#5F7A61",
                now,
                now,
            ),
        )

    empresas = conn.execute("SELECT id FROM empresas ORDER BY nombre").fetchall()
    for row in empresas:
        empresa_id = row["id"] if isinstance(row, sqlite3.Row) else row[0]
        conn.execute(
            """
            INSERT OR IGNORE INTO workspace_empresas (
              id, workspace_id, empresa_id, rol, created_at, updated_at
            ) VALUES (?, ?, ?, 'operativa', datetime(?), datetime(?))
            """,
            (os.urandom(16).hex(), workspace_id, empresa_id, now, now),
        )
    for module in WORKSPACE_MODULE_CATALOG:
        conn.execute(
            """
            INSERT OR IGNORE INTO workspace_modulos (
              id, workspace_id, modulo_key, modulo_nombre, categoria, enabled, sort_order, config_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, 1, ?, '{}', datetime(?), datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                module["key"],
                module["nombre"],
                module["categoria"],
                module["sort_order"],
                now,
                now,
            ),
        )


def is_gestoria_dashboard_active_state(value):
    state = normalize_lookup_text(value or "")
    return state in {"ALTA", "ACTIVO", "ACTIVA"}


def is_active_service_state(value, fecha_fin=None):
    state = normalize_lookup_text(value or "")
    if state and state in {"INACTIVO", "BAJA", "CANCELADO", "ANULADO", "FINALIZADO"}:
        return False
    end_date = parse_iso_date(fecha_fin)
    if end_date and end_date < datetime.now(timezone.utc).date():
        return False
    return True


def parse_iso_date(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    head = raw.split("T", 1)[0].split(" ", 1)[0]
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(head, fmt).date()
        except Exception:
            continue
    return None


def parse_datetime_value(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        pass
    parsed_date = parse_iso_date(raw)
    if parsed_date:
        return datetime.combine(parsed_date, datetime.min.time(), tzinfo=timezone.utc)
    return None


def add_year_to_date(value):
    base = parse_iso_date(value)
    if not base:
        return ""
    try:
        return base.replace(year=base.year + 1).isoformat()
    except ValueError:
        # 29/02 -> 28/02 en años no bisiestos
        return base.replace(month=2, day=28, year=base.year + 1).isoformat()


def parse_money_value(value):
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return 0.0
    text = text.replace(".", "").replace(",", ".")
    text = re.sub(r"[^0-9.\-]+", "", text)
    if not text or text in ("-", "."):
        return 0.0
    try:
        return float(text)
    except ValueError:
        return 0.0


MALAGA_BONUS_OFFICES = {
    "MODERNIA NORTE",
    "MODERNIA OESTE",
    "MODERNIA CENTRO",
    "MALAGA NORTE",
    "MALAGA OESTE",
    "MALAGA CENTRO",
}


def has_malaga_bonus_office(value):
    key = normalize_lookup_text(value)
    if not key:
        return False
    return key in MALAGA_BONUS_OFFICES


def derive_hipoteca_commissions(comision_total, oficina_o_agencia):
    total = max(parse_money_value(comision_total), 0.0)
    juan = round(total * 0.20, 2)
    cesion_rate = 0.25 if has_malaga_bonus_office(oficina_o_agencia) else 0.20
    cesion = round(total * cesion_rate, 2)
    modernia = round(max(total - juan - cesion, 0.0), 2)
    return {
        "comision_juan": juan,
        "cesion": cesion,
        "comision_modernia": modernia,
    }


def derive_hipoteca_financing(precio, importe_hipoteca):
    precio_num = parse_money_value(precio) if precio not in (None, "") else None
    hipoteca_num = parse_money_value(importe_hipoteca) if importe_hipoteca not in (None, "") else None
    if precio_num is None or precio_num <= 0 or hipoteca_num is None:
        return None
    porcentaje = round((hipoteca_num * 100.0) / precio_num, 2)
    return {
        "precio": round(precio_num, 2),
        "importe_hipoteca": round(hipoteca_num, 2),
        "porcentaje": porcentaje,
    }


