def derive_hipoteca_inmobiliaria_cost(row):
    total = parse_money_value((row.get("comision") if isinstance(row, dict) else row["comision"]) or 0)
    juan = parse_money_value((row.get("comision_juan") if isinstance(row, dict) else row["comision_juan"]) or 0)
    modernia = parse_money_value((row.get("comision_modernia") if isinstance(row, dict) else row["comision_modernia"]) or 0)
    explicit = parse_money_value((row.get("cesion") if isinstance(row, dict) else row["cesion"]) or 0)
    if explicit > 0.005:
        return round(explicit, 2)
    derived = round(total - juan - modernia, 2)
    if derived > 0.005:
        return derived
    return 0.0


def hipoteca_office_has_no_cesion_costs(value):
    key = normalize_lookup_text(value)
    return key in {"PARTICULAR", "PARTICULARES"}


def build_hipoteca_accounting_entries(row):
    estado = (row.get("estado") if isinstance(row, dict) else row["estado"]) or ""
    fecha = resolve_hipoteca_accounting_date(row)
    if not fecha or not hipoteca_estado_is_closed(estado):
        return []
    cliente = str((row.get("cliente") if isinstance(row, dict) else row["cliente"]) or "").strip() or "Hipoteca"
    banco = str((row.get("banco") if isinstance(row, dict) else row["banco"]) or "").strip()
    suffix = f"{cliente}"
    if banco:
        suffix = f"{cliente} · {banco}"
    entries = []

    def add_entry(gestion, tipo, importe, concepto):
        amount = round(parse_money_value(importe), 2)
        if abs(amount) < 0.005:
            return
        entries.append(
            {
                "gestion": gestion,
                "tipo": tipo,
                "importe": amount,
                "concepto": f"{concepto} · {suffix}",
                "fecha": fecha.isoformat(),
            }
        )

    total_comision = (row.get("comision") if isinstance(row, dict) else row["comision"]) or 0
    oficina = (row.get("oficina") if isinstance(row, dict) else row["oficina"]) or ""
    split = derive_hipoteca_commissions(total_comision, oficina)
    raw_gasto_juan = (row.get("comision_juan") if isinstance(row, dict) else row["comision_juan"])
    raw_gasto_inmobiliaria = (row.get("cesion") if isinstance(row, dict) else row["cesion"])
    if raw_gasto_juan in (None, ""):
        gasto_juan = split["comision_juan"]
    else:
        gasto_juan = raw_gasto_juan
    if raw_gasto_inmobiliaria in (None, ""):
        gasto_inmobiliaria = split["cesion"]
    else:
        gasto_inmobiliaria = raw_gasto_inmobiliaria
    if hipoteca_office_has_no_cesion_costs(oficina):
        gasto_juan = 0
        gasto_inmobiliaria = 0

    add_entry("Comisión cliente", "Ingreso", total_comision, "Comisión cliente")
    add_entry("Cesión Juan", "Gasto", gasto_juan, "Cesión Juan")
    add_entry("Cesión a inmobiliarias", "Gasto", gasto_inmobiliaria, "Cesión a inmobiliarias")
    return entries


def hipoteca_accounting_exclusion_key(hipoteca_id, fecha, gestion):
    return (
        str(hipoteca_id or "").strip(),
        str(fecha or "").strip(),
        normalize_lookup_text(gestion),
    )


def load_hipoteca_accounting_exclusions(conn, empresa_id):
    try:
        rows = conn.execute(
            """
            SELECT hipoteca_id, fecha, gestion
            FROM hipotecas_contabilidad_excluidas
            WHERE empresa_id = ?
            """,
            (empresa_id,),
        ).fetchall()
    except sqlite3.Error:
        return set()
    return {
        hipoteca_accounting_exclusion_key(row["hipoteca_id"], row["fecha"], row["gestion"])
        for row in rows
        if str(row["hipoteca_id"] or "").strip()
    }


def maybe_promote_study_hipoteca_accounting(conn, empresa_id, hipoteca_id, payload, now=None):
    hipoteca_id = str(hipoteca_id or "").strip()
    if not hipoteca_id:
        return False
    tipo = normalize_lookup_text(payload.get("tipo"))
    if tipo == "GASTO":
        return False
    row = conn.execute(
        """
        SELECT id, estado, fecha_firma, anio
        FROM hipotecas
        WHERE id = ?
        LIMIT 1
        """,
        (hipoteca_id,),
    ).fetchone()
    if not row or not hipoteca_estado_is_study(row["estado"]):
        return False
    fecha = parse_iso_date(payload.get("fecha")) or datetime.now(timezone.utc).date()
    stamp = now or datetime.now(timezone.utc).isoformat()
    conn.execute(
        """
        UPDATE hipotecas
        SET estado = ?, fecha_firma = COALESCE(NULLIF(TRIM(fecha_firma), ''), ?), anio = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        ("INDEMNIZACIÓN", fecha.isoformat(), int(fecha.year), stamp, hipoteca_id),
    )
    sync_hipotecas_contabilidad_entries(conn, empresa_id, now=stamp)
    return True


def sync_hipotecas_contabilidad_entries(conn, empresa_id, now=None):
    now = now or datetime.now(timezone.utc).isoformat()
    excluded_keys = load_hipoteca_accounting_exclusions(conn, empresa_id)
    rows = conn.execute(
        """
        SELECT *
        FROM hipotecas
        WHERE empresa_id = ?
        """,
        (empresa_id,),
    ).fetchall()
    expected_keys = set()
    for raw in rows:
        row = dict(raw)
        hipoteca_id = str(row.get("id") or "").strip()
        if not hipoteca_id:
            continue
        entries = build_hipoteca_accounting_entries(row)
        link = resolve_hipoteca_contabilidad_link(conn, hipoteca_id)
        cliente_id = link.get("cliente_id")
        cliente_ids_json = json.dumps([cliente_id], ensure_ascii=False) if cliente_id else None
        for item in entries:
            key = hipoteca_accounting_exclusion_key(hipoteca_id, item["fecha"], item["gestion"])
            if key in excluded_keys:
                continue
            expected_keys.add(key)
            existing = conn.execute(
                """
                SELECT id
                FROM gestoria_contabilidad
                WHERE hipoteca_id = ?
                  AND fecha = ?
                  AND LOWER(COALESCE(gestion, '')) = LOWER(?)
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (hipoteca_id, item["fecha"], item["gestion"]),
            ).fetchone()
            notes = f"{HIPOTECA_ACCOUNTING_AUTO_NOTES_PREFIX} · {item['gestion'].lower()}."
            if existing:
                conn.execute(
                    """
                    UPDATE gestoria_contabilidad
                    SET empresa_id = ?, cliente_id = ?, cliente_ids_json = ?, hipoteca_id = ?, concepto = ?, gestion = ?, tipo = ?,
                        importe = ?, notas = ?, updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (
                        empresa_id,
                        cliente_id,
                        cliente_ids_json,
                        hipoteca_id,
                        item["concepto"],
                        item["gestion"],
                        item["tipo"],
                        item["importe"],
                        notes,
                        now,
                        existing["id"],
                    ),
                )
            else:
                conn.execute(
                    """
                    INSERT INTO gestoria_contabilidad (
                      id, empresa_id, cliente_id, cliente_ids_json, hipoteca_id, fecha, concepto, gestion, tipo, importe, notas,
                      created_at, updated_at
                    ) VALUES (
                      ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                    )
                    """,
                    (
                        os.urandom(16).hex(),
                        empresa_id,
                        cliente_id,
                        cliente_ids_json,
                        hipoteca_id,
                        item["fecha"],
                        item["concepto"],
                        item["gestion"],
                        item["tipo"],
                        item["importe"],
                        notes,
                        now,
                        now,
                    ),
                )
    fixed_expected_keys = set()
    for item in build_hipoteca_fixed_cost_entries(now):
        key = (
            str(item["fecha"]).strip(),
            normalize_lookup_text(item["gestion"]),
            normalize_lookup_text(item["concepto"]),
        )
        fixed_expected_keys.add(key)
        existing = conn.execute(
            """
            SELECT id
            FROM gestoria_contabilidad
            WHERE empresa_id = ?
              AND (hipoteca_id IS NULL OR TRIM(hipoteca_id) = '')
              AND fecha = ?
              AND LOWER(COALESCE(gestion, '')) = LOWER(?)
              AND LOWER(COALESCE(concepto, '')) = LOWER(?)
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (empresa_id, item["fecha"], item["gestion"], item["concepto"]),
        ).fetchone()
        if existing:
            conn.execute(
                """
                UPDATE gestoria_contabilidad
                SET empresa_id = ?, cliente_id = NULL, cliente_ids_json = NULL, hipoteca_id = NULL, concepto = ?, gestion = ?, tipo = ?,
                    importe = ?, notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    item["concepto"],
                    item["gestion"],
                    item["tipo"],
                    item["importe"],
                    item["notas"],
                    now,
                    existing["id"],
                ),
            )
        else:
            conn.execute(
                """
                INSERT INTO gestoria_contabilidad (
                  id, empresa_id, cliente_id, cliente_ids_json, hipoteca_id, fecha, concepto, gestion, tipo, importe, notas,
                  created_at, updated_at
                ) VALUES (
                  ?, ?, NULL, NULL, NULL, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    item["fecha"],
                    item["concepto"],
                    item["gestion"],
                    item["tipo"],
                    item["importe"],
                    item["notas"],
                    now,
                    now,
                ),
            )
    existing_rows = conn.execute(
        """
        SELECT id, hipoteca_id, fecha, gestion
        FROM gestoria_contabilidad
        WHERE empresa_id = ?
          AND hipoteca_id IS NOT NULL
          AND TRIM(hipoteca_id) <> ''
          AND UPPER(COALESCE(notas, '')) LIKE 'AUTO CRM HIPOTECAS%'
        """,
        (empresa_id,),
    ).fetchall()
    for row in existing_rows:
        key = hipoteca_accounting_exclusion_key(row["hipoteca_id"], row["fecha"], row["gestion"])
        if key not in expected_keys:
            conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (row["id"],))
    fixed_rows = conn.execute(
        """
        SELECT id, fecha, gestion, concepto
        FROM gestoria_contabilidad
        WHERE empresa_id = ?
          AND (hipoteca_id IS NULL OR TRIM(hipoteca_id) = '')
          AND UPPER(COALESCE(notas, '')) LIKE UPPER(?)
        """,
        (empresa_id, f"{HIPOTECA_ACCOUNTING_FIXED_COSTS_PREFIX}%"),
    ).fetchall()
    for row in fixed_rows:
        key = (
            str(row["fecha"] or "").strip(),
            normalize_lookup_text(row["gestion"]),
            normalize_lookup_text(row["concepto"]),
        )
        if key not in fixed_expected_keys:
            conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (row["id"],))


def delete_hipoteca_record(conn, record_id):
    if not record_id:
        return False
    row = conn.execute("SELECT id FROM hipotecas WHERE id = ?", (record_id,)).fetchone()
    if not row:
        return False
    conn.execute("DELETE FROM hipotecas WHERE id = ?", (record_id,))
    return True


def delete_gestoria_contabilidad_record(conn, record_id, now=None):
    if not record_id:
        return False
    now = now or datetime.now(timezone.utc).isoformat()
    row = conn.execute(
        """
        SELECT id, empresa_id, hipoteca_id, fecha, gestion, notas
        FROM gestoria_contabilidad
        WHERE id = ?
        LIMIT 1
        """,
        (record_id,),
    ).fetchone()
    if not row:
        return False
    hipoteca_id = str(row["hipoteca_id"] or "").strip()
    notes = str(row["notas"] or "").strip().upper()
    if hipoteca_id and notes.startswith("AUTO CRM HIPOTECAS"):
        conn.execute(
            """
            INSERT INTO hipotecas_contabilidad_excluidas (
              id, empresa_id, hipoteca_id, fecha, gestion, created_at
            ) VALUES (?, ?, ?, ?, ?, datetime(?))
            ON CONFLICT(empresa_id, hipoteca_id, fecha, gestion) DO NOTHING
            """,
            (
                os.urandom(16).hex(),
                row["empresa_id"],
                hipoteca_id,
                row["fecha"],
                row["gestion"],
                now,
            ),
        )
    conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (record_id,))
    return True


def has_explicit_renewal_action(seguro_row):
    estado = normalize_lookup_text(seguro_row.get("estado"))
    estado_ren = normalize_lookup_text(seguro_row.get("estado_renovacion"))
    if seguro_row.get("renovacion_fecha") or seguro_row.get("nueva_poliza_ref"):
        return True
    if any(token in estado for token in ("BAJA", "CANCEL", "ANULAD")):
        return True
    if not estado_ren:
        return False
    return "AUTOM" not in estado_ren


def compute_seguro_display(seguro_row):
    fecha_efecto = seguro_row.get("fecha_efecto")
    venc = parse_iso_date(seguro_row.get("fecha_vencimiento")) or parse_iso_date(add_year_to_date(fecha_efecto))
    base_estado = seguro_row.get("estado") or "-"
    if not venc:
        return {"vencimiento_display": "", "estado_display": base_estado}
    today = datetime.now(timezone.utc).date()
    has_action = has_explicit_renewal_action(seguro_row)
    while venc < today and not has_action:
        try:
            venc = venc.replace(year=venc.year + 1)
        except ValueError:
            venc = venc.replace(month=2, day=28, year=venc.year + 1)
    estado = base_estado
    if parse_iso_date(seguro_row.get("fecha_vencimiento")) and parse_iso_date(seguro_row.get("fecha_vencimiento")) < today and not has_action:
        estado = "Renovada automática"
    return {"vencimiento_display": venc.isoformat(), "estado_display": estado}


def load_seguros_company_hints(path=SEGUROS_COMPANY_HINTS_PATH):
    hints = {}
    if not path.exists():
        return hints
    try:
        with path.open("r", encoding="utf-8") as handle:
            payload = json.load(handle) or {}
    except Exception:
        return hints
    raw_hints = payload.get("hints") if isinstance(payload, dict) else {}
    if not isinstance(raw_hints, dict):
        return hints
    for token, company in raw_hints.items():
        norm_token = normalize_lookup_text(token)
        if norm_token and company:
            hints[norm_token] = normalize_company_name(company)
    return hints


LEARNED_COMPANY_HINTS = load_seguros_company_hints()


def detect_company_from_text(text):
    cleaned = normalize_lookup_text(text)
    if not cleaned:
        return ""
    for pattern, name in COMPANY_ALIAS_PATTERNS:
        if re.search(pattern, cleaned, re.IGNORECASE):
            return name
    return ""


def detect_company_from_metadata(*values):
    joined = " ".join(str(v or "") for v in values).strip()
    if not joined:
        return ""
    cleaned = normalize_lookup_text(joined)
    if not cleaned:
        return ""
    if LEARNED_COMPANY_HINTS:
        for token, company in sorted(LEARNED_COMPANY_HINTS.items(), key=lambda it: len(it[0]), reverse=True):
            if token and token in cleaned:
                return company
    return detect_company_from_text(cleaned)

def normalize_fin_nif(value):
    if not value:
        return ""
    raw = str(value).strip().upper()
    if not raw:
        return ""
    raw = raw.replace(" ", "").replace("-", "").replace(".", "")
    raw = raw.replace("O", "0").replace("I", "1").replace("L", "1").replace("S", "5")
    raw = re.sub(r"[^A-Z0-9]", "", raw)
    if len(raw) > 9:
        raw = raw[:9]
    return raw

def normalize_nif(value):
    if not value:
        return ""
    raw = str(value).strip().upper()
    if not raw:
        return ""
    raw = raw.replace(" ", "").replace("-", "").replace(".", "")
    raw = raw.replace("O", "0").replace("I", "1").replace("L", "1").replace("S", "5")
    raw = re.sub(r"[^A-Z0-9]", "", raw)
    if len(raw) > 12:
        raw = raw[:12]
    return raw

FIN_REQUIRED_FIELDS = [
    ("cliente1_nombre", "Nombre cliente 1"),
    ("cliente1_dni", "DNI cliente 1"),
    ("cliente1_telefono", "Teléfono cliente 1"),
    ("fecha", "Fecha"),
    ("ingresos_conjuntos", "Ingresos conjuntos"),
]

def fin_missing_fields(row):
    missing = []
    if not row:
        return missing
    for key, label in FIN_REQUIRED_FIELDS:
        value = row.get(key) if isinstance(row, dict) else row[key]
        if value is None or str(value).strip() == "":
            missing.append(label)
    return missing

def fin_sync_missing_action(conn, empresa_id, asesoramiento_id, cliente_id, cliente_nombre, missing, now):
    if missing:
        notas = f"Completar datos asesoramiento ({', '.join(missing)}). Asesoramiento ID: {asesoramiento_id}"
        exists = conn.execute(
            """
            SELECT id, estado FROM acciones
            WHERE LOWER(servicio) = 'financiaciones'
              AND asesoramiento_id = ?
              AND tipo = 'Completar datos asesoramiento'
            LIMIT 1
            """,
            (asesoramiento_id,),
        ).fetchone()
        if exists:
            if (exists["estado"] or "").lower() != "pendiente":
                conn.execute(
                    "UPDATE acciones SET estado = 'Pendiente', updated_at = datetime(?) WHERE id = ?",
                    (now, exists["id"]),
                )
            return
        today = datetime.now().strftime("%Y-%m-%d")
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, asesoramiento_id, cliente_nombre,
              fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                "financiaciones",
                cliente_id,
                None,
                asesoramiento_id,
                cliente_nombre or "",
                today,
                None,
                "Completar datos asesoramiento",
                None,
                "Pendiente",
                notas,
                None,
                now,
                now,
            ),
        )
    else:
        conn.execute(
            """
            UPDATE acciones
            SET estado = 'Hecho', updated_at = datetime(?)
            WHERE LOWER(servicio) = 'financiaciones'
              AND asesoramiento_id = ?
              AND tipo = 'Completar datos asesoramiento'
            """,
            (now, asesoramiento_id),
        )


def seguros_sync_activation_action(conn, seguro_row, now):
    if not seguro_row:
        return
    seguro_id = str(seguro_row["id"] or "").strip()
    if not seguro_id:
        return
    empresa_id = str(seguro_row["empresa_id"] or "").strip()
    cliente_id = str(seguro_row["cliente_id"] or "").strip() or None
    fecha_efecto = str(seguro_row["fecha_efecto"] or "").strip()
    efecto_dt = parse_iso_date(fecha_efecto)
    estado_key = normalize_lookup_text(seguro_row["estado"] or "")
    in_vigor = any(token in estado_key for token in ("EN VIGOR", "VIGENTE", "ACTIVA", "ACTIVO"))
    existing = conn.execute(
        """
        SELECT id, estado
        FROM acciones
        WHERE servicio = 'Seguros'
          AND tipo = 'Activar póliza'
          AND notas LIKE ?
        LIMIT 1
        """,
        (f"%{seguro_id}%",),
    ).fetchone()
    today = datetime.now(timezone.utc).date()
    should_be_pending = (
        bool(efecto_dt)
        and efecto_dt > today
        and not in_vigor
    )
    if should_be_pending:
        notas = f"Activar póliza por entrada en vigor ({seguro_row['poliza_numero'] or 'sin número'}). Poliza ID: {seguro_id}"
        if existing:
            conn.execute(
                """
                UPDATE acciones
                SET empresa_id = ?, cliente_id = ?, cliente_nombre = ?, fecha = ?, tipo = 'Activar póliza',
                    estado = 'Pendiente', notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    cliente_id,
                    seguro_row["tomador"] or "",
                    fecha_efecto,
                    notas,
                    now,
                    existing["id"],
                ),
            )
            return
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
              fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                "Seguros",
                cliente_id,
                None,
                seguro_row["tomador"] or "",
                fecha_efecto,
                None,
                "Activar póliza",
                None,
                "Pendiente",
                notas,
                None,
                now,
                now,
            ),
        )
        return
    if existing:
        conn.execute(
            "UPDATE acciones SET estado = 'Hecho', updated_at = datetime(?) WHERE id = ?",
            (now, existing["id"]),
        )

def normalize_header(value):
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())

def load_postal_catalog(conn):
    if not POSTAL_CATALOG_PATH.exists():
        return
    count_row = conn.execute("SELECT COUNT(*) AS total FROM postal_catalogo").fetchone()
    total = 0
    if count_row:
        try:
            total = count_row["total"]
        except (TypeError, KeyError, IndexError):
            total = count_row[0]
    if total:
        return
    encodings = ("utf-8-sig", "latin-1")
    for encoding in encodings:
        try:
            with POSTAL_CATALOG_PATH.open("r", encoding=encoding, newline="") as handle:
                reader = csv.DictReader(handle)
                if not reader.fieldnames:
                    return
                headers = {normalize_header(name): name for name in reader.fieldnames}
                cp_key = next(
                    (headers[k] for k in headers if k in ("codigopostal", "codigo_postal", "postalcode", "cp", "codigo")),
                    None,
                )
                pob_key = next(
                    (headers[k] for k in headers if k in ("poblacion", "municipio", "municipionombre", "localidad", "ciudad", "nombre")),
                    None,
                )
                prov_key = next(
                    (headers[k] for k in headers if k in ("provincia", "provincianombre", "province")),
                    None,
                )
                if not cp_key:
                    return
                batch = []
                seen = set()
                for row in reader:
                    cp_raw = row.get(cp_key, "")
                    cp = normalize_postal_code(cp_raw)
                    if not cp:
                        continue
                    poblacion = (row.get(pob_key, "") if pob_key else "") or ""
                    poblacion = str(poblacion).strip()
                    provincia = (row.get(prov_key, "") if prov_key else "") or ""
                    provincia = str(provincia).strip()
                    if not provincia:
                        provincia = POSTAL_PROVINCES.get(cp[:2], "")
                    key = (cp, poblacion, provincia)
                    if key in seen:
                        continue
                    seen.add(key)
                    batch.append(key)
                    if len(batch) >= 5000:
                        conn.executemany(
                            "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                            batch,
                        )
                        batch = []
                if batch:
                    conn.executemany(
                        "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                        batch,
                    )
            return
        except UnicodeDecodeError:
            continue

def hash_password(password):
    return runtime_hash_password(password)


def verify_password(password, password_hash):
    return runtime_verify_password(password, password_hash)


def _cleanup_expired_sessions():
    now = time.time()
    expired = []
    for token, session in AUTH_SESSIONS.items():
        if float(session.get("expires_at") or 0) <= now:
            expired.append(token)
    for token in expired:
        AUTH_SESSIONS.pop(token, None)


def create_auth_session(user_row):
    now = time.time()
    session = {
        "token": secrets.token_urlsafe(32),
        "user_id": str(user_row["id"]),
        "usuario": str(user_row["usuario"] or ""),
        "nombre": str(user_row["nombre"] or ""),
        "apellido": str(user_row["apellido"] or ""),
        "rol": str(user_row["rol"] or ""),
        "email": str(user_row["email"] or ""),
        "servicio": str(user_row["servicio"] or ""),
        "expires_at": now + APP_SESSION_TTL_SECONDS,
        "created_at": now,
    }
    with AUTH_SESSIONS_LOCK:
        _cleanup_expired_sessions()
        AUTH_SESSIONS[session["token"]] = session
    return session


def get_auth_session(token):
    if not token:
        return None
    with AUTH_SESSIONS_LOCK:
        session = AUTH_SESSIONS.get(token)
        if not session:
            return None
        if float(session.get("expires_at") or 0) <= time.time():
            AUTH_SESSIONS.pop(token, None)
            return None
        session["expires_at"] = time.time() + APP_SESSION_TTL_SECONDS
        return dict(session)


def delete_auth_session(token):
    if not token:
        return
    with AUTH_SESSIONS_LOCK:
        AUTH_SESSIONS.pop(token, None)


def send_mail_smtp(subject, to_email, text_body, html_body=None):
    host = (os.environ.get("SMTP_HOST") or "").strip()
    if not host:
        raise RuntimeError("SMTP_HOST no configurado")
    port = int((os.environ.get("SMTP_PORT") or "587").strip())
    username = (os.environ.get("SMTP_USER") or "").strip()
    password = (os.environ.get("SMTP_PASS") or "").strip()
    from_email = (os.environ.get("SMTP_FROM") or username or "").strip()
    if not from_email:
        raise RuntimeError("SMTP_FROM/SMTP_USER no configurado")
    use_ssl = (os.environ.get("SMTP_SSL") or "").strip().lower() in ("1", "true", "yes", "on")
    use_tls = (os.environ.get("SMTP_TLS") or "1").strip().lower() not in ("0", "false", "no", "off")
    msg = EmailMessage()
    msg["Subject"] = subject
    msg["From"] = from_email
    msg["To"] = to_email
    msg.set_content(text_body)
    if html_body:
        msg.add_alternative(html_body, subtype="html")
    if use_ssl:
        server = smtplib.SMTP_SSL(host, port, timeout=20)
    else:
        server = smtplib.SMTP(host, port, timeout=20)
    try:
        server.ehlo()
        if use_tls and not use_ssl:
            server.starttls()
            server.ehlo()
        if username:
            server.login(username, password)
        server.send_message(msg)
    finally:
        try:
            server.quit()
        except Exception:
            pass


def decode_mime_text(raw):
    if not raw:
        return ""
    parts = []
    try:
        decoded = decode_header(raw)
    except Exception:
        return str(raw)
    for chunk, encoding in decoded:
        if isinstance(chunk, bytes):
            codec = encoding or "utf-8"
            try:
                parts.append(chunk.decode(codec, errors="replace"))
            except Exception:
                parts.append(chunk.decode("utf-8", errors="replace"))
        else:
            parts.append(str(chunk))
    return "".join(parts).strip()


def html_to_text(value):
    text = str(value or "")
    text = re.sub(r"<\s*(script|style)\b[^>]*>.*?<\s*/\s*\1\s*>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def extract_pdf_attachment_text(pdf_bytes, max_pages=2):
    if not pdf_bytes:
        return ""
    tmp_path = ""
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
            tmp_file.write(pdf_bytes)
            tmp_path = tmp_file.name
        text, err = pdftotext_extract(tmp_path, pages=max_pages)
        if text and len(text.strip()) >= 40:
            return text
        text_full, _detail, _method = extract_pdf_text(tmp_path)
        if text_full:
            return text_full
        return text or ""
    except Exception:
        return ""
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def save_campaign_attachment_file(file_bytes, original_name="campana.pdf"):
    if not file_bytes:
        return "", ""
    safe_name = re.sub(r"[^A-Za-z0-9._-]", "_", os.path.basename(original_name or "campana.pdf"))
    if not safe_name.lower().endswith(".pdf"):
        safe_name = f"{safe_name}.pdf"
    folder = UPLOADS / "seguros_campanas"
    folder.mkdir(parents=True, exist_ok=True)
    file_id = os.urandom(16).hex()
    filename = f"{file_id}_{safe_name}"
    file_path = folder / filename
    file_path.write_bytes(file_bytes)
    return f"/uploads/seguros_campanas/{filename}", safe_name


def parse_decimal_amount(value):
    raw = str(value or "").strip()
    if not raw:
        return 0.0
    text = raw.replace("€", "").replace("EUR", "").replace(" ", "")
    text = re.sub(r"[^0-9,.\-]", "", text)
    if not text:
        return 0.0
    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(".", "").replace(",", ".")
    elif "." in text:
        if text.count(".") == 1 and len(text.split(".")[-1]) <= 2:
            pass
        else:
            text = text.replace(".", "")
    try:
        return float(text)
    except Exception:
        return 0.0


def detect_campaign_ramo(text):
    cleaned = normalize_lookup_text(text)
    if not cleaned:
        return ""
    patterns = [
        (r"\bHOGAR\b", "Hogar"),
        (r"\bAUTO\b|\bAUTOMOVIL\b|\bCOCHE\b", "Auto"),
        (r"\bSALUD\b|\bMEDIC(O|A)\b|\bASISTENCIA SANITARIA\b", "Salud"),
        (r"\bDECESOS\b", "Decesos"),
        (r"\bVIDA\b", "Vida"),
        (r"\bCOMERCIO\b|\bPYME\b|\bNEGOCIO\b", "Comercio"),
        (r"\bCOMUNIDAD\b", "Comunidad"),
        (r"\bRESPONSABILIDAD CIVIL\b|\bRC\b", "Responsabilidad civil"),
        (r"\bDEFENSA JURIDICA\b|\bARAG\b", "Defensa jurídica"),
        (r"\bVIAJE\b|\bVIAJES\b", "Viaje"),
        (r"\bAHORRO\b", "Ahorro"),
    ]
    for pattern, ramo in patterns:
        if re.search(pattern, cleaned, re.IGNORECASE):
            return ramo
    return ""


def parse_campaign_dates(text):
    cleaned = str(text or "")
    if not cleaned:
        return "", ""

    def _by_patterns(patterns):
        for pattern in patterns:
            match = re.search(pattern, cleaned, re.IGNORECASE)
            if not match:
                continue
            parsed = parse_iso_date(match.group(1))
            if parsed:
                return parsed.isoformat()
        return ""

    inicio = _by_patterns(
        [
            r"(?:inicio|desde|vigencia\s+desde|validez\s+desde)\s*[:\-]?\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})",
        ]
    )
    fin = _by_patterns(
        [
            r"(?:fin|hasta|vigencia\s+hasta|validez\s+hasta|v[aá]lida\s+hasta|vence)\s*[:\-]?\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})",
        ]
    )
    if inicio and fin:
        return inicio, fin
    date_hits = re.findall(r"([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})", cleaned)
    parsed_dates = []
    for raw in date_hits:
        parsed = parse_iso_date(raw)
        if parsed and parsed.isoformat() not in parsed_dates:
            parsed_dates.append(parsed.isoformat())
    if not inicio and parsed_dates:
        inicio = parsed_dates[0]
    if not fin and len(parsed_dates) > 1:
        fin = parsed_dates[-1]
    if inicio and fin and fin < inicio:
        inicio, fin = fin, inicio
    return inicio, fin


def extract_campaign_from_email(message_obj):
    subject = decode_mime_text(message_obj.get("Subject", ""))
    from_name, from_email = parseaddr(message_obj.get("From", ""))
    from_name = decode_mime_text(from_name)
    sender = " ".join(part for part in [from_name, from_email] if part).strip()

    text_parts = []
    html_parts = []
    attachment_parts = []
    primary_pdf_bytes = b""
    primary_pdf_name = ""
    if message_obj.is_multipart():
        for part in message_obj.walk():
            if part.get_content_maintype() == "multipart":
                continue
            content_type = str(part.get_content_type() or "").lower()
            filename = decode_mime_text(part.get_filename() or "")
            disposition = str(part.get("Content-Disposition") or "").lower()
            payload = part.get_payload(decode=True)
            if payload is None:
                continue
            is_attachment = ("attachment" in disposition) or bool(filename)
            is_pdf_attachment = content_type == "application/pdf" or filename.lower().endswith(".pdf")
            if is_attachment and is_pdf_attachment:
                pdf_text = extract_pdf_attachment_text(payload, max_pages=2)
                if pdf_text:
                    attachment_parts.append(pdf_text[:12000])
                if (not primary_pdf_bytes) and payload:
                    primary_pdf_bytes = payload
                    primary_pdf_name = filename or "campana.pdf"
                continue
            if is_attachment:
                continue
            charset = part.get_content_charset() or "utf-8"
            try:
                decoded = payload.decode(charset, errors="replace")
            except Exception:
                decoded = payload.decode("utf-8", errors="replace")
            if content_type == "text/plain":
                text_parts.append(decoded)
            elif content_type == "text/html":
                html_parts.append(decoded)
    else:
        payload = message_obj.get_payload(decode=True)
        if payload:
            charset = message_obj.get_content_charset() or "utf-8"
            try:
                decoded = payload.decode(charset, errors="replace")
            except Exception:
                decoded = payload.decode("utf-8", errors="replace")
            if str(message_obj.get_content_type() or "").lower() == "text/html":
                html_parts.append(decoded)
            else:
                text_parts.append(decoded)

    body = "\n".join(text_parts).strip() or html_to_text("\n".join(html_parts))
    attachment_text = "\n".join(attachment_parts).strip()
    search_blob = " ".join(part for part in [subject, sender, body, attachment_text] if part).strip()

    compania = detect_company_from_metadata(subject, sender, body)
    if not compania:
        compania = detect_company_from_text(search_blob)
    if not compania and from_email and "@" in from_email:
        domain = from_email.split("@", 1)[-1].lower().strip()
        domain_hits = {
            "mapfre.com": "Mapfre",
            "allianz.es": "Allianz",
            "axa.es": "AXA",
            "zurich.com": "Zurich",
            "lineadirecta.com": "Línea Directa",
            "santalucia.es": "Santa Lucia",
            "caser.es": "Caser",
            "ocaso.es": "Ocaso",
            "generali.com": "Generali",
            "fiatc.es": "Fiatc",
            "mutua.es": "Mutua Madrileña",
            "dkv.es": "DKV",
            "adeslas.es": "Adeslas",
            "asisa.es": "Asisa",
            "sanitas.es": "Sanitas",
        }
        for key, name in domain_hits.items():
            if domain == key or domain.endswith(f".{key}"):
                compania = name
                break
    ramo = detect_campaign_ramo(search_blob) or canonicalize_ramo(search_blob)
    if not ramo:
        ramo_match = re.search(r"\bramo\s*[:\-]?\s*([A-Za-zÁÉÍÓÚÜÑñçÇ\s]{3,40})", body or "", re.IGNORECASE)
        if ramo_match:
            ramo = canonicalize_ramo(ramo_match.group(1))
    fecha_inicio, fecha_fin = parse_campaign_dates(search_blob)

    precio_base = 0.0
    comision_pct = 0.0
    comision_fija = 0.0
    price_match = re.search(
        r"(?:precio|prima|tarifa|cuota|desde)\s*(?:base)?\s*[:\-]?\s*([0-9][0-9.,]{0,14})\s*€?",
        search_blob,
        re.IGNORECASE,
    )
    if price_match:
        precio_base = parse_decimal_amount(price_match.group(1))
    pct_match = re.search(
        r"(?:comisi[oó]n|brokerage|mediaci[oó]n)[^%\n\r]{0,24}([0-9]{1,2}(?:[.,][0-9]{1,2})?)\s*%",
        search_blob,
        re.IGNORECASE,
    )
    if pct_match:
        comision_pct = parse_decimal_amount(pct_match.group(1))
    fijo_match = re.search(
        r"(?:comisi[oó]n|fee|honorario)[^€\n\r]{0,24}([0-9][0-9.,]{0,14})\s*€",
        search_blob,
        re.IGNORECASE,
    )
    if fijo_match:
        comision_fija = parse_decimal_amount(fijo_match.group(1))

    url_match = re.search(r"(https?://[^\s<>\"]+)", search_blob, re.IGNORECASE)
    url = (url_match.group(1).rstrip(").,;]") if url_match else "")
    campaign_name = re.sub(r"^(RE|RV|FW|FWD)\s*:\s*", "", subject, flags=re.IGNORECASE).strip()
    if not campaign_name:
        campaign_name = f"Campaña correo {datetime.now().strftime('%Y-%m-%d')}"
    if compania and campaign_name.lower() in {"campaña", "campana", "campaña correo"}:
        campaign_name = f"Campaña {compania}"
    description = re.sub(r"\s+", " ", body).strip()
    if len(description) < 20:
        fallback_desc = " · ".join(part for part in [f"Asunto: {subject}" if subject else "", f"Remitente: {sender}" if sender else ""] if part)
        description = fallback_desc or description
    if len(description) < 40 and attachment_text:
        attachment_summary = re.sub(r"\s+", " ", attachment_text).strip()
        if len(attachment_summary) > 500:
            attachment_summary = f"{attachment_summary[:497]}..."
        description = f"{description} · PDF: {attachment_summary}".strip(" ·")
    if len(description) > 700:
        description = f"{description[:697]}..."

    quality = 0
    if compania:
        quality += 1
    if ramo:
        quality += 1
    if url:
        quality += 1
    if abs(precio_base) > 0.0001 or abs(comision_pct) > 0.0001 or abs(comision_fija) > 0.0001:
        quality += 1
    if description and len(description) >= 40:
        quality += 1

    return {
        "compania": normalize_company_name(compania),
        "nombre": campaign_name,
        "ramo": ramo or "",
        "origen": "Correo",
        "fecha_inicio": fecha_inicio,
        "fecha_fin": fecha_fin,
        "descripcion": description,
        "url": url,
        "precio_base": round(precio_base, 2) if abs(precio_base) > 0.0001 else None,
        "comision_pct": round(comision_pct, 2) if abs(comision_pct) > 0.0001 else None,
        "comision_fija": round(comision_fija, 2) if abs(comision_fija) > 0.0001 else None,
        "remitente": sender,
        "quality": quality,
        "adjunto_bytes": primary_pdf_bytes,
        "adjunto_nombre": primary_pdf_name,
    }


def import_campaigns_from_mailbox(conn, payload, now):
    host = (payload.get("host") or os.environ.get("CAMPAIGN_IMAP_HOST") or os.environ.get("IMAP_HOST") or "").strip()
    user = (payload.get("user") or os.environ.get("CAMPAIGN_IMAP_USER") or os.environ.get("IMAP_USER") or "").strip()
    password = str(payload.get("password") or os.environ.get("CAMPAIGN_IMAP_PASS") or os.environ.get("IMAP_PASS") or "").strip()
    mailbox = str(payload.get("mailbox") or os.environ.get("CAMPAIGN_IMAP_MAILBOX") or "INBOX").strip() or "INBOX"
    search = str(payload.get("search") or os.environ.get("CAMPAIGN_IMAP_SEARCH") or "UNSEEN").strip() or "UNSEEN"
    ssl_enabled = str(payload.get("ssl") or os.environ.get("CAMPAIGN_IMAP_SSL") or "1").strip().lower() not in ("0", "false", "no", "off")
    mark_seen = str(payload.get("mark_seen") or "1").strip().lower() not in ("0", "false", "no", "off")
    try:
        port = int(str(payload.get("port") or os.environ.get("CAMPAIGN_IMAP_PORT") or (993 if ssl_enabled else 143)).strip())
    except Exception:
        port = 993 if ssl_enabled else 143
    try:
        limit = max(1, min(50, int(str(payload.get("limit") or "20").strip() or "20")))
    except Exception:
        limit = 20
    if not host or not user or not password:
        raise RuntimeError("Configura host, usuario y contraseña IMAP.")

    if ssl_enabled:
        mail = imaplib.IMAP4_SSL(host, port)
    else:
        mail = imaplib.IMAP4(host, port)
        mail.starttls()
    created = 0
    skipped = 0
    errors = []
    preview = []
    try:
        mail.login(user, password)
        status, _ = mail.select(mailbox, readonly=False)
        if status != "OK":
            raise RuntimeError(f"No se pudo abrir el buzón '{mailbox}'.")
        status, data = mail.search(None, search)
        if status != "OK":
            raise RuntimeError(f"No se pudo ejecutar búsqueda IMAP '{search}'.")
        raw_ids = [token for token in (data[0] or b"").split() if token]
        if not raw_ids:
            return {"created": 0, "skipped": 0, "preview": []}
        for seq_id in raw_ids[-limit:]:
            try:
                fetch_status, msg_data = mail.fetch(seq_id, "(UID BODY.PEEK[])")
                if fetch_status != "OK" or not msg_data:
                    skipped += 1
                    continue
                raw_message = None
                imap_uid = ""
                for item in msg_data:
                    if not isinstance(item, tuple) or len(item) < 2:
                        continue
                    meta = item[0] if isinstance(item[0], (bytes, bytearray)) else b""
                    body_bytes = item[1]
                    if body_bytes and raw_message is None:
                        raw_message = body_bytes
                    uid_match = re.search(rb"UID\s+(\d+)", meta or b"")
                    if uid_match:
                        imap_uid = uid_match.group(1).decode("utf-8", errors="ignore")
                if not raw_message:
                    skipped += 1
                    continue
                msg = email.message_from_bytes(raw_message)
                subject = decode_mime_text(msg.get("Subject", ""))
                sender = decode_mime_text(msg.get("From", ""))
                date_header = str(msg.get("Date") or "").strip()
                message_id = str(msg.get("Message-ID") or "").strip()
                seq_label = seq_id.decode("utf-8", errors="ignore") if isinstance(seq_id, (bytes, bytearray)) else str(seq_id)
                fingerprint = f"{subject}|{sender}|{date_header}|{imap_uid or seq_label}"
                dedupe_key = message_id or f"sha1:{hashlib.sha1(fingerprint.encode('utf-8')).hexdigest()}"
                seen = conn.execute(
                    "SELECT 1 FROM seguros_campanas_mail_seen WHERE message_id = ? LIMIT 1",
                    (dedupe_key,),
                ).fetchone()
                if seen:
                    skipped += 1
                    if mark_seen:
                        try:
                            mail.store(seq_id, "+FLAGS", "(\\Seen)")
                        except Exception:
                            pass
                    continue
                parsed = extract_campaign_from_email(msg)
                if int(parsed.get("quality") or 0) < 2:
                    skipped += 1
                    conn.execute(
                        """
                        INSERT INTO seguros_campanas_mail_seen (
                          id, message_id, mailbox_uid, remitente, asunto, fecha_mail, campaign_id, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
                        """,
                        (
                            os.urandom(16).hex(),
                            dedupe_key,
                            imap_uid,
                            parsed.get("remitente") or sender,
                            f"[IGNORADO BAJA_CALIDAD] {subject}",
                            date_header,
                            None,
                            now,
                        ),
                    )
                    continue
                campaign_id = os.urandom(16).hex()
                adjunto_url = ""
                adjunto_nombre = ""
                adjunto_bytes = parsed.get("adjunto_bytes") or b""
                if adjunto_bytes:
                    try:
                        adjunto_url, adjunto_nombre = save_campaign_attachment_file(
                            adjunto_bytes,
                            parsed.get("adjunto_nombre") or f"{campaign_id}.pdf",
                        )
                    except Exception as exc:
                        if len(errors) < 5:
                            errors.append(f"Adjunto PDF no guardado ({subject}): {exc}")
                conn.execute(
                    """
                    INSERT INTO seguros_campanas (
                      id, compania, nombre, ramo, origen, fecha_inicio, fecha_fin, descripcion, url, adjunto_url, adjunto_nombre, precio_base, comision_pct, comision_fija,
                      created_at, updated_at
                    ) VALUES (
                      ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                    )
                    """,
                    (
                        campaign_id,
                        parsed.get("compania"),
                        parsed.get("nombre"),
                        canonicalize_ramo(parsed.get("ramo")) or parsed.get("ramo"),
                        parsed.get("origen") or "Correo",
                        parsed.get("fecha_inicio") or None,
                        parsed.get("fecha_fin") or None,
                        parsed.get("descripcion") or None,
                        parsed.get("url") or None,
                        adjunto_url or None,
                        adjunto_nombre or None,
                        parsed.get("precio_base"),
                        parsed.get("comision_pct"),
                        parsed.get("comision_fija"),
                        now,
                        now,
                    ),
                )
                conn.execute(
                    """
                    INSERT INTO seguros_campanas_mail_seen (
                      id, message_id, mailbox_uid, remitente, asunto, fecha_mail, campaign_id, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
                    """,
                    (
                        os.urandom(16).hex(),
                        dedupe_key,
                        imap_uid,
                        parsed.get("remitente") or sender,
                        subject,
                        date_header,
                        campaign_id,
                        now,
                    ),
                )
                created += 1
                if mark_seen:
                    try:
                        mail.store(seq_id, "+FLAGS", "(\\Seen)")
                    except Exception:
                        pass
                if len(preview) < 10:
                    preview.append(
                        {
                            "compania": parsed.get("compania") or "",
                            "nombre": parsed.get("nombre") or "",
                            "ramo": parsed.get("ramo") or "",
                        }
                    )
            except Exception as exc:
                skipped += 1
                if len(errors) < 5:
                    errors.append(str(exc))
    finally:
        try:
            mail.logout()
        except Exception:
            pass
    return {"created": created, "skipped": skipped, "preview": preview, "errors": errors}

def detect_ocr_lang():
    if os.path.isdir(TESSDATA_DIR):
        has_spa = os.path.exists(os.path.join(TESSDATA_DIR, "spa.traineddata"))
        has_eng = os.path.exists(os.path.join(TESSDATA_DIR, "eng.traineddata"))
        if has_spa and has_eng:
            return "spa+eng"
        if has_spa:
            return "spa"
        if has_eng:
            return "eng"
    return "spa+eng"


def run_subprocess(args, **kwargs):
    kwargs.setdefault("timeout", OCR_SUBPROCESS_TIMEOUT_SECONDS)
    return subprocess.run(args, **kwargs)


def is_stale_ocr_job(started_at):
    if not started_at:
        return False
    raw = str(started_at).strip()
    if not raw:
        return False
    if raw.endswith("Z"):
        raw = raw[:-1]
    try:
        started_dt = datetime.fromisoformat(raw)
    except Exception:
        return False
    if started_dt.tzinfo is None:
        started_dt = started_dt.replace(tzinfo=timezone.utc)
    return datetime.now(timezone.utc) - started_dt > timedelta(minutes=OCR_JOB_STALE_MINUTES)


def s3_config():
    bucket = os.environ.get("AWS_S3_BUCKET") or os.environ.get("S3_BUCKET") or S3_BUCKET
    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or S3_REGION
    return bucket, region

def s3_client():
    global S3_BOTO3_AVAILABLE
    try:
        import boto3
        from botocore.config import Config
    except ImportError:
        S3_BOTO3_AVAILABLE = False
        return None
    bucket, region = s3_config()
    if not bucket or not region:
        return None
    return boto3.client(
        "s3",
        region_name=region,
        config=Config(
            signature_version="s3v4",
            s3={"addressing_style": "virtual"},
        ),
    )


def s3_safe_key(prefix, filename):
    base = os.path.basename(filename or "archivo.pdf")
    safe = re.sub(r"[^A-Za-z0-9._-]", "_", base)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    rand = os.urandom(4).hex()
    prefix = prefix.strip("/").strip() if prefix else "seguros"
    return f"{prefix}/{stamp}_{rand}_{safe}"

def s3_get_object_bytes(key):
    client = s3_client()
    if not client:
        return None, "S3 no configurado"
    bucket, _region = s3_config()
    if not bucket:
        return None, "S3 sin bucket"
    try:
        obj = client.get_object(Bucket=bucket, Key=key)
        return obj["Body"].read(), ""
    except Exception as exc:
        return None, str(exc)


def decode_seguros_payload(payload):
    data_uri = payload.get("file_base64") or payload.get("data")
    s3_key = (payload.get("s3_key") or "").strip()
    pdf_bytes = None
    if s3_key:
        pdf_bytes, s3_err = s3_get_object_bytes(s3_key)
        if not pdf_bytes:
            raise ValueError(f"S3: {s3_err}")
    else:
        if not data_uri:
            raise ValueError("Archivo requerido")
        if "," in data_uri:
            data_uri = data_uri.split(",", 1)[1]
        try:
            pdf_bytes = base64.b64decode(data_uri)
        except Exception:
            raise ValueError("Base64 invalido")
    return pdf_bytes


def decode_document_payload(payload):
    data_uri = payload.get("file_base64") or payload.get("data")
    s3_key = (payload.get("s3_key") or "").strip()
    raw_bytes = None
    mime = ""
    filename = str(payload.get("filename") or "").strip()
    if s3_key:
        raw_bytes, s3_err = s3_get_object_bytes(s3_key)
        if not raw_bytes:
            raise ValueError(f"S3: {s3_err}")
        lower_key = s3_key.lower()
        if lower_key.endswith(".pdf"):
            mime = "application/pdf"
        elif lower_key.endswith((".jpg", ".jpeg")):
            mime = "image/jpeg"
        elif lower_key.endswith(".png"):
            mime = "image/png"
    else:
        if not data_uri:
            raise ValueError("Archivo requerido")
        if "," in data_uri:
            header, data_uri = data_uri.split(",", 1)
            if header.startswith("data:") and ";base64" in header:
                mime = header.split(":", 1)[1].split(";", 1)[0]
        try:
            raw_bytes = base64.b64decode(data_uri)
        except Exception:
            raise ValueError("Base64 invalido")
    if not raw_bytes:
        raise ValueError("Archivo vacio")
    source_hint = " ".join(
        [
            filename,
            str(payload.get("source_hint") or ""),
            s3_key,
        ]
    ).strip()
    return raw_bytes, mime, source_hint


def parse_decimal_eu(value):
    raw = str(value or "").strip()
    if not raw:
        return 0.0
    raw = raw.replace("€", "").replace("EUR", "").replace(" ", "")
    if "," in raw and "." in raw:
        if raw.rfind(",") > raw.rfind("."):
            raw = raw.replace(".", "").replace(",", ".")
        else:
            raw = raw.replace(",", "")
    elif "," in raw:
        raw = raw.replace(".", "").replace(",", ".")
    raw = re.sub(r"[^0-9.\-]", "", raw)
    if raw in ("", ".", "-", "-."):
        return 0.0
    try:
        return float(raw)
    except Exception:
        return 0.0


def extract_invoice_amount(text, labels):
    if not text:
        return 0.0
    for label in labels:
        pattern = rf"{label}\s*[:\-]?\s*([0-9][0-9\.\,\s€]*)"
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            value = parse_decimal_eu(match.group(1))
            if value > 0:
                return value
    return 0.0


def parse_invoice_text(text):
    raw = str(text or "")
    upper = normalize_lookup_text(raw)
    if not raw.strip():
        return {}
    numero = ""
    numero_match = re.search(
        r"(?:factura|fra\.?|n[úu]m(?:ero)?|n[º°])\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/\.]{2,})",
        raw,
        re.IGNORECASE,
    )
    if numero_match:
        numero = numero_match.group(1).strip()
    fecha = ""
    fecha_match = re.search(r"\b(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})\b", raw)
    if fecha_match:
        fecha = fecha_match.group(1).strip()
    fecha_iso = ""
    if fecha:
        date_bits = re.split(r"[\/\-]", fecha)
        if len(date_bits) == 3:
            day, month, year = date_bits
            if len(year) == 2:
                year = f"20{year}"
            try:
                fecha_iso = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            except Exception:
                fecha_iso = ""
    nif_candidates = re.findall(
        r"\b(?:[ABCDEFGHJNPQRSUVW]\d{7}[0-9A-J]|\d{8}[A-Z])\b",
        upper,
        re.IGNORECASE,
    )
    nif = nif_candidates[0].upper() if nif_candidates else ""
    tercero = ""
    for pattern in (
        r"(?:proveedor|acreedor)\s*[:\-]\s*([^\n\r]{3,80})",
        r"(?:raz[oó]n social)\s*[:\-]\s*([^\n\r]{3,80})",
        r"(?:cliente)\s*[:\-]\s*([^\n\r]{3,80})",
    ):
        m = re.search(pattern, raw, re.IGNORECASE)
        if m:
            tercero = m.group(1).strip(" .;:")
            break
    tipo = "compra"
    if any(token in upper for token in ("FACTURA EMITIDA", "TOTAL A COBRAR", "CLIENTE")):
        tipo = "venta"
    base = extract_invoice_amount(raw, ["base imponible", "subtotal", "base"])
    cuota_iva = extract_invoice_amount(raw, ["cuota iva", "iva", "i\\.v\\.a\\."])
    cuota_irpf = extract_invoice_amount(raw, ["retencion", "irpf"])
    total = extract_invoice_amount(raw, ["total factura", "importe total", "total a pagar", "total"])
    if base <= 0 and total > 0:
        base = max(0.0, total - cuota_iva + cuota_irpf)
    if total <= 0 and base > 0:
        total = max(0.0, base + cuota_iva - cuota_irpf)
    iva_pct = 0.0
    pct_match = re.search(r"\b(4|10|21)(?:[.,]0+)?\s*%\b", raw)
    if pct_match:
        iva_pct = parse_decimal_eu(pct_match.group(1))
    elif base > 0 and cuota_iva > 0:
        iva_pct = round((cuota_iva / base) * 100.0, 2)
    descripcion = numero or "Factura"
    if tercero:
        descripcion = f"{descripcion} · {tercero}"
    return {
        "numero": numero,
        "fecha": fecha_iso,
        "nif": nif,
        "tercero": tercero,
        "tipo": tipo,
        "base_imponible": round(base, 2),
        "cuota_iva": round(cuota_iva, 2),
        "cuota_irpf": round(cuota_irpf, 2),
        "total": round(total, 2),
        "iva_pct": iva_pct,
        "descripcion": descripcion,
        "raw_text": raw.strip(),
    }


def infer_expense_account(concepto):
    text = normalize_lookup_text(concepto or "")
    mapping = [
        ("ALQUILER", "621"),
        ("ARRENDAMIENTO", "621"),
        ("REPARACION", "622"),
        ("CONSERVACION", "622"),
        ("PROFESIONAL", "623"),
        ("HONORARIO", "623"),
        ("TRANSPORTE", "624"),
        ("SEGURO", "625"),
        ("BANC", "626"),
        ("PUBLICIDAD", "627"),
        ("SUMINISTRO", "628"),
        ("LUZ", "628"),
        ("AGUA", "628"),
        ("TELEFON", "628"),
        ("INTERNET", "628"),
        ("TRIBUTO", "631"),
        ("IMPUESTO", "631"),
    ]
    for token, account in mapping:
        if token in text:
            return account
    return "629"


def infer_revenue_account(concepto):
    text = normalize_lookup_text(concepto or "")
    if "ALQUILER" in text:
        return "705"
    return "700"


def ensure_gestoria_tercero(conn, empresa_id, nif, nombre, tipo, now):
    nif_clean = (nif or "").strip().upper()
    name_clean = (nombre or "").strip()
    kind = (tipo or "").strip().lower() or "proveedor"
    account_map = {"proveedor": "400", "acreedor": "410", "cliente": "430"}
    account = account_map.get(kind, "400")
    row = None
    if name_clean:
        row = conn.execute(
            "SELECT id, cuenta_contable, nombre, nif FROM gestoria_terceros WHERE empresa_id = ? AND UPPER(COALESCE(nombre,'')) = UPPER(?) LIMIT 1",
            (empresa_id, name_clean),
        ).fetchone()
    if not row and nif_clean:
        nif_row = conn.execute(
            "SELECT id, cuenta_contable, nombre, nif FROM gestoria_terceros WHERE empresa_id = ? AND UPPER(COALESCE(nif,'')) = ? LIMIT 1",
            (empresa_id, nif_clean),
        ).fetchone()
        if nif_row:
            existing_name = normalize_lookup_text(nif_row["nombre"] or "")
            current_name = normalize_lookup_text(name_clean or "")
            if existing_name and current_name and existing_name != current_name:
                nif_clean = ""
            else:
                row = nif_row
    if row:
        conn.execute(
            """
            UPDATE gestoria_terceros
            SET nif = COALESCE(NULLIF(?, ''), nif),
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = ?,
                cuenta_contable = COALESCE(NULLIF(cuenta_contable, ''), ?),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (nif_clean, name_clean, kind, account, now, row["id"]),
        )
        return row["id"], row["cuenta_contable"] or account
    tercero_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_terceros (
          id, empresa_id, nif, nombre, tipo, cuenta_contable, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
        """,
        (tercero_id, empresa_id, nif_clean, name_clean, kind, account, now, now),
    )
    return tercero_id, account


def build_invoice_asiento(parsed, counterpart_account):
    tipo = (parsed.get("tipo") or "compra").strip().lower()
    base = float(parsed.get("base_imponible") or 0.0)
    iva = float(parsed.get("cuota_iva") or 0.0)
    irpf = float(parsed.get("cuota_irpf") or 0.0)
    total = float(parsed.get("total") or 0.0)
    concepto = parsed.get("descripcion") or parsed.get("numero") or "Factura"
    lines = []
    if tipo == "venta":
        ingreso = infer_revenue_account(concepto)
        if total > 0:
            lines.append({"cuenta": counterpart_account or "430", "descripcion": "Cliente", "debe": round(total, 2), "haber": 0.0})
        if base > 0:
            lines.append({"cuenta": ingreso, "descripcion": "Ingreso", "debe": 0.0, "haber": round(base, 2)})
        if iva > 0:
            lines.append({"cuenta": "477", "descripcion": "IVA repercutido", "debe": 0.0, "haber": round(iva, 2), "impuesto": "IVA", "porcentaje": parsed.get("iva_pct") or 0.0})
    else:
        gasto = infer_expense_account(concepto)
        if base > 0:
            lines.append({"cuenta": gasto, "descripcion": "Gasto", "debe": round(base, 2), "haber": 0.0})
        if iva > 0:
            lines.append({"cuenta": "472", "descripcion": "IVA soportado", "debe": round(iva, 2), "haber": 0.0, "impuesto": "IVA", "porcentaje": parsed.get("iva_pct") or 0.0})
        if irpf > 0:
            lines.append({"cuenta": "4751", "descripcion": "H.P. acreedora retenciones", "debe": 0.0, "haber": round(irpf, 2), "impuesto": "IRPF", "porcentaje": 0.0})
        payable = total if total > 0 else max(0.0, base + iva - irpf)
        if payable > 0:
            lines.append({"cuenta": counterpart_account or "400", "descripcion": "Proveedor/Acreedor", "debe": 0.0, "haber": round(payable, 2)})
    debe = round(sum(float(item.get("debe") or 0.0) for item in lines), 2)
    haber = round(sum(float(item.get("haber") or 0.0) for item in lines), 2)
    return lines, debe, haber


def normalize_import_review_state(value):
    state = normalize_lookup_text(value or "")
    if state in {"OK", "VALIDADO", "APROBADO"}:
        return "OK"
    if state in {"DUPLICADO", "DUPLICATE"}:
        return "DUPLICADO"
    if state in {"ERROR", "ERR"}:
        return "ERROR"
    if state in {"REVISAR", "REVISION", "PENDIENTE", "PENDIENTE REVISION"}:
        return "REVISAR"
    return "REVISAR"


def normalize_import_reasons(value):
    if isinstance(value, (list, tuple, set)):
        items = [str(item or "").strip() for item in value]
        return ",".join(item for item in items if item)
    return str(value or "").strip()


def parse_confidence_value(value):
    if value in (None, ""):
        return 0.0
    try:
        parsed = float(value)
    except Exception:
        parsed = parse_money_value(value)
    if parsed < 0:
        return 0.0
    if parsed > 1:
        return 1.0 if parsed <= 100 else parsed
    return round(parsed, 4)


