def import_number_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return False
    if token in {"PAGADO", "EMITIDA", "CALLE", "SIMPLIFICADA", "FACTURA", "GAPP", "ORIGINAL"}:
        return True
    if not any(ch.isdigit() for ch in token):
        return True
    if re.fullmatch(r"\d{1,2}", token):
        return True
    if re.fullmatch(r"\d{4}", token):
        return True
    return False


def import_vendor_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return True
    if token in {"Q", "QO", "ORIGINAL", "PAGADO", "EMITIDA", "MES FEBRERO"}:
        return True
    letters = re.sub(r"[^A-Z]", "", token)
    if len(letters) <= 2:
        return True
    return False


def import_vat_is_implausible(base, cuota_iva, total):
    base = float(base or 0.0)
    cuota_iva = float(cuota_iva or 0.0)
    total = float(total or 0.0)
    if cuota_iva < 0:
        return True
    if cuota_iva <= 0:
        return False
    if total > 0 and cuota_iva > total + 0.01:
        return True
    if base > 0:
        if cuota_iva / max(base, 0.01) > 0.30:
            return True
        if total > 0 and abs((base + cuota_iva) - total) > max(1.0, total * 0.15):
            return True
    return False


def validate_import_document_for_apply(document_row):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = []
    categoria = str(document_row.get("categoria_detectada") or "").strip()
    tipo = str(document_row.get("tipo_detectado") or "compra").strip().lower()
    numero = str(document_row.get("numero_detectado") or "").strip()
    tercero = str(document_row.get("tercero_detectado") or "").strip()
    base = parse_money_value(document_row.get("base_detectada"))
    cuota_iva = parse_money_value(document_row.get("cuota_iva_detectada"))
    total = parse_money_value(document_row.get("total_detectado"))
    if import_category_is_expense(categoria) and tipo == "venta":
        reasons.append("tipo_venta_en_gasto")
    if total <= 0 and base <= 0:
        reasons.append("importe_invalido")
    if import_vat_is_implausible(base, cuota_iva, total):
        reasons.append("iva_inverosimil")
    if import_number_is_suspicious(numero):
        reasons.append("numero_dudoso")
    if import_vendor_is_suspicious(tercero):
        reasons.append("proveedor_dudoso")
    return reasons


def describe_import_record(record):
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    archivo = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    concept_parts = [part for part in (numero, tercero or categoria or archivo) if part]
    return " · ".join(concept_parts) or "Factura importada"


def ensure_gestoria_import_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_lotes (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          origen TEXT,
          estado TEXT NOT NULL,
          periodo TEXT,
          carpeta_origen TEXT,
          template_path TEXT,
          total_documentos INTEGER NOT NULL DEFAULT 0,
          total_ok INTEGER NOT NULL DEFAULT 0,
          total_revisar INTEGER NOT NULL DEFAULT 0,
          total_duplicado INTEGER NOT NULL DEFAULT 0,
          total_error INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_documentos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          factura_id TEXT,
          tercero_id TEXT,
          gestoria_doc_id TEXT,
          archivo_nombre TEXT NOT NULL,
          archivo_hash TEXT,
          doc_key TEXT,
          numero_detectado TEXT,
          fecha_detectada TEXT,
          tercero_detectado TEXT,
          nif_detectado TEXT,
          base_detectada REAL,
          cuota_iva_detectada REAL,
          total_detectado REAL,
          tipo_detectado TEXT,
          categoria_detectada TEXT,
          subcategoria_detectada TEXT,
          cuenta_sugerida TEXT,
          cuenta_tercero_sugerida TEXT,
          confianza_categoria REAL,
          confianza_extraccion REAL,
          estado_revision TEXT NOT NULL,
          motivos_revision TEXT,
          regla_aplicada TEXT,
          ocr_metodo TEXT,
          ocr_error TEXT,
          raw_text TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id),
          FOREIGN KEY (tercero_id) REFERENCES gestoria_terceros(id),
          FOREIGN KEY (gestoria_doc_id) REFERENCES gestoria_docs(id)
        )
        """
    )
    conn.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS idx_gestoria_import_documentos_lote_archivo
        ON gestoria_import_documentos (lote_id, archivo_nombre)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_estado
        ON gestoria_import_documentos (estado_revision)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_hash
        ON gestoria_import_documentos (archivo_hash)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_reglas (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          ambito TEXT NOT NULL,
          prioridad INTEGER NOT NULL DEFAULT 100,
          activo INTEGER NOT NULL DEFAULT 1,
          proveedor_match TEXT,
          proveedor_nif_match TEXT,
          texto_match TEXT,
          categoria_forzada TEXT,
          tercero_nombre_forzado TEXT,
          tercero_nif_forzado TEXT,
          cuenta_gasto_forzada TEXT,
          cuenta_tercero_forzada TEXT,
          iva_pct_forzado REAL,
          auto_ok INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_reglas_scope
        ON gestoria_import_reglas (empresa_id, cliente_id, activo, prioridad)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_eventos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          documento_id TEXT,
          factura_id TEXT,
          tipo TEXT NOT NULL,
          detalle TEXT,
          payload_json TEXT,
          created_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (documento_id) REFERENCES gestoria_import_documentos(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_eventos_lote
        ON gestoria_import_eventos (lote_id, created_at)
        """
    )


def log_gestoria_import_event(conn, lote_id, tipo, now, documento_id=None, factura_id=None, detalle=None, payload=None):
    conn.execute(
        """
        INSERT INTO gestoria_import_eventos (
          id, lote_id, documento_id, factura_id, tipo, detalle, payload_json, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            lote_id,
            documento_id,
            factura_id,
            tipo,
            detalle,
            json.dumps(payload, ensure_ascii=False) if payload is not None else None,
            now,
        ),
    )


def refresh_gestoria_import_lote_totals(conn, lote_id, now):
    summary = conn.execute(
        """
        SELECT
          COUNT(*) AS total_documentos,
          SUM(CASE WHEN estado_revision = 'OK' THEN 1 ELSE 0 END) AS total_ok,
          SUM(CASE WHEN estado_revision = 'REVISAR' THEN 1 ELSE 0 END) AS total_revisar,
          SUM(CASE WHEN estado_revision = 'DUPLICADO' THEN 1 ELSE 0 END) AS total_duplicado,
          SUM(CASE WHEN estado_revision = 'ERROR' THEN 1 ELSE 0 END) AS total_error
        FROM gestoria_import_documentos
        WHERE lote_id = ?
        """,
        (lote_id,),
    ).fetchone()
    if not summary:
        summary = {
            "total_documentos": 0,
            "total_ok": 0,
            "total_revisar": 0,
            "total_duplicado": 0,
            "total_error": 0,
        }
    total_ok = int(summary["total_ok"] or 0)
    total_revisar = int(summary["total_revisar"] or 0)
    total_duplicado = int(summary["total_duplicado"] or 0)
    total_error = int(summary["total_error"] or 0)
    if total_error > 0:
        estado = "con_errores"
    elif total_revisar > 0:
        estado = "pendiente_revision"
    elif total_ok > 0:
        estado = "preparado"
    else:
        estado = "vacio"
    conn.execute(
        """
        UPDATE gestoria_import_lotes
        SET total_documentos = ?,
            total_ok = ?,
            total_revisar = ?,
            total_duplicado = ?,
            total_error = ?,
            estado = ?,
            updated_at = datetime(?)
        WHERE id = ?
        """,
        (
            int(summary["total_documentos"] or 0),
            total_ok,
            total_revisar,
            total_duplicado,
            total_error,
            estado,
            now,
            lote_id,
        ),
    )
    row = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
    return dict(row) if row else None


def upsert_gestoria_import_document(conn, lote_id, empresa_id, default_cliente_id, record, now):
    archivo_nombre = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    if not archivo_nombre:
        raise ValueError("archivo_nombre requerido")
    existing = conn.execute(
        """
        SELECT id, factura_id, tercero_id, gestoria_doc_id, created_at
        FROM gestoria_import_documentos
        WHERE lote_id = ? AND archivo_nombre = ?
        LIMIT 1
        """,
        (lote_id, archivo_nombre),
    ).fetchone()
    document_id = existing["id"] if existing else os.urandom(16).hex()
    cliente_id = str(record.get("cliente_id") or default_cliente_id or "").strip() or None
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    tipo = str(record.get("tipo_detectado") or record.get("tipo") or "compra").strip().lower() or "compra"
    estado = normalize_import_review_state(record.get("estado_revision"))
    motivos = normalize_import_reasons(record.get("motivos_revision"))
    cuenta_sugerida = str(record.get("cuenta_sugerida") or "").strip() or map_import_category_to_account(categoria)
    cuenta_tercero = str(record.get("cuenta_tercero_sugerida") or "").strip()
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    fecha = str(record.get("fecha_detectada") or record.get("fecha") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    nif = str(record.get("nif_detectado") or record.get("nif") or "").strip().upper()
    base = round(parse_money_value(record.get("base_detectada") if "base_detectada" in record else record.get("base_imponible")), 2)
    cuota_iva = round(parse_money_value(record.get("cuota_iva_detectada") if "cuota_iva_detectada" in record else record.get("cuota_iva")), 2)
    total = round(parse_money_value(record.get("total_detectado") if "total_detectado" in record else record.get("total")), 2)
    if total <= 0:
        total = round(parse_money_value(record.get("importe_agregado")), 2)
    confianza_categoria = parse_confidence_value(record.get("confianza_categoria"))
    confianza_extraccion = parse_confidence_value(record.get("confianza_extraccion"))
    if confianza_extraccion <= 0:
        confianza_extraccion = 1.0 if total > 0 else 0.0
    raw_text = str(record.get("raw_text") or record.get("descripcion") or "").strip()
    values = (
        document_id,
        lote_id,
        empresa_id,
        cliente_id,
        existing["factura_id"] if existing else None,
        existing["tercero_id"] if existing else None,
        existing["gestoria_doc_id"] if existing else None,
        archivo_nombre,
        str(record.get("archivo_hash") or "").strip() or None,
        str(record.get("doc_key") or "").strip() or None,
        numero or None,
        fecha or None,
        tercero or None,
        nif or None,
        base,
        cuota_iva,
        total,
        tipo,
        categoria or None,
        str(record.get("subcategoria_detectada") or record.get("subcategoria") or "").strip() or None,
        cuenta_sugerida or None,
        cuenta_tercero or None,
        confianza_categoria,
        confianza_extraccion,
        estado,
        motivos or None,
        str(record.get("regla_aplicada") or record.get("motivo_categoria") or "").strip() or None,
        str(record.get("ocr_metodo") or "").strip() or None,
        str(record.get("ocr_error") or "").strip() or None,
        raw_text or None,
        existing["created_at"] if existing else now,
        now,
    )
    conn.execute(
        """
        INSERT OR REPLACE INTO gestoria_import_documentos (
          id, lote_id, empresa_id, cliente_id, factura_id, tercero_id, gestoria_doc_id,
          archivo_nombre, archivo_hash, doc_key, numero_detectado, fecha_detectada,
          tercero_detectado, nif_detectado, base_detectada, cuota_iva_detectada,
          total_detectado, tipo_detectado, categoria_detectada, subcategoria_detectada,
          cuenta_sugerida, cuenta_tercero_sugerida, confianza_categoria, confianza_extraccion,
          estado_revision, motivos_revision, regla_aplicada, ocr_metodo, ocr_error, raw_text,
          created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        values,
    )
    return document_id


def apply_gestoria_import_document(conn, document_row, now):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = validate_import_document_for_apply(document_row)
    if reasons:
        raise ValueError(",".join(reasons))
    tipo = str(document_row["tipo_detectado"] or "compra").strip().lower() or "compra"
    numero = str(document_row["numero_detectado"] or "").strip()
    fecha = str(document_row["fecha_detectada"] or "").strip() or datetime.now().strftime("%Y-%m-%d")
    tercero_nombre = str(document_row["tercero_detectado"] or "").strip() or str(document_row["archivo_nombre"] or "").strip()
    tercero_nif = str(document_row["nif_detectado"] or "").strip().upper()
    categoria = str(document_row["categoria_detectada"] or "").strip()
    descripcion = describe_import_record(document_row)
    base = round(parse_money_value(document_row["base_detectada"]), 2)
    cuota_iva = round(parse_money_value(document_row["cuota_iva_detectada"]), 2)
    total = round(parse_money_value(document_row["total_detectado"]), 2)
    if total <= 0 and base > 0 and cuota_iva > 0:
        total = round(base + cuota_iva, 2)
    if base <= 0 and total > 0 and cuota_iva > 0:
        base = round(max(0.0, total - cuota_iva), 2)
    iva_pct = 0.0
    if base > 0 and cuota_iva > 0:
        iva_pct = round((cuota_iva / base) * 100.0, 2)
    third_type = "cliente" if tipo == "venta" else ("proveedor" if numero else "acreedor")
    tercero_id, counterpart_account = ensure_gestoria_tercero(
        conn,
        document_row["empresa_id"],
        tercero_nif,
        tercero_nombre,
        third_type,
        now,
    )
    if document_row["cuenta_tercero_sugerida"]:
        counterpart_account = str(document_row["cuenta_tercero_sugerida"]).strip() or counterpart_account
        conn.execute(
            """
            UPDATE gestoria_terceros
            SET cuenta_contable = COALESCE(NULLIF(?, ''), cuenta_contable),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (counterpart_account, now, tercero_id),
        )
    concepto = descripcion
    if categoria and categoria not in normalize_lookup_text(concepto):
        concepto = f"{concepto} · {categoria}" if concepto else categoria
    parsed_factura = {
        "tipo": tipo,
        "numero": numero,
        "fecha": fecha,
        "nif": tercero_nif,
        "tercero": tercero_nombre,
        "base_imponible": base,
        "cuota_iva": cuota_iva,
        "cuota_irpf": 0.0,
        "total": total,
        "iva_pct": iva_pct,
        "descripcion": concepto,
        "raw_text": document_row["raw_text"] or "",
    }
    lines, total_debe, total_haber = build_invoice_asiento(parsed_factura, counterpart_account)
    forced_account = str(document_row["cuenta_sugerida"] or "").strip() or map_import_category_to_account(categoria)
    if forced_account:
        for item in lines:
            cuenta = str(item.get("cuenta") or "").strip()
            if tipo == "venta":
                if cuenta.startswith("7"):
                    item["cuenta"] = forced_account
            else:
                if cuenta.startswith("6"):
                    item["cuenta"] = forced_account
    factura_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_facturas (
          id, empresa_id, cliente_id, tercero_id, tipo, numero, fecha_emision, descripcion,
          base_imponible, cuota_iva, cuota_irpf, total, iva_pct, estado_ocr, doc_key, raw_text,
          import_documento_id, origen_importacion, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            factura_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            tercero_id,
            tipo,
            numero or None,
            fecha,
            concepto,
            base,
            cuota_iva,
            0.0,
            total,
            iva_pct,
            "importado",
            document_row["doc_key"],
            document_row["raw_text"],
            document_row["id"],
            "gestoria_import",
            now,
            now,
        ),
    )
    asiento_id = os.urandom(16).hex()
    referencia = numero or factura_id
    conn.execute(
        """
        INSERT INTO gestoria_asientos (
          id, empresa_id, cliente_id, factura_id, fecha, concepto, diario, referencia,
          total_debe, total_haber, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            asiento_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            factura_id,
            fecha,
            concepto,
            "FACT",
            referencia,
            total_debe,
            total_haber,
            now,
            now,
        ),
    )
    for item in lines:
        conn.execute(
            """
            INSERT INTO gestoria_asiento_lineas (
              id, asiento_id, tercero_id, cuenta, descripcion, debe, haber,
              impuesto_tipo, impuesto_pct, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                asiento_id,
                tercero_id,
                item.get("cuenta"),
                item.get("descripcion"),
                item.get("debe") or 0.0,
                item.get("haber") or 0.0,
                item.get("impuesto"),
                item.get("porcentaje"),
                now,
                now,
            ),
        )
    conn.execute(
        """
        INSERT INTO gestoria_contabilidad (
          id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            document_row["empresa_id"],
            document_row["cliente_id"],
            json.dumps([document_row["cliente_id"]], ensure_ascii=False) if document_row["cliente_id"] else None,
            fecha,
            concepto,
            "Contable",
            "Ingreso" if tipo == "venta" else "Gasto",
            total,
            f"Importador facturas · lote {document_row['lote_id']} · documento {document_row['id']} · asiento {asiento_id}",
            now,
            now,
        ),
    )
    conn.execute(
        """
        UPDATE gestoria_import_documentos
        SET factura_id = ?, tercero_id = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        (factura_id, tercero_id, now, document_row["id"]),
    )
    return {
        "factura_id": factura_id,
        "asiento_id": asiento_id,
        "tercero_id": tercero_id,
        "lineas": lines,
        "totales": {"debe": total_debe, "haber": total_haber},
    }


def apply_gestoria_import_lote(conn, lote_id, empresa_id, now, limit=None):
    sql = """
        SELECT *
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        ORDER BY fecha_detectada ASC, created_at ASC
    """
    values = [lote_id, empresa_id]
    if limit:
        sql += " LIMIT ?"
        values.append(int(limit))
    rows = conn.execute(sql, values).fetchall()
    applied = []
    errors = []
    for row in rows:
        try:
            result = apply_gestoria_import_document(conn, row, now)
            applied.append({"documento_id": row["id"], **result})
            log_gestoria_import_event(
                conn,
                lote_id,
                "aplicado",
                now,
                documento_id=row["id"],
                factura_id=result["factura_id"],
                detalle="Documento aplicado a factura/asiento",
                payload={"archivo_nombre": row["archivo_nombre"], "factura_id": result["factura_id"], "asiento_id": result["asiento_id"]},
            )
        except Exception as exc:
            conn.execute(
                """
                UPDATE gestoria_import_documentos
                SET estado_revision = 'ERROR',
                    motivos_revision = COALESCE(NULLIF(TRIM(COALESCE(motivos_revision, '') || ',error_aplicacion'), ''), 'error_aplicacion'),
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (now, row["id"]),
            )
            errors.append({"documento_id": row["id"], "archivo_nombre": row["archivo_nombre"], "error": str(exc)})
            log_gestoria_import_event(
                conn,
                lote_id,
                "error_aplicacion",
                now,
                documento_id=row["id"],
                detalle=str(exc),
                payload={"archivo_nombre": row["archivo_nombre"]},
            )
    lote = refresh_gestoria_import_lote_totals(conn, lote_id, now)
    pending_ok = conn.execute(
        """
        SELECT COUNT(*) AS n
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        """,
        (lote_id, empresa_id),
    ).fetchone()
    pending_ok_count = int((pending_ok["n"] if pending_ok else 0) or 0)
    if lote and pending_ok_count == 0 and int(lote.get("total_ok") or 0) > 0 and not errors:
        conn.execute(
            """
            UPDATE gestoria_import_lotes
            SET estado = 'aplicado',
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (now, lote_id),
        )
        lote = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
        lote = dict(lote) if lote else None
    return {"applied": applied, "errors": errors, "lote": lote}

def process_seguros_ocr(payload, conn):
    pdf_bytes = decode_seguros_payload(payload)
    fast_mode = str(payload.get("fast_mode") or "").strip().lower() in ("1", "true", "yes", "on")
    tmp_path = None
    text = ""
    err_detail = ""
    method = ""
    source_hint = " ".join(
        [
            str(payload.get("filename") or ""),
            str(payload.get("s3_key") or ""),
            str(payload.get("source_hint") or ""),
        ]
    ).strip()
    hinted_company = detect_company_from_metadata(source_hint)
    required_keys = ("tomador", "poliza_numero", "compania", "fecha_efecto")
    ai_used = False
    ai_error = ""
    field_sources = {}
    candidate_fields = []
    def candidate_score(quality):
        if not isinstance(quality, dict):
            return 0
        required_valid = len(quality.get("required_valid") or [])
        required_filled = len(quality.get("required_filled") or [])
        confidence = float(quality.get("confidence") or 0)
        return required_valid * 100 + required_filled * 10 + int(confidence * 100)
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
            tmp_file.write(pdf_bytes)
            tmp_path = tmp_file.name
        text, err_detail, method = extract_pdf_text(tmp_path)
        if not text:
            raise RuntimeError(err_detail or "No se pudo extraer texto")
        fields = parse_poliza_text(text, source_hint=source_hint, hinted_company=hinted_company)
        candidate_fields.append(("pdf_text", normalize_extracted_fields(fields), 1.0))
        best_quality = compute_ocr_quality(fields, required_keys)
        if (not fast_mode) and (
            not any(str(value or "").strip() for value in fields.values()) or (
            not fields.get("poliza_numero")
            or not fields.get("tomador")
            or not fields.get("compania")
            or not fields.get("fecha_efecto")
            )
        ):
            ocr_text, ocr_err = ocr_pdf_all_pages(tmp_path, use_external=external_ocr_available())
            if ocr_text:
                ocr_fields = parse_poliza_text(ocr_text, source_hint=source_hint, hinted_company=hinted_company)
                candidate_fields.append(("ocr_all_pages", normalize_extracted_fields(ocr_fields), 1.05))
                ocr_quality = compute_ocr_quality(ocr_fields, required_keys)
                if candidate_score(ocr_quality) >= candidate_score(best_quality):
                    fields = ocr_fields
                    best_quality = ocr_quality
                    text = ocr_text
                    method = "vision" if external_ocr_available() else "tesseract"
            elif ocr_err and not err_detail:
                err_detail = ocr_err
        doc_text = ""
        missing_required = any(not fields.get(key) for key in required_keys)
        if (missing_required or candidate_score(best_quality) < 250) and docai_available() and not fast_mode:
            doc_text, doc_fields, doc_err = ocr_image_docai(pdf_bytes, "application/pdf")
            if doc_err and not err_detail:
                err_detail = doc_err
            doc_mapped = map_docai_poliza_fields(doc_fields)
            doc_parsed = parse_poliza_text(doc_text, source_hint=source_hint, hinted_company=hinted_company) if doc_text else {}
            candidate_fields.append(("docai_fields", normalize_extracted_fields(doc_mapped), 1.1))
            candidate_fields.append(("docai_parsed", normalize_extracted_fields(doc_parsed), 1.05))
            merged = dict(fields)
            for key, value in doc_mapped.items():
                if value and not merged.get(key):
                    merged[key] = value
            for key, value in doc_parsed.items():
                if value and not merged.get(key):
                    merged[key] = value
            merged_quality = compute_ocr_quality(merged, required_keys)
            if candidate_score(merged_quality) >= candidate_score(best_quality):
                fields = merged
                best_quality = merged_quality
            if doc_text and doc_text.strip():
                method = "docai"
        missing_required = any(not fields.get(key) for key in required_keys)
        need_zones = missing_required or (not fast_mode and candidate_score(best_quality) < 320)
        if need_zones:
            zones_text, zones_err = ocr_poliza_key_regions(tmp_path, use_external=external_ocr_available())
            if zones_text:
                zones_fields = parse_poliza_text(
                    zones_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                candidate_fields.append(("zones", normalize_extracted_fields(zones_fields), 1.08))
                zones_merged = merge_fields(fields, zones_fields)
                zones_quality = compute_ocr_quality(zones_merged, required_keys)
                if candidate_score(zones_quality) >= candidate_score(best_quality):
                    fields = zones_merged
                    best_quality = zones_quality
                    if method:
                        method = f"{method}+zones"
                    else:
                        method = "zones"
            elif zones_err and not err_detail:
                err_detail = zones_err
        if hinted_company and not fields.get("compania"):
            fields["compania"] = hinted_company
        missing_required = any(not fields.get(key) for key in required_keys)
        if fast_mode and missing_required:
            # Último intento rápido sin OCR externo ni IA para evitar latencia alta.
            quick_text, quick_err = ocr_pdf_all_pages(tmp_path, use_external=False)
            if quick_text:
                quick_fields = parse_poliza_text(quick_text, source_hint=source_hint, hinted_company=hinted_company)
                quick_merged = merge_fields(fields, quick_fields)
                quick_quality = compute_ocr_quality(quick_merged, required_keys)
                if candidate_score(quick_quality) >= candidate_score(best_quality):
                    fields = quick_merged
                    best_quality = quick_quality
                    text = quick_text
                    method = "tesseract"
            elif quick_err and not err_detail:
                err_detail = quick_err
            missing_required = any(not fields.get(key) for key in required_keys)
        if (not fast_mode) and openai_available() and (missing_required or candidate_score(best_quality) < 320):
            ai_text = text or ""
            if doc_text and doc_text.strip():
                ai_text = f"{ai_text}\n\n{doc_text}".strip()
            if tmp_path and OCR_OPENAI_VISION_PAGES > 0:
                image_urls, vision_img_err = pdf_to_png_data_urls(
                    tmp_path,
                    max_pages=OCR_OPENAI_VISION_PAGES,
                    dpi=OCR_OPENAI_VISION_DPI,
                )
                if image_urls:
                    ai_vision_fields, ai_vision_err = call_openai_extract_seguro_vision(
                        image_urls,
                        text=ai_text,
                        source_hint=source_hint,
                        hinted_company=hinted_company,
                    )
                    if ai_vision_err:
                        ai_error = ai_vision_err
                    elif ai_vision_fields:
                        ai_used = True
                        candidate_fields.append(("openai_vision", normalize_extracted_fields(ai_vision_fields), 1.18))
                        merged = dict(fields)
                        for key, value in ai_vision_fields.items():
                            if value and not str(merged.get(key) or "").strip():
                                merged[key] = value
                        ai_quality = compute_ocr_quality(merged, required_keys)
                        if candidate_score(ai_quality) >= candidate_score(best_quality):
                            fields = merged
                            best_quality = ai_quality
                elif vision_img_err and not ai_error:
                    ai_error = vision_img_err
            if ai_text:
                ai_fields, ai_error_msg = call_openai_extract_seguro(
                    ai_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                if ai_error_msg:
                    ai_error = ai_error_msg
                elif ai_fields:
                    ai_used = True
                    candidate_fields.append(("openai_text", normalize_extracted_fields(ai_fields), 0.98))
                    merged = dict(fields)
                    for key, value in ai_fields.items():
                        if value and not str(merged.get(key) or "").strip():
                            merged[key] = value
                    ai_quality = compute_ocr_quality(merged, required_keys)
                    if candidate_score(ai_quality) >= candidate_score(best_quality):
                        fields = merged
                        best_quality = ai_quality
        if (not fast_mode) and OCR_EXPERT_MODE and candidate_fields:
            expert_fields, expert_sources = blend_ocr_field_candidates(candidate_fields, required_keys)
            expert_quality = compute_ocr_quality(expert_fields, required_keys)
            if candidate_score(expert_quality) >= candidate_score(best_quality):
                fields = expert_fields
                best_quality = expert_quality
                field_sources = expert_sources
        # Post-fix final para AXA Profesional: evita valores del mediador y fechas truncadas.
        company_key = normalize_company_key(fields.get("compania") or hinted_company or "")
        text_upper = normalize_lookup_text(text)
        if ("AXA" in company_key) and ("AXA PROFESIONAL" in text_upper or "POLIZA DE SEGURO DE PROFESIONAL" in text_upper):
            def _norm_date_local(value):
                raw = str(value or "").strip()
                raw = raw.replace(".", "/").replace("-", "/")
                raw = re.sub(r"\s+", "", raw)
                return raw
            def _clean_name_local(value):
                raw = normalize_person_name(value or "")
                raw = re.sub(r"\s{2,}", " ", raw).strip(" ,;:-")
                return raw
            fields["ramo"] = "Profesional"
            pol = re.search(r"p[oó]liza\s*(?:n[º°o]|no\.?)\s*([0-9]{2})[- ]?([0-9]{7,})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = f"{pol.group(1)}-{pol.group(2)}"
            dates = re.search(
                r"Datos\s+de\s+la\s+Poliza[\s\S]{0,900}?Fecha\s+efecto[\s\S]{0,200}?Fecha\s+vencimiento[\s\S]{0,220}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})[\s\S]{0,120}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})",
                text,
                re.IGNORECASE,
            )
            if dates:
                fields["fecha_efecto"] = _norm_date_local(dates.group(1))
                fields["fecha_vencimiento"] = _norm_date_local(dates.group(2))
            tom = re.search(r"Tomador\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{6,}?)\s+Producto", text, re.IGNORECASE)
            if tom:
                fields["tomador"] = _clean_name_local(tom.group(1))
            if not fields.get("tomador") or len((fields.get("tomador") or "").split()) < 3:
                aseg = re.search(r"Nombre\s+del\s+asegurado\s*[\r\n]+\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{8,})", text, re.IGNORECASE)
                if aseg:
                    fields["tomador"] = _clean_name_local(aseg.group(1))
            if normalize_phone(fields.get("telefono") or "") == "900909014":
                fields["telefono"] = ""
            if "fincasvelazquez" in str(fields.get("email") or "").lower():
                fields["email"] = ""
            dir_norm = normalize_lookup_text(fields.get("direccion") or "")
            if "DOMICILIO SOCIAL" in dir_norm or "MEDIADOR" in dir_norm or "PALMA DE MALLORCA" in dir_norm:
                fields["direccion"] = ""
            if not fields.get("direccion"):
                addr = re.search(r"\b(CL\s+calle[^\n]{5,160}?\d{5}\s+[A-ZÁÉÍÓÚÑ]{3,})", text, re.IGNORECASE)
                if addr:
                    fields["direccion"] = re.sub(r"\s+", " ", addr.group(1)).strip()
        if ("ALLIANZ" in company_key) and ("CERTIFICADO DE SEGURO" in text_upper or "ALLIANZ R C PYME" in text_upper or "ALLIANZ R.C.PYME" in text_upper):
            if not fields.get("ramo"):
                fields["ramo"] = "Responsabilidad civil"
            allianz_general = re.search(
                r"Datos\s+Generales([\s\S]{0,2200}?)Datos\s+del\s+Asegurado",
                text,
                re.IGNORECASE,
            )
            allianz_scope = allianz_general.group(1) if allianz_general else text
            pol = re.search(r"P[oó]liza\s*n[º°o]\s*:\s*([0-9]{6,12})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = pol.group(1).strip()
            dur = re.search(
                r"Duraci[oó]n\s*:\s*Desde[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})[\s\S]{0,240}?hasta[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})",
                text,
                re.IGNORECASE,
            )
            if dur:
                fields["fecha_efecto"] = dur.group(1)
                fields["fecha_vencimiento"] = dur.group(2)
            m = re.search(
                r"Datos\s+Generales\s*\n\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s,.'\-]{5,})\s*\n\s*Tomador\s+del\s+Seguro",
                text,
                re.IGNORECASE,
            )
            if m:
                name = normalize_person_name(m.group(1))
                name = re.sub(r"\s+", " ", name).strip(" ,;:-")
                if name and len(name.split()) >= 2:
                    fields["tomador"] = name
            # Si tomador quedó como una dirección, priorizar razón social del bloque general.
            tomador_norm = normalize_lookup_text(fields.get("tomador") or "")
            looks_address = (
                " CL " in f" {tomador_norm} "
                or " CALLE " in f" {tomador_norm} "
                or " AVDA " in f" {tomador_norm} "
                or " AVD " in f" {tomador_norm} "
            )
            if looks_address or not fields.get("tomador"):
                lines = [ln.strip() for ln in allianz_scope.splitlines() if ln.strip()]
                for idx, ln in enumerate(lines):
                    if re.search(r"Tomador\s+del", ln, re.IGNORECASE):
                        if idx > 0:
                            candidate = re.sub(r"\s+", " ", lines[idx - 1]).strip(" ,;:-")
                            if candidate and len(candidate.split()) >= 2:
                                fields["tomador"] = candidate
                        break
            nif_line = re.search(r"\bNIF\s*:\s*([A-Z0-9.\-]{8,16})", allianz_scope, re.IGNORECASE)
            if nif_line:
                fields["nif"] = re.sub(r"[^A-Z0-9]", "", nif_line.group(1).upper())
                fields["dni"] = fields["nif"]
            if fields.get("fecha_efecto") and fields.get("fecha_vencimiento") and fields["fecha_efecto"] == fields["fecha_vencimiento"]:
                fields["fecha_vencimiento"] = add_year_to_date(fields["fecha_efecto"])
        doc_type = classify_seguros_document(text)
        if doc_type == "otro" and doc_text:
            doc_type = classify_seguros_document(doc_text)
        ocr_quality = compute_ocr_quality(fields, required_keys)
        if field_sources:
            ocr_quality["field_sources"] = field_sources
        cliente_match = False
        cliente_id = None
        tomador = (fields.get("tomador") or "").strip()
        nif = (fields.get("nif") or fields.get("dni") or "").strip()
        if tomador or nif:
            if nif:
                nif_norm = re.sub(r"\s+", "", nif).upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE REPLACE(UPPER(nif), ' ', '') = ?",
                    (nif_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
            if not cliente_match and tomador:
                nombre_norm = re.sub(r"\s+", " ", tomador).strip().upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE TRIM(UPPER(nombre)) = ?",
                    (nombre_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
        return {
            "fields": fields,
            "text": text,
            "language": detect_ocr_lang(),
            "method": method,
            "doc_type": doc_type,
            "ocr_quality": ocr_quality,
            "cliente_id": cliente_id,
            "cliente_match": cliente_match,
            "ai_used": ai_used,
            "ai_error": ai_error,
        }
    finally:
        if tmp_path and os.path.exists(tmp_path):
            os.unlink(tmp_path)


def enqueue_ocr_job(db_path, kind, payload):
    job_id = os.urandom(16).hex()
    now = datetime.now(timezone.utc).isoformat()
    conn = open_sqlite_conn(db_path, with_row_factory=False)
    conn.execute(
        """
        INSERT INTO ocr_jobs (id, kind, status, payload_json, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (job_id, kind, "pending", json.dumps(payload), now, now),
    )
    conn.commit()
    conn.close()
    return job_id


def fetch_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    row = conn.execute(
        """
        SELECT id, kind, payload_json
        FROM ocr_jobs
        WHERE status = 'pending'
           OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
        ORDER BY created_at ASC
        LIMIT 1
        """,
        (cutoff,),
    ).fetchone()
    return row


def claim_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    now = datetime.now(timezone.utc).isoformat()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT id, kind, payload_json
            FROM ocr_jobs
            WHERE status = 'pending'
               OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
            ORDER BY created_at ASC
            LIMIT 1
            """,
            (cutoff,),
        ).fetchone()
        if not row:
            conn.commit()
            return None
        updated = conn.execute(
            """
            UPDATE ocr_jobs
            SET status = 'processing', error = NULL, started_at = ?, updated_at = ?
            WHERE id = ?
              AND (
                status = 'pending'
                OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
              )
            """,
            (now, now, row["id"], cutoff),
        ).rowcount
        conn.commit()
        if updated == 1:
            return row
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    return None


def update_ocr_job(conn, job_id, status, result=None, error=None):
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        """
        UPDATE ocr_jobs
        SET status = ?, result_json = COALESCE(?, result_json), error = ?, updated_at = ?,
            started_at = CASE
                WHEN ? = 'processing' THEN ?
                WHEN started_at IS NULL THEN ?
                ELSE started_at
            END,
            finished_at = CASE WHEN ? IN ('done','error') THEN ? ELSE finished_at END
        WHERE id = ?
        """,
        (
            status,
            json.dumps(result) if result is not None else None,
            error,
            now,
            status,
            now,
            now,
            status,
            now,
            job_id,
        ),
    )


def ocr_worker_loop(jobs_db_path, main_db_path):
    while True:
        jobs_conn = None
        job_id = None
        try:
            jobs_conn = open_sqlite_conn(jobs_db_path, with_row_factory=True)
            row = claim_next_ocr_job(jobs_conn)
            if not row:
                jobs_conn.close()
                time.sleep(0.6)
                continue
            job_id = row["id"]
            kind = row["kind"]
            payload = json.loads(row["payload_json"] or "{}")
            if kind == "seguros":
                main_conn = open_sqlite_conn(main_db_path, with_row_factory=True)
                try:
                    result = process_seguros_ocr(payload, main_conn)
                finally:
                    main_conn.close()
            else:
                raise RuntimeError("Tipo OCR no soportado")
            update_ocr_job(jobs_conn, job_id, "done", result=result, error=None)
            jobs_conn.commit()
            jobs_conn.close()
        except Exception as exc:
            try:
                if jobs_conn and job_id:
                    update_ocr_job(jobs_conn, job_id, "error", result=None, error=str(exc))
                    jobs_conn.commit()
            except Exception:
                pass
            try:
                if jobs_conn:
                    jobs_conn.close()
            except Exception:
                pass
            time.sleep(1.0)

def preprocess_image_for_ocr(src_path, out_path=None):
    tmp_base = tempfile.gettempdir()
    created = False
    if not out_path:
        tmp_file = tempfile.NamedTemporaryFile(suffix=".png", delete=False, dir=tmp_base)
        out_path = tmp_file.name
        tmp_file.close()
        created = True
    magick = shutil.which("magick") or shutil.which("convert")
    if magick and os.path.exists(magick):
        try:
            run_subprocess(
                [
                    magick,
                    src_path,
                    "-colorspace",
                    "Gray",
                    "-density",
                    "300",
                    "-resize",
                    "2500x2500",
                    "-deskew",
                    "40%",
                    "-sharpen",
                    "0x1",
                    "-contrast-stretch",
                    "1%x1%",
                    out_path,
                ],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
                text=True,
            )
            return out_path, created
        except Exception:
            pass
    try:
        run_subprocess(
            ["sips", "-s", "format", "png", src_path, "--out", out_path],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        try:
            run_subprocess(
                ["sips", "-Z", "2400", out_path, "--out", out_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            pass
        return out_path, created
    except Exception:
        return src_path, created

def ocr_image_file(image_path):
    lang = detect_ocr_lang()
    tesseract_cmd = (
        shutil.which("tesseract")
        or "/opt/homebrew/bin/tesseract"
        or "/usr/local/bin/tesseract"
    )
    if not tesseract_cmd or not os.path.exists(tesseract_cmd):
        return "", "tesseract no encontrado en PATH"
    env = os.environ.copy()
    if os.path.isdir(TESSDATA_DIR):
        env["TESSDATA_PREFIX"] = TESSDATA_DIR
    tmp_base = tempfile.gettempdir()
    with tempfile.TemporaryDirectory(dir=tmp_base) as tmpdir:
        processed, created = preprocess_image_for_ocr(image_path)
        variants = [processed]
        magick = shutil.which("magick") or shutil.which("convert")
        if magick and os.path.exists(magick) and os.path.exists(processed):
            for idx, extra in enumerate(
                (
                    ["-threshold", "55%", "-despeckle"],
                    ["-adaptive-threshold", "15x15+10%", "-sharpen", "0x1.2"],
                )
            ):
                out_variant = os.path.join(tmpdir, f"ocr_var_{idx}.png")
                try:
                    run_subprocess(
                        [magick, processed, *extra, out_variant],
                        check=True,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.PIPE,
                        text=True,
                    )
                    if os.path.exists(out_variant):
                        variants.append(out_variant)
                except Exception:
                    continue
        def run_tesseract(psm, source_path):
            result = run_subprocess(
                [
                    tesseract_cmd,
                    source_path,
                    "stdout",
                    "-l",
                    lang,
                    "--oem",
                    "1",
                    "--psm",
                    str(psm),
                    "-c",
                    "user_defined_dpi=300",
                    "-c",
                    "preserve_interword_spaces=1",
                ],
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
                text=True,
            )
            return result.stdout or ""
        try:
            candidates = []
            for source_path in variants:
                for psm in OCR_TESSERACT_PSMS:
                    try:
                        candidates.append(run_tesseract(psm, source_path))
                    except subprocess.CalledProcessError:
                        continue
            if not candidates:
                return "", "tesseract: sin salida"
            best = max(candidates, key=lambda t: (len(t.strip()), sum(ch.isdigit() for ch in t)))
            return best, ""
        except subprocess.CalledProcessError as err:
            return "", f"tesseract: {err.stderr.strip()}"
        except Exception as err:
            return "", f"tesseract: {err}"
        finally:
            if created and processed and os.path.exists(processed):
                try:
                    os.unlink(processed)
                except Exception:
                    pass

def ocr_image_external(image_bytes):
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    api_key = os.environ.get("GOOGLE_VISION_API_KEY") or os.environ.get("VISION_API_KEY")
    auth_header = None
    if credentials_path and os.path.exists(credentials_path):
        try:
            from google.oauth2 import service_account
            from google.auth.transport.requests import Request
        except Exception:
            return "", "OCR externo: instala google-auth y requests (pip install google-auth requests)"
        try:
            creds = service_account.Credentials.from_service_account_file(
                credentials_path,
                scopes=["https://www.googleapis.com/auth/cloud-platform"],
            )
            creds.refresh(Request())
            auth_header = f"Bearer {creds.token}"
        except Exception as err:
            return "", f"OCR externo: credenciales inválidas ({err})"
    elif not api_key:
        return "", "OCR externo no configurado"
    payload = {
        "requests": [
            {
                "image": {"content": base64.b64encode(image_bytes).decode("utf-8")},
                "features": [{"type": "DOCUMENT_TEXT_DETECTION"}],
            }
        ]
    }
    data = json.dumps(payload).encode("utf-8")
    if auth_header:
        url = "https://vision.googleapis.com/v1/images:annotate"
        headers = {"Content-Type": "application/json", "Authorization": auth_header}
    else:
        url = f"https://vision.googleapis.com/v1/images:annotate?key={api_key}"
        headers = {"Content-Type": "application/json"}
    req = urllib.request.Request(url, data=data, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            res = json.loads(resp.read().decode("utf-8"))
    except Exception as err:
        return "", f"OCR externo: {err}"
    try:
        text = res["responses"][0].get("fullTextAnnotation", {}).get("text", "")
        return text, ""
    except Exception:
        return "", "OCR externo: sin texto"

def external_ocr_available():
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    api_key = os.environ.get("GOOGLE_VISION_API_KEY") or os.environ.get("VISION_API_KEY")
    return bool(api_key) or (credentials_path and os.path.exists(credentials_path))

def docai_available():
    processor_id = os.environ.get("DOCUMENTAI_PROCESSOR_ID") or os.environ.get("DOC_AI_PROCESSOR_ID")
    return bool(processor_id)

def normalize_field_label(value):
    value = value or ""
    value = value.lower()
    value = value.replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u")
    value = re.sub(r"[^a-z0-9 ]+", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    return value

def ocr_image_docai(image_bytes, mime_type):
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    if not credentials_path or not os.path.exists(credentials_path):
        return "", {}, "Document AI: credenciales no configuradas"
    processor_id = os.environ.get("DOCUMENTAI_PROCESSOR_ID") or os.environ.get("DOC_AI_PROCESSOR_ID")
    if not processor_id:
        return "", {}, "Document AI: falta DOCUMENTAI_PROCESSOR_ID"
    location = os.environ.get("DOCUMENTAI_LOCATION") or "eu"
    try:
        from google.oauth2 import service_account
        from google.auth.transport.requests import Request
    except Exception:
        return "", {}, "Document AI: instala google-auth y requests"
    try:
        creds = service_account.Credentials.from_service_account_file(
            credentials_path,
            scopes=["https://www.googleapis.com/auth/cloud-platform"],
        )
        creds.refresh(Request())
        project_id = creds.project_id
    except Exception as err:
        return "", {}, f"Document AI: credenciales inválidas ({err})"
    if not project_id:
        return "", {}, "Document AI: project_id no encontrado"
    url = (
        f"https://{location}-documentai.googleapis.com/v1/projects/{project_id}"
        f"/locations/{location}/processors/{processor_id}:process"
    )
    payload = {
        "rawDocument": {
            "content": base64.b64encode(image_bytes).decode("utf-8"),
            "mimeType": mime_type or "image/jpeg",
        }
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {creds.token}"},
    )
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            res = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as err:
        try:
            detail = err.read().decode("utf-8")
        except Exception:
            detail = ""
        return "", {}, f"Document AI: {err} {detail}".strip()
    except Exception as err:
        return "", {}, f"Document AI: {err}"
    doc = res.get("document") or {}
    text = doc.get("text", "")
    fields = {}
    occurrences = {}
    for field in doc.get("pages", []) or []:
        for form_field in field.get("formFields", []) or []:
            name_text = ""
            value_text = ""
            name = form_field.get("fieldName", {}).get("textAnchor", {}).get("textSegments", [])
            for seg in name:
                try:
                    start = int(seg.get("startIndex", 0))
                    end = int(seg.get("endIndex", 0))
                    name_text += text[start:end]
                except Exception:
                    continue
            value = form_field.get("fieldValue", {}).get("textAnchor", {}).get("textSegments", [])
            for seg in value:
                try:
                    start = int(seg.get("startIndex", 0))
                    end = int(seg.get("endIndex", 0))
                    value_text += text[start:end]
                except Exception:
                    continue
            label = normalize_field_label(name_text)
            val = value_text.strip()
            if not label or not val:
                continue
            occurrences[label] = occurrences.get(label, 0) + 1
            key = label
            if label in (
                "nombre y apellidos",
                "nombre apellidos",
                "nombre",
                "dni",
                "nif",
                "telefono",
                "movil",
                "correo electronico",
                "email",
                "fecha nacimiento",
                "estado civil",
                "hijos",
                "profesion",
                "tipo contrato",
                "ingresos nomina",
                "ingresos",
                "nomina",
                "patrimonio alquiler",
                "prestamos",
            ):
                suffix = "1" if occurrences[label] == 1 else "2"
                key = f"{label} {suffix}"
            fields[key] = val
    return text, fields, ""

def map_docai_fields(doc_fields):
    doc_fields = doc_fields or {}
    def doc_pick(label, idx=1):
        key = f"{label} {idx}"
