def fin_sync_stage(conn, asesoramiento_id, stage, now):
    if not asesoramiento_id or not stage:
        return
    conn.execute(
        "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
        (stage, now, asesoramiento_id),
    )


def ensure_fin_followup_action(
    conn,
    empresa_id,
    asesoramiento_id,
    cliente_id,
    cliente_nombre,
    responsable,
    action_type,
    notas,
    now,
):
    if not empresa_id or not asesoramiento_id or not action_type:
        return None
    exists = conn.execute(
        """
        SELECT id
        FROM acciones
        WHERE servicio = 'financiaciones'
          AND asesoramiento_id = ?
          AND tipo = ?
          AND LOWER(COALESCE(estado, '')) = 'pendiente'
        LIMIT 1
        """,
        (asesoramiento_id, action_type),
    ).fetchone()
    if exists:
        return exists["id"]
    next_id = os.urandom(16).hex()
    next_date = datetime.now().strftime("%Y-%m-%d")
    conn.execute(
        """
        INSERT INTO acciones (
          id, empresa_id, servicio, cliente_id, inmueble_id, asesoramiento_id, cliente_nombre,
          fecha, hora, tipo, responsable, estado, notas, created_at, updated_at
        ) VALUES (
          ?, ?, 'financiaciones', ?, NULL, ?, ?, ?, '10:00', ?, ?, 'Pendiente', ?, datetime(?), datetime(?)
        )
        """,
        (
            next_id,
            empresa_id,
            cliente_id,
            asesoramiento_id,
            cliente_nombre or "",
            next_date,
            action_type,
            responsable or "",
            notas or "",
            now,
            now,
        ),
    )
    return next_id


def convert_fin_asesoramiento_to_hipoteca(conn, empresa_id, row, now):
    if not row:
        return None
    existing = conn.execute(
        """
        SELECT id
        FROM hipotecas
        WHERE empresa_id = ?
          AND cliente_id = ?
          AND fecha_encargo = ?
        LIMIT 1
        """,
        (empresa_id, row["cliente1_id"], row["fecha"]),
    ).fetchone()
    if existing:
        conn.execute(
            "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
            ("Convertido", now, row["id"]),
        )
        return existing["id"]
    cliente_nombre = row["cliente1_nombre"] or ""
    if row["cliente2_nombre"]:
        cliente_nombre = f"{cliente_nombre} / {row['cliente2_nombre']}".strip(" /")
    fecha = row["fecha"] or ""
    try:
        anio = int(fecha.split("/")[-1]) if "/" in fecha else int(fecha.split("-")[0])
    except Exception:
        anio = None
    hipoteca_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO hipotecas (
          id, empresa_id, cliente, cliente_id, banco, precio, importe_hipoteca, porcentaje,
          entrada, comision, oficina, fecha_encargo, encargo, tipo_hipoteca,
          fecha_firma, cesion, comision_juan, comision_modernia, inmobiliaria_compra,
          asesor, estado, anio, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            hipoteca_id,
            empresa_id,
            cliente_nombre,
            row["cliente1_id"],
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            fecha,
            None,
            None,
            None,
            None,
            None,
            None,
            row["inmobiliaria_asesor"],
            row["asesor"],
            "Pendiente",
            anio,
            now,
            now,
        ),
    )
    conn.execute(
        "UPDATE asesoramientos_financiacion SET estado = ?, updated_at = datetime(?) WHERE id = ?",
        ("Convertido", now, row["id"]),
    )
    return hipoteca_id


def apply_fin_action_workflow(conn, empresa_id, action_row, now):
    if not action_row:
        return None
    asesoramiento_id = str(action_row["asesoramiento_id"] or "").strip()
    if not asesoramiento_id:
        return None
    current = conn.execute(
        "SELECT * FROM asesoramientos_financiacion WHERE id = ? LIMIT 1",
        (asesoramiento_id,),
    ).fetchone()
    if not current:
        return None
    tipo = normalize_fin_action_type(action_row["tipo"])
    resultado = str(action_row["resultado_cierre"] or "").strip()
    next_stage = ""
    next_action = ""
    next_note = ""
    if tipo == "primera_llamada":
        if resultado == "Cita concertada":
            next_stage = "Asesoramiento"
            next_action = "Reunión de asesoramiento"
            next_note = "Cita concertada desde la primera llamada."
        elif resultado == "No interesado":
            next_stage = "Descartada"
    elif tipo == "reunion_asesoramiento":
        if resultado == "Realizada":
            next_stage = "Estudio"
            next_action = "Estudio financiero"
            next_note = "Analizar viabilidad y ratios."
        elif resultado == "Pendiente documentación":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Completar documentación antes del estudio."
        elif resultado == "No viable":
            next_stage = "Descartada"
    elif tipo == "solicitud_documentacion":
        if resultado == "Completa":
            next_stage = "Estudio"
            next_action = "Estudio financiero"
            next_note = "Documentación completa para analizar."
        else:
            next_stage = "Documentación"
    elif tipo == "estudio_financiero":
        if resultado == "Viable":
            next_stage = "Bancos"
            next_action = "Presentación bancaria"
            next_note = "Enviar expediente a entidades."
        elif resultado == "Pendiente documentación":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Falta documentación para terminar el estudio."
        elif resultado == "No viable":
            next_stage = "Descartada"
    elif tipo == "presentacion_bancaria":
        if resultado == "Presentada":
            next_stage = "Bancos"
            next_action = "Seguimiento bancario"
            next_note = "Hacer seguimiento de entidades."
        elif resultado == "Pendiente completar":
            next_stage = "Documentación"
            next_action = "Solicitud documentación"
            next_note = "Completar expediente antes de enviar."
    elif tipo == "seguimiento_bancario":
        if resultado == "Tasación solicitada":
            next_stage = "Tasación"
            next_action = "Tasación"
            next_note = "Controlar cita, encargo y resultado de tasación."
        elif resultado == "Aprobada":
            next_stage = "FEIN / Acta"
            next_action = "FEIN / Acta"
            next_note = "Revisar FEIN, acta notarial y pre-firma."
        elif resultado == "Denegada":
            next_stage = "Descartada"
    elif tipo == "tasacion_fin":
        if resultado == "Tasación OK":
            next_stage = "FEIN / Acta"
            next_action = "FEIN / Acta"
            next_note = "Avanzar a FEIN y acta."
        elif resultado == "Incidencia":
            next_stage = "Tasación"
    elif tipo == "fein_acta":
        if resultado == "Firmable":
            next_stage = "Firma"
            next_action = "Firma hipoteca"
            next_note = "Preparar firma hipotecaria."
        elif resultado == "Pendiente":
            next_stage = "FEIN / Acta"
    elif tipo == "firma_hipoteca":
        if resultado == "Firmada":
            convert_fin_asesoramiento_to_hipoteca(conn, empresa_id, current, now)
            return "Convertido"
        elif resultado == "Cancelada":
            next_stage = "Descartada"
        elif resultado == "Pospuesta":
            next_stage = "Firma"
    if next_stage:
        fin_sync_stage(conn, asesoramiento_id, next_stage, now)
    if next_action:
        ensure_fin_followup_action(
            conn,
            empresa_id,
            asesoramiento_id,
            current["cliente1_id"],
            current["cliente1_nombre"],
            action_row["responsable"],
            next_action,
            next_note,
            now,
        )
    return next_stage or normalize_fin_stage(current["estado"])


def get_inmueble_propietarios(conn, inmueble_id):
    if not inmueble_id:
        return []
    rows = conn.execute(
        """
        SELECT c.id, c.nombre, c.nif, c.telefono, c.email
        FROM inmueble_propietarios ip
        JOIN clientes c ON c.id = ip.cliente_id
        WHERE ip.inmueble_id = ?
        ORDER BY c.nombre
        """,
        (inmueble_id,),
    ).fetchall()
    return [dict(row) for row in rows]


def resolve_inmobiliaria_contact_candidate(conn, empresa_id, payload, *, role_prefix="", demanda_id="", inmueble_id=""):
    nombre = normalize_person_name(payload.get(f"{role_prefix}_nombre")) if role_prefix else ""
    nif = normalize_nif(payload.get(f"{role_prefix}_nif")) if role_prefix else ""
    telefono = str(payload.get(f"{role_prefix}_telefono") or "").strip() if role_prefix else ""
    email = normalize_email(payload.get(f"{role_prefix}_email")) if role_prefix else ""
    cliente_id = None
    if role_prefix and (nombre or nif or telefono or email):
        cliente_id = ensure_cliente_for_inmobiliaria(
            conn,
            empresa_id,
            nombre,
            nif,
            datetime.now(timezone.utc).isoformat(),
            {"telefono": telefono, "email": email},
        )
        return {
            "cliente_id": cliente_id,
            "nombre": nombre,
            "nif": nif,
            "telefono": telefono,
            "email": email,
        }

    if demanda_id:
        demanda = conn.execute(
            """
            SELECT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
            FROM demandas d
            LEFT JOIN clientes c ON c.id = d.cliente_id
            WHERE d.id = ? AND d.empresa_id = ?
            LIMIT 1
            """,
            (demanda_id, empresa_id),
        ).fetchone()
        if demanda and (demanda["cliente_id"] or demanda["nombre"]):
            return {
                "cliente_id": demanda["cliente_id"],
                "nombre": str(demanda["nombre"] or "").strip(),
                "nif": normalize_nif(demanda["nif"]),
                "telefono": str(demanda["telefono"] or "").strip(),
                "email": normalize_email(demanda["email"]),
            }

    if inmueble_id:
        rows = conn.execute(
            """
            SELECT DISTINCT d.cliente_id, c.nombre, c.nif, c.telefono, c.email
            FROM visitas v
            JOIN demandas d ON d.id = v.demanda_id
            LEFT JOIN clientes c ON c.id = d.cliente_id
            WHERE v.empresa_id = ?
              AND v.inmueble_id = ?
              AND d.cliente_id IS NOT NULL
            ORDER BY v.created_at DESC
            """,
            (empresa_id, inmueble_id),
        ).fetchall()
        unique = []
        seen = set()
        for row in rows:
            key = str(row["cliente_id"] or "").strip()
            if not key or key in seen:
                continue
            seen.add(key)
            unique.append(row)
        if len(unique) == 1:
            row = unique[0]
            return {
                "cliente_id": row["cliente_id"],
                "nombre": str(row["nombre"] or "").strip(),
                "nif": normalize_nif(row["nif"]),
                "telefono": str(row["telefono"] or "").strip(),
                "email": normalize_email(row["email"]),
            }
    return {
        "cliente_id": None,
        "nombre": "",
        "nif": "",
        "telefono": "",
        "email": "",
    }


def normalize_inmobiliaria_address(value):
    return re.sub(r"\s+", " ", normalize_lookup_text(value or "")).strip()


def resolve_owner_nifs_from_cliente_ids(conn, cliente_ids):
    normalized = []
    seen = set()
    for cliente_id in cliente_ids or []:
        row = conn.execute(
            "SELECT nif FROM clientes WHERE id = ? LIMIT 1",
            (cliente_id,),
        ).fetchone()
        nif = normalize_nif(row["nif"] if row else "")
        if nif and nif not in seen:
            seen.add(nif)
            normalized.append(nif)
    return normalized


def detect_inmobiliaria_duplicates(conn, empresa_id, *, direccion="", owner_nifs=None, scope="captacion"):
    direccion_norm = normalize_inmobiliaria_address(direccion)
    owner_nifs = [normalize_nif(item) for item in (owner_nifs or []) if normalize_nif(item)]
    owner_nif_set = set(owner_nifs)
    duplicates = []

    inmueble_rows = conn.execute(
        """
        SELECT
          i.id AS inmueble_id,
          i.direccion,
          i.referencia,
          i.referencia_catastral,
          cpt.id AS captacion_id,
          cpt.propietario,
          cpt.etapa,
          GROUP_CONCAT(DISTINCT c.nif) AS propietario_nifs
        FROM inmuebles i
        LEFT JOIN captaciones cpt ON cpt.inmueble_id = i.id
        LEFT JOIN inmueble_propietarios ip ON ip.inmueble_id = i.id
        LEFT JOIN clientes c ON c.id = ip.cliente_id
        WHERE i.empresa_id = ?
        GROUP BY i.id, cpt.id
        ORDER BY COALESCE(i.updated_at, i.created_at) DESC
        """,
        (empresa_id,),
    ).fetchall()
    for row in inmueble_rows:
        reasons = []
        if direccion_norm and normalize_inmobiliaria_address(row["direccion"]) == direccion_norm:
            reasons.append("misma dirección")
        row_nifs = {
            normalize_nif(part)
            for part in re.split(r"[|,]", str(row["propietario_nifs"] or ""))
            if normalize_nif(part)
        }
        shared_nifs = sorted(row_nifs.intersection(owner_nif_set))
        if shared_nifs:
            reasons.append(f"mismo DNI/NIF de propietario ({', '.join(shared_nifs)})")
        if not reasons:
            continue
        duplicates.append(
            {
                "type": "inmueble",
                "id": row["inmueble_id"],
                "direccion": row["direccion"] or "",
                "label": row["direccion"] or row["referencia"] or "Inmueble existente",
                "subtype": "captacion" if row["captacion_id"] else "inmueble",
                "propietario": row["propietario"] or "",
                "referencia_catastral": row["referencia_catastral"] or "",
                "reasons": reasons,
            }
        )

    if scope == "compraventa":
        operacion_rows = conn.execute(
            """
            SELECT
              id,
              direccion,
              fecha_escritura,
              propietario1_nombre,
              propietario1_nif,
              propietario2_nombre,
              propietario2_nif
            FROM operaciones_inmobiliarias
            WHERE empresa_id = ?
              AND LOWER(COALESCE(tipo_operacion, 'venta')) = 'venta'
            ORDER BY COALESCE(updated_at, created_at) DESC
            """,
            (empresa_id,),
        ).fetchall()
        for row in operacion_rows:
            reasons = []
            if direccion_norm and normalize_inmobiliaria_address(row["direccion"]) == direccion_norm:
                reasons.append("misma dirección en compraventa existente")
            row_nifs = {
                normalize_nif(row["propietario1_nif"]),
                normalize_nif(row["propietario2_nif"]),
            }
            row_nifs = {item for item in row_nifs if item}
            shared_nifs = sorted(row_nifs.intersection(owner_nif_set))
            if shared_nifs:
                reasons.append(f"mismo DNI/NIF de vendedor ({', '.join(shared_nifs)})")
            if not reasons:
                continue
            duplicates.append(
                {
                    "type": "compraventa",
                    "id": row["id"],
                    "direccion": row["direccion"] or "",
                    "label": row["direccion"] or "Compraventa existente",
                    "fecha_escritura": row["fecha_escritura"] or "",
                    "propietario": " | ".join(
                        [
                            item
                            for item in [
                                row["propietario1_nombre"] or "",
                                row["propietario2_nombre"] or "",
                            ]
                            if item
                        ]
                    ),
                    "reasons": reasons,
                }
            )

    deduped = []
    seen = set()
    for item in duplicates:
        signature = (
            item.get("type"),
            item.get("id"),
            tuple(item.get("reasons") or []),
        )
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(item)
    return deduped


def infer_operacion_estado_documental(payload):
    checks = [
        ("nota de encargo", payload.get("doc_nota_encargo_path")),
        ("propuesta", payload.get("doc_propuesta_path")),
        ("escritura", payload.get("doc_escritura_path")),
        ("nota simple", payload.get("doc_nota_simple_path")),
    ]
    missing = [label for label, value in checks if not str(value or "").strip()]
    return "Completo" if not missing else f"Falta: {', '.join(missing)}"


def iso_month_label(value):
    parsed = parse_iso_date(value)
    if not parsed:
        return ""
    labels = {
        1: "enero",
        2: "febrero",
        3: "marzo",
        4: "abril",
        5: "mayo",
        6: "junio",
        7: "julio",
        8: "agosto",
        9: "septiembre",
        10: "octubre",
        11: "noviembre",
        12: "diciembre",
    }
    return labels.get(parsed.month, "")


def autolink_uploaded_seguros_for_cliente(conn, cliente_id, empresa_id, now):
    if not cliente_id or not empresa_id:
        return {"linked": 0, "docs": 0}
    cliente = conn.execute(
        "SELECT id, nombre FROM clientes WHERE id = ?",
        (cliente_id,),
    ).fetchone()
    if not cliente:
        return {"linked": 0, "docs": 0}
    wanted_tokens = {t for t in normalize_lookup_text(cliente["nombre"] or "").split(" ") if len(t) >= 3}
    if not wanted_tokens:
        return {"linked": 0, "docs": 0}
    rows = conn.execute(
        f"""
        SELECT *
        FROM seguros
        WHERE empresa_id = ?
          AND ({uploaded_policy_filter()})
          AND (
            cliente_id IS NULL OR TRIM(cliente_id) = '' OR cliente_id = ?
          )
          AND tomador IS NOT NULL AND TRIM(tomador) <> ''
        ORDER BY COALESCE(fecha_efecto, created_at) DESC
        """,
        (empresa_id, cliente_id),
    ).fetchall()
    to_link = []
    for row in rows:
        cand_tokens = {t for t in normalize_lookup_text(row["tomador"] or "").split(" ") if len(t) >= 3}
        if not cand_tokens:
            continue
        if wanted_tokens.issubset(cand_tokens):
            to_link.append(row["id"])
            continue
        overlap = len(wanted_tokens.intersection(cand_tokens))
        if overlap >= 2 and (overlap / max(1, len(wanted_tokens))) >= 0.8:
            to_link.append(row["id"])
    linked = 0
    if to_link:
        conn.executemany(
            "UPDATE seguros SET cliente_id = ?, updated_at = datetime(?) WHERE id = ?",
            [(cliente_id, now, sid) for sid in to_link],
        )
        linked = len(to_link)
    docs = 0
    linked_rows = conn.execute(
        f"""
        SELECT *
        FROM seguros
        WHERE empresa_id = ?
          AND cliente_id = ?
          AND ({uploaded_policy_filter()})
        """,
        (empresa_id, cliente_id),
    ).fetchall()
    for row in linked_rows:
        doc_id = ensure_seguro_doc_link(conn, row, now)
        if doc_id:
            docs += 1
    if linked_rows:
        ensure_cliente_servicio_link(conn, cliente_id, empresa_id, "seguros", now)
    return {"linked": linked, "docs": docs}


def ensure_seguro_doc_link(conn, seguro_row, now, calidad_ocr=None, campos_ocr=""):
    if not seguro_row:
        return None
    cliente_id = seguro_row["cliente_id"]
    empresa_id = seguro_row["empresa_id"]
    poliza_key = (seguro_row["poliza_key"] or "").strip()
    poliza_url = (seguro_row["poliza_url"] or "").strip()
    if not cliente_id or not empresa_id or (not poliza_key and not poliza_url):
        return None
    where = ["cliente_id = ?", "empresa_id = ?", "LOWER(COALESCE(referencia_tipo, '')) = 'seguros'"]
    values = [cliente_id, empresa_id]
    key_or_url = []
    if poliza_key:
        key_or_url.append("doc_key = ?")
        values.append(poliza_key)
    if poliza_url:
        key_or_url.append("doc_url = ?")
        values.append(poliza_url)
    if key_or_url:
        where.append(f"({' OR '.join(key_or_url)})")
    exists = conn.execute(
        f"SELECT id FROM gestoria_docs WHERE {' AND '.join(where)} LIMIT 1",
        values,
    ).fetchone()
    if exists:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET referencia_id = COALESCE(?, referencia_id),
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = COALESCE(NULLIF(?, ''), tipo),
                fecha = COALESCE(NULLIF(?, ''), fecha),
                estado = COALESCE(NULLIF(?, ''), estado),
                notas = COALESCE(NULLIF(?, ''), notas),
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                calidad_ocr = COALESCE(NULLIF(?, ''), calidad_ocr),
                campos_ocr = COALESCE(NULLIF(?, ''), campos_ocr),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                seguro_row["id"],
                seguro_row["poliza_numero"] or seguro_row["tomador"] or "Póliza seguro",
                "Seguros",
                seguro_row["fecha_efecto"] or seguro_row["mes_creacion"] or "",
                "Recibido" if (poliza_key or poliza_url) else (seguro_row["estado"] or "En vigor"),
                " · ".join([value for value in (seguro_row["compania"], seguro_row["ramo"]) if value]),
                poliza_key or "",
                poliza_url or "",
                str(calidad_ocr or ""),
                str(campos_ocr or ""),
                now,
                exists["id"],
            ),
        )
        return exists["id"]
    # Fallback: si ya existe doc por referencia de la póliza, actualizarlo.
    by_ref = conn.execute(
        """
        SELECT id FROM gestoria_docs
        WHERE referencia_tipo = 'seguros' AND referencia_id = ?
        LIMIT 1
        """,
        (seguro_row["id"],),
    ).fetchone()
    if by_ref:
        conn.execute(
            """
            UPDATE gestoria_docs
            SET cliente_id = ?,
                empresa_id = ?,
                doc_key = COALESCE(NULLIF(?, ''), doc_key),
                doc_url = COALESCE(NULLIF(?, ''), doc_url),
                estado = COALESCE(NULLIF(?, ''), estado),
                calidad_ocr = COALESCE(NULLIF(?, ''), calidad_ocr),
                campos_ocr = COALESCE(NULLIF(?, ''), campos_ocr),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                cliente_id,
                empresa_id,
                poliza_key or "",
                poliza_url or "",
                "Recibido" if (poliza_key or poliza_url) else "",
                str(calidad_ocr or ""),
                str(campos_ocr or ""),
                now,
                by_ref["id"],
            ),
        )
        return by_ref["id"]
    nombre_doc = seguro_row["poliza_numero"] or seguro_row["tomador"] or "Póliza seguro"
    notas_doc = " · ".join([value for value in (seguro_row["compania"], seguro_row["ramo"]) if value])
    doc_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_docs (
          id, empresa_id, cliente_id, referencia_tipo, referencia_id,
          nombre, tipo, fecha, estado, notas, doc_key, doc_url,
          calidad_ocr, campos_ocr, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            doc_id,
            empresa_id,
            cliente_id,
            "seguros",
            seguro_row["id"],
            nombre_doc,
            "Seguros",
            seguro_row["fecha_efecto"] or seguro_row["mes_creacion"],
            seguro_row["estado"] or "En vigor",
            notas_doc,
            poliza_key or None,
            poliza_url or None,
            calidad_ocr,
            campos_ocr or "",
            now,
            now,
        ),
    )
    return doc_id


def parse_renta_detalles_payload(raw):
    text = str(raw or "").strip()
    if not text:
        return {
            "notes": "",
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    try:
        payload = json.loads(text)
    except Exception:
        return {
            "notes": text,
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    if isinstance(payload, list):
        return {
            "notes": "",
            "entries": payload,
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    if not isinstance(payload, dict):
        return {
            "notes": "",
            "entries": [],
            "related_cliente_id": "",
            "related_relation_id": "",
            "declaracion_conjunta": 0,
        }
    notes = str(payload.get("notes") or "").strip()
    entries = payload.get("entries")
    if not isinstance(entries, list):
        entries = []
    return {
        "notes": notes,
        "entries": entries,
        "related_cliente_id": str(payload.get("related_cliente_id") or "").strip(),
        "related_relation_id": str(payload.get("related_relation_id") or "").strip(),
        "declaracion_conjunta": 1 if str(payload.get("declaracion_conjunta") or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0,
    }


def normalize_renta_presentacion_status(value):
    text = normalize_lookup_text(value or "")
    if "BORR" in text:
        return "Borrador"
    if "PRESEN" in text:
        return "Presentada"
    return "Presentada"


def renta_dni_label(entry):
    if not isinstance(entry, dict):
        return "Caducidad DNI"
    if str(entry.get("dni_permanente") or "").strip().lower() in {"1", "true", "yes", "si", "sí"}:
        return "DNI permanente"
    return "Caducidad DNI"


def sort_renta_entries(entries):
    def entry_key(entry):
        if not isinstance(entry, dict):
            return ("", "", "")
        ejercicio = str(entry.get("ejercicio") or "")
        fecha = str(entry.get("presentacion_fecha") or "")
        entry_id = str(entry.get("id") or "")
        return (ejercicio, fecha, entry_id)

    return sorted(
        [entry for entry in entries if isinstance(entry, dict)],
        key=entry_key,
        reverse=True,
    )


RENTA_MAX_REASONABLE_AMOUNT = 1_000_000.0
RENTA_OUTLIER_RATIO = 50.0
RENTA_MAJOR_AMOUNT_FLOOR = 1000.0


def coerce_renta_money(value):
    if value is None:
        return None
    if isinstance(value, str) and not value.strip():
        return None
    number = parse_money_value(value)
    if number is None:
        return None
    return round(number, 2)


def is_reasonable_renta_amount(value, allow_zero=True):
    number = coerce_renta_money(value)
    if number is None:
        return False
    if allow_zero and abs(number) < 0.0001:
        return True
    return abs(number) <= RENTA_MAX_REASONABLE_AMOUNT


def is_renta_amount_outlier(value, reference):
    candidate = coerce_renta_money(value)
    ref = coerce_renta_money(reference)
    if candidate is None or ref is None:
        return False
    if abs(candidate) < 0.0001 or abs(ref) < RENTA_MAJOR_AMOUNT_FLOOR:
        return False
    ratio = max(abs(candidate), abs(ref)) / max(min(abs(candidate), abs(ref)), 0.01)
    return ratio > RENTA_OUTLIER_RATIO and min(abs(candidate), abs(ref)) < RENTA_MAJOR_AMOUNT_FLOOR


def first_reasonable_renta_amount(values, reference=None, allow_zero=True):
    for raw in values:
        number = coerce_renta_money(raw)
        if number is None:
            continue
        if not is_reasonable_renta_amount(number, allow_zero=allow_zero):
            continue
        if reference is not None and is_renta_amount_outlier(number, reference):
            continue
        return number
    return None


def sanitize_renta_entry(entry):
    if not isinstance(entry, dict):
        return {}
    sanitized = dict(entry)

    raw_work = coerce_renta_money(entry.get("rendimientos_trabajo_total"))
    raw_activities = coerce_renta_money(entry.get("rendimientos_actividades_economicas_total"))
    raw_cap_inm = coerce_renta_money(entry.get("rendimientos_capital_inmobiliario_total"))
    raw_cap_mob = coerce_renta_money(entry.get("rendimientos_capital_mobiliario_total"))
    raw_base_general = coerce_renta_money(entry.get("base_imponible_general"))
    raw_base_liquidable = coerce_renta_money(entry.get("base_liquidable_general"))
    raw_casilla_505 = coerce_renta_money(entry.get("casilla_505"))

    major_reference = first_reasonable_renta_amount(
        [
            raw_casilla_505,
            raw_base_liquidable,
            raw_base_general,
            raw_work,
            raw_activities,
            raw_cap_inm,
            raw_cap_mob,
        ],
        allow_zero=False,
    )

    sanitized["rendimientos_trabajo_total"] = first_reasonable_renta_amount(
        [raw_work],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_actividades_economicas_total"] = first_reasonable_renta_amount(
        [raw_activities],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_capital_inmobiliario_total"] = first_reasonable_renta_amount(
        [raw_cap_inm],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["rendimientos_capital_mobiliario_total"] = first_reasonable_renta_amount(
        [raw_cap_mob],
        reference=major_reference,
        allow_zero=True,
    )
    sanitized["base_imponible_general"] = first_reasonable_renta_amount([raw_base_general], allow_zero=True)
    sanitized["base_liquidable_general"] = first_reasonable_renta_amount([raw_base_liquidable], allow_zero=True)

    income_reference = first_reasonable_renta_amount(
        [
            sanitized.get("rendimientos_trabajo_total"),
            sanitized.get("rendimientos_actividades_economicas_total"),
            sanitized.get("rendimientos_capital_inmobiliario_total"),
            sanitized.get("rendimientos_capital_mobiliario_total"),
            sanitized.get("base_liquidable_general"),
            sanitized.get("base_imponible_general"),
            raw_casilla_505,
        ],
        allow_zero=False,
    )

    sanitized["casilla_505"] = first_reasonable_renta_amount(
        [raw_casilla_505, raw_base_liquidable, raw_base_general],
        reference=income_reference,
        allow_zero=True,
    )
    sanitized["resultado_declaracion"] = first_reasonable_renta_amount(
        [entry.get("resultado_declaracion")],
        allow_zero=True,
    )
    sanitized["ingresos_principales_total"] = first_reasonable_renta_amount(
        [
            entry.get("ingresos_principales_total"),
            sanitized.get("rendimientos_trabajo_total"),
            sanitized.get("rendimientos_actividades_economicas_total"),
            sanitized.get("rendimientos_capital_inmobiliario_total"),
            sanitized.get("rendimientos_capital_mobiliario_total"),
            sanitized.get("casilla_505"),
            sanitized.get("base_liquidable_general"),
            sanitized.get("base_imponible_general"),
        ],
        reference=sanitized.get("casilla_505") or major_reference,
        allow_zero=True,
    )
    sanitized["estado_presentacion"] = normalize_renta_presentacion_status(
        entry.get("estado_presentacion") or entry.get("doc_status")
    )
    sanitized["doc_status"] = sanitized["estado_presentacion"]
    sanitized["dni_expedicion"] = str(entry.get("dni_expedicion") or "").strip()
    sanitized["dni_caducidad"] = str(entry.get("dni_caducidad") or "").strip()
    sanitized["dni_permanente"] = 1 if str(entry.get("dni_permanente") or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0
    sanitized["dni_label"] = renta_dni_label(sanitized)
    sanitized["pendiente_presentacion"] = 1 if sanitized["estado_presentacion"] == "Borrador" else 0
    return sanitized


def sanitize_renta_entries(entries):
    return [sanitize_renta_entry(entry) for entry in entries if isinstance(entry, dict)]


def collect_gestoria_renta_card_items(conn, empresa_id, q="", estado="", limit=50):
    q_norm = str(q or "").strip().lower()
    estado_norm = normalize_lookup_text(estado or "")
    try:
        limit_val = int(limit)
    except Exception:
        limit_val = 50
    limit_val = max(1, min(limit_val, 200))
    service_filter = (
        "LOWER(ce.servicio) IN ('gestoria', 'gestoría', "
        "'administracion fincas', 'administración fincas')"
    )
    rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          c.nombre,
          c.nif,
          c.telefono,
          c.email,
          c.estado AS cliente_estado,
          c.fecha_nacimiento,
          c.poblacion,
          c.provincia,
          cg.tipo_cliente,
          cg.renta_detalles,
          ce.estado AS servicio_estado
        FROM cliente_gestoria cg
        JOIN clientes c ON c.id = cg.cliente_id
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id = ?
          AND {service_filter}
          AND COALESCE(cg.mod_renta, 0) = 1
        ORDER BY c.updated_at DESC, c.nombre COLLATE NOCASE ASC
        """,
        (empresa_id,),
    ).fetchall()
    items = []
    for row in rows:
        servicio_estado = str(row["servicio_estado"] or row["cliente_estado"] or "").strip()
        if estado_norm and normalize_lookup_text(servicio_estado) != estado_norm:
            continue
        search_blob = " ".join(
            [
                str(row["nombre"] or ""),
                str(row["nif"] or ""),
                str(row["email"] or ""),
                str(row["telefono"] or ""),
                str(row["poblacion"] or ""),
                str(row["provincia"] or ""),
            ]
        ).lower()
        if q_norm and q_norm not in search_blob:
            continue
        renta_payload = parse_renta_detalles_payload(row["renta_detalles"])
        entries = sanitize_renta_entries(sort_renta_entries(renta_payload.get("entries") or []))
        latest = entries[0] if entries else {}
        docs = conn.execute(
            """
            SELECT id, nombre, tipo, fecha, estado, notas, doc_key, doc_url, referencia_tipo, referencia_id
            FROM gestoria_docs
            WHERE cliente_id = ?
              AND (
                LOWER(COALESCE(referencia_tipo, '')) = 'renta'
                OR LOWER(COALESCE(tipo, '')) = 'renta'
                OR LOWER(COALESCE(tipo, '')) = 'declaracion de renta'
                OR LOWER(COALESCE(nombre, '')) LIKE 'renta %'
              )
            ORDER BY date(COALESCE(fecha, '0001-01-01')) DESC, updated_at DESC
            """,
            (row["cliente_id"],),
        ).fetchall()
        docs_list = [dict(doc) for doc in docs]
        pending_presentacion = 1 if latest and normalize_renta_presentacion_status(latest.get("estado_presentacion")) == "Borrador" else 0
        items.append(
            {
                "cliente_id": row["cliente_id"],
                "nombre": row["nombre"],
                "nif": row["nif"],
                "telefono": row["telefono"],
                "email": row["email"],
                "fecha_nacimiento": row["fecha_nacimiento"],
                "poblacion": row["poblacion"],
                "provincia": row["provincia"],
                "tipo_cliente": row["tipo_cliente"],
                "estado": servicio_estado or "Alta",
                "renta_notes": renta_payload.get("notes") or "",
                "renta_entries": entries,
                "renta_latest": latest,
                "renta_entry_count": len(entries),
                "renta_pendiente_presentacion": pending_presentacion,
                "docs": docs_list,
                "doc_count": len(docs_list),
                "preview_doc": docs_list[0] if docs_list else {},
            }
        )
        if len(items) >= limit_val:
            break
    return items


def serialize_renta_detalles_payload(raw_value, existing_value=""):
    current = parse_renta_detalles_payload(existing_value)
    if isinstance(raw_value, dict):
        payload = raw_value
    else:
        text = str(raw_value or "").strip()
        if not text:
            payload = {"notes": "", "entries": current.get("entries", [])}
        else:
            try:
                payload = json.loads(text)
            except Exception:
                payload = {
                    "notes": text,
                    "entries": current.get("entries", []),
                }
    if isinstance(payload, list):
        payload = {"notes": current.get("notes", ""), "entries": payload}
    if not isinstance(payload, dict):
        payload = {
            "notes": current.get("notes", ""),
            "entries": current.get("entries", []),
            "related_cliente_id": current.get("related_cliente_id", ""),
            "related_relation_id": current.get("related_relation_id", ""),
            "declaracion_conjunta": current.get("declaracion_conjunta", 0),
        }
    notes = str(payload.get("notes") or "").strip()
    entries = payload.get("entries")
    if not isinstance(entries, list):
        entries = current.get("entries", [])
    related_cliente_id = str(
        payload["related_cliente_id"] if "related_cliente_id" in payload else current.get("related_cliente_id") or ""
    ).strip()
    related_relation_id = str(
        payload["related_relation_id"] if "related_relation_id" in payload else current.get("related_relation_id") or ""
    ).strip()
    declaracion_raw = (
        payload["declaracion_conjunta"]
        if "declaracion_conjunta" in payload
        else current.get("declaracion_conjunta", 0)
    )
    declaracion_conjunta = 1 if str(declaracion_raw or "").strip().lower() in {"1", "true", "yes", "si", "sí"} else 0
    return json.dumps(
        {
            "notes": notes,
            "entries": entries,
            "related_cliente_id": related_cliente_id,
            "related_relation_id": related_relation_id,
            "declaracion_conjunta": declaracion_conjunta,
        },
        ensure_ascii=False,
    )


def upsert_cliente_renta_entry(conn, cliente_id, entry_payload, now):
    row = conn.execute(
        "SELECT renta_detalles FROM cliente_gestoria WHERE cliente_id = ?",
        (cliente_id,),
    ).fetchone()
    current = parse_renta_detalles_payload(row["renta_detalles"] if row else "")
    entries = sanitize_renta_entries(current.get("entries") or [])
    entry_id = str(entry_payload.get("id") or "").strip()
    next_entries = []
    replaced = False
    for item in entries:
        same_entry = entry_id and str(item.get("id") or "").strip() == entry_id
        if same_entry:
            merged = dict(item)
            merged.update(entry_payload)
            merged["estado_presentacion"] = normalize_renta_presentacion_status(
                merged.get("estado_presentacion") or merged.get("doc_status")
            )
            merged["doc_status"] = merged["estado_presentacion"]
            next_entries.append(merged)
            replaced = True
        else:
            next_entries.append(item)
    if not replaced:
        fresh = dict(entry_payload)
        fresh["estado_presentacion"] = normalize_renta_presentacion_status(
            fresh.get("estado_presentacion") or fresh.get("doc_status")
        )
        fresh["doc_status"] = fresh["estado_presentacion"]
        next_entries.append(fresh)
    payload = {
        "notes": current.get("notes") or "",
        "entries": sort_renta_entries(next_entries),
        "related_cliente_id": current.get("related_cliente_id") or "",
        "related_relation_id": current.get("related_relation_id") or "",
        "declaracion_conjunta": current.get("declaracion_conjunta", 0),
    }
    serialized = json.dumps(payload, ensure_ascii=False)
    if row:
        conn.execute(
            """
            UPDATE cliente_gestoria
            SET mod_renta = 1, renta_detalles = ?, updated_at = datetime(?)
            WHERE cliente_id = ?
            """,
            (serialized, now, cliente_id),
        )
    else:
        conn.execute(
            """
            INSERT INTO cliente_gestoria (
              id, cliente_id, tipo_cliente, mod_fiscal, mod_laboral, mod_contable,
              mod_renta, mod_registro, mod_trafico, mod_puntuales, renta_detalles, created_at, updated_at
            ) VALUES (
              ?, ?, 'Particular', 0, 0, 0, 1, 0, 0, 0, ?, datetime(?), datetime(?)
            )
            """,
            (uuid.uuid4().hex, cliente_id, serialized, now, now),
        )
    return payload


def fetch_cliente_relaciones(conn, cliente_id):
    table_row = conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'cliente_relaciones'"
    ).fetchone()
    if not table_row:
        return []
    rows = conn.execute(
        """
        SELECT
          r.id,
          r.cliente_id,
          r.related_cliente_id,
          r.vinculo,
          r.notas,
          r.usar_en_renta,
          r.usar_en_seguros,
          r.usar_en_inmobiliaria,
          r.declaracion_conjunta,
          r.created_at,
          r.updated_at,
          c1.nombre AS cliente_nombre,
          c1.nif AS cliente_nif,
          c2.nombre AS related_cliente_nombre,
          c2.nif AS related_cliente_nif
        FROM cliente_relaciones r
        LEFT JOIN clientes c1 ON c1.id = r.cliente_id
        LEFT JOIN clientes c2 ON c2.id = r.related_cliente_id
        WHERE r.cliente_id = ? OR r.related_cliente_id = ?
        ORDER BY LOWER(COALESCE(r.vinculo, '')), LOWER(COALESCE(c1.nombre, '')), LOWER(COALESCE(c2.nombre, ''))
        """,
        (cliente_id, cliente_id),
    ).fetchall()
    items = []
    for row in rows:
        row_dict = dict(row)
        is_reverse = str(row_dict.get("related_cliente_id") or "") == str(cliente_id)
        counterpart_id = row_dict.get("cliente_id") if is_reverse else row_dict.get("related_cliente_id")
        counterpart_nombre = row_dict.get("cliente_nombre") if is_reverse else row_dict.get("related_cliente_nombre")
        counterpart_nif = row_dict.get("cliente_nif") if is_reverse else row_dict.get("related_cliente_nif")
        row_dict["counterpart_id"] = counterpart_id
        row_dict["counterpart_nombre"] = counterpart_nombre
        row_dict["counterpart_nif"] = counterpart_nif
        row_dict["is_reverse"] = is_reverse
        items.append(row_dict)
    return items


def build_cliente_ficha_payload(conn, cliente_id, services_filter=None):
    cliente = conn.execute("SELECT * FROM clientes WHERE id = ?", (cliente_id,)).fetchone()
    if not cliente:
        return None
    services_filter = services_filter or []
    if services_filter and not cliente_has_servicio(conn, cliente_id, services_filter):
        return {"error": "Cliente no disponible para este servicio"}

    empresas_query = """
        SELECT ce.id AS rel_id, ce.empresa_id, e.nombre AS empresa, ce.servicio, ce.estado,
               ce.fecha_inicio, ce.fecha_fin
        FROM clientes_empresas ce
        LEFT JOIN empresas e ON e.id = ce.empresa_id
        WHERE ce.cliente_id = ?
    """
    values = [cliente_id]
    if services_filter:
        placeholders = ",".join(["?"] * len(services_filter))
        empresas_query += f" AND LOWER(ce.servicio) IN ({placeholders})"
        values.extend(services_filter)
    empresas_query += " ORDER BY e.nombre"
    empresas = [dict(r) for r in conn.execute(empresas_query, values).fetchall()]

    service_keys = []
    allowed_keys = {"gestoria", "seguros", "inmobiliaria", "financiaciones"}
    for row in empresas:
        service_key = normalize_service_key(row.get("servicio"))
        active = is_active_service_state(row.get("estado"), row.get("fecha_fin"))
        row["servicio_key"] = service_key
        row["is_active"] = active
        if not active:
            continue
        if service_key == "hipotecas":
            service_key = "financiaciones"
        if service_key in allowed_keys and service_key not in service_keys:
            service_keys.append(service_key)
    empresa_ids = [row["empresa_id"] for row in empresas if row.get("empresa_id")]

    seguros_rows = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, cliente_id, empresa_id, compania, ramo, poliza_numero, fecha_efecto, fecha_vencimiento,
                   estado, prima_neta, prima_total, tomador, estado_renovacion, renovacion_fecha,
                   nueva_poliza_ref, colaborador, produccion, mes_creacion,
                   poliza_key, poliza_url, fecha_baja, motivo_baja
            FROM seguros
            WHERE cliente_id = ?
            ORDER BY COALESCE(fecha_efecto, created_at) DESC
            """,
            (cliente_id,),
        ).fetchall()
    ]
    for row in seguros_rows:
        row.update(compute_seguro_display(row))

    docs_rows = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, referencia_tipo, referencia_id, nombre, tipo, fecha,
                   estado, notas, doc_key, doc_url
            FROM gestoria_docs
            WHERE cliente_id = ?
            ORDER BY created_at DESC
            """,
            (cliente_id,),
        ).fetchall()
    ]
    docs_by_service = {"seguros": [], "gestoria": [], "financiaciones": [], "inmobiliaria": [], "otros": []}
    for row in docs_rows:
        key = normalize_service_key(row.get("referencia_tipo") or row.get("tipo"))
        if key not in docs_by_service:
            key = "otros"
        docs_by_service[key].append(row)

    facturas = []
    if empresa_ids:
        placeholders = ",".join(["?"] * len(empresa_ids))
        raw_facturas = conn.execute(
            f"""
            SELECT id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas
            FROM gestoria_contabilidad
            WHERE empresa_id IN ({placeholders})
            ORDER BY fecha DESC, created_at DESC
            LIMIT 1000
            """,
            [*empresa_ids],
        ).fetchall()
        for raw_row in raw_facturas:
            row = dict(raw_row)
            asignados = parse_cliente_ids_payload(row.get("cliente_ids_json"))
            if not asignados and row.get("cliente_id"):
                asignados = [str(row.get("cliente_id")).strip()]
            if cliente_id not in asignados:
                continue
            reparto = 1.0 / max(1, len(asignados))
            importe_original = parse_money_value(row.get("importe"))
            row["importe_asignado"] = round(importe_original * reparto, 2)
            row["clientes_reparto"] = asignados
            facturas.append(row)
        facturas = facturas[:500]
    fact_total = sum(
        parse_money_value(row.get("importe_asignado") if row.get("importe_asignado") not in (None, "") else row.get("importe"))
        for row in facturas
        if normalize_lookup_text(row.get("tipo")) != "GASTO"
    )

    trabajos = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, tipo_trabajo, estado, fecha_inicio, fecha_fin, responsable, importe, notas
            FROM gestoria_trabajos
            WHERE cliente_id = ?
            ORDER BY COALESCE(fecha_fin, fecha_inicio, created_at) DESC
            LIMIT 500
            """,
            (cliente_id,),
        ).fetchall()
    ]

    acciones = [
        dict(r)
        for r in conn.execute(
            """
            SELECT id, empresa_id, cliente_id, fecha, hora, tipo, responsable, estado, notas, servicio, recordatorio_min
            FROM acciones
            WHERE cliente_id = ?
            ORDER BY fecha DESC, hora DESC
            LIMIT 500
            """,
            (cliente_id,),
        ).fetchall()
    ]

    historico = []
    for row in trabajos:
        historico.append(
            {
                "fecha": row.get("fecha_fin") or row.get("fecha_inicio") or "",
                "servicio": "gestoria",
                "concepto": row.get("tipo_trabajo") or "Trabajo",
                "estado": row.get("estado") or "-",
                "importe": row.get("importe"),
            }
        )
    for row in seguros_rows:
        historico.append(
            {
                "fecha": row.get("vencimiento_display") or row.get("fecha_efecto") or "",
                "servicio": "seguros",
                "concepto": f"{row.get('compania') or 'Seguro'} {row.get('poliza_numero') or ''}".strip(),
                "estado": row.get("estado_display") or row.get("estado") or "-",
                "importe": row.get("prima_total"),
            }
        )
    historico.sort(key=lambda r: str(r.get("fecha") or ""), reverse=True)

    pendientes_trabajos = sum(
        1
        for row in trabajos
        if "FINAL" not in normalize_lookup_text(row.get("estado"))
        and "CANCEL" not in normalize_lookup_text(row.get("estado"))
    )
    pendientes_acciones = sum(
        1
        for row in acciones
        if all(
            token not in normalize_lookup_text(row.get("estado"))
            for token in ("HECHO", "FINAL", "CANCEL")
        )
    )
    today = datetime.now(timezone.utc).date()
    citas_programadas = [
        row
        for row in acciones
        if parse_iso_date(row.get("fecha")) and parse_iso_date(row.get("fecha")) >= today
    ]
    primas_total = sum(parse_money_value(row.get("prima_total")) for row in seguros_rows)
    realizado = sum(
        parse_money_value(row.get("importe"))
        for row in trabajos
        if "FINAL" in normalize_lookup_text(row.get("estado"))
    )
    cobrado = fact_total
    rentabilidad = cobrado - realizado

    profesionales = {
        "gestoria": {},
        "seguros": {
            "polizas_total": len(seguros_rows),
            "companias": sorted(
                {str(row.get("compania") or "").strip() for row in seguros_rows if str(row.get("compania") or "").strip()}
            ),
        },
    }
    gestoria_row = conn.execute(
        """
        SELECT tipo_cliente, mod_fiscal, mod_laboral, mod_contable, mod_renta, mod_registro, mod_trafico, mod_puntuales, renta_detalles
        FROM cliente_gestoria
        WHERE cliente_id = ?
        """,
        (cliente_id,),
    ).fetchone()
    if gestoria_row:
        gestoria_payload = dict(gestoria_row)
        renta_payload = parse_renta_detalles_payload(gestoria_payload.get("renta_detalles"))
        gestoria_payload["renta_notes"] = renta_payload.get("notes", "")
        gestoria_payload["renta_entries"] = sanitize_renta_entries(renta_payload.get("entries", []))
        gestoria_payload["renta_related_cliente_id"] = renta_payload.get("related_cliente_id", "")
        gestoria_payload["renta_related_relation_id"] = renta_payload.get("related_relation_id", "")
        gestoria_payload["renta_declaracion_conjunta"] = renta_payload.get("declaracion_conjunta", 0)
        profesionales["gestoria"] = gestoria_payload
    relaciones = fetch_cliente_relaciones(conn, cliente_id)
    asesoramientos_table = conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'asesoramientos_financiacion'"
    ).fetchone()
    datos_economicos = None
    if asesoramientos_table:
        datos_economicos = conn.execute(
            """
            SELECT *
            FROM asesoramientos_financiacion
            WHERE cliente1_id = ? OR cliente2_id = ?
            ORDER BY datetime(COALESCE(updated_at, created_at)) DESC
            LIMIT 1
            """,
            (cliente_id, cliente_id),
        ).fetchone()

    return {
        "cliente": dict(cliente),
        "datos_personales": dict(cliente),
        "empresas": empresas,
        "relaciones": relaciones,
        "servicios_activos": service_keys,
        "datos_profesionales_por_servicio": profesionales,
        "datos_economicos": dict(datos_economicos) if datos_economicos else {},
        "servicios": {
            "seguros": seguros_rows,
            "gestoria_trabajos": trabajos,
            "acciones": acciones,
        },
        "documentacion": {
            "all": docs_rows,
            "by_service": docs_by_service,
        },
        "facturas": facturas,
        "historico": historico[:500],
        "dashboard": {
            "rentabilidad": {
                "realizado": realizado,
                "cobrado": cobrado,
                "margen": rentabilidad,
            },
            "primas_total": primas_total,
            "tareas_pendientes": pendientes_trabajos + pendientes_acciones,
            "citas_programadas": len(citas_programadas),
            "proxima_cita": min(
                [row["fecha"] for row in citas_programadas if row.get("fecha")],
                default="",
            ),
            "series": {
                "rentabilidad": [
                    {"label": "Realizado", "value": realizado},
                    {"label": "Cobrado", "value": cobrado},
                    {"label": "Margen", "value": rentabilidad},
                ],
                "actividad": [
                    {"label": "Primas", "value": primas_total},
                    {"label": "Pendientes", "value": pendientes_trabajos + pendientes_acciones},
                    {"label": "Citas", "value": len(citas_programadas)},
                ],
            },
        },
    }

def ensure_cliente_for_financiacion(conn, empresa_id, nombre, nif, now, extra=None):
    if not nombre:
        return None
    nombre = str(nombre).strip()
    nif = (nif or "").strip()
    extra = extra or {}
    cliente = None
    if nif:
        cliente = conn.execute(
            "SELECT id FROM clientes WHERE nif = ?",
            (nif,),
        ).fetchone()
    if not cliente:
        cliente = conn.execute(
            "SELECT id FROM clientes WHERE nombre = ?",
            (nombre,),
        ).fetchone()
    if not cliente:
        tipo_persona = None
        if nif:
            if re.match(r"^[0-9]{8}[A-Z]$", nif):
                tipo_persona = "Física"
            elif re.match(r"^[A-Z][0-9]{7}[0-9A-Z]$", nif):
                tipo_persona = "Jurídica"
        cliente_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO clientes (
              id, nombre, tipo_persona, nif, telefono, email, fecha_nacimiento, direccion, estado, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                cliente_id,
                nombre,
                tipo_persona,
                nif or None,
                extra.get("telefono"),
                extra.get("email"),
                extra.get("fecha_nacimiento"),
                extra.get("direccion"),
                "Activo",
                now,
                now,
            ),
        )
    else:
        cliente_id = cliente["id"]
        updates = {}
        if nif:
            updates["nif"] = nif
        for key in ("telefono", "email", "fecha_nacimiento", "direccion"):
            value = extra.get(key)
            if value:
                updates[key] = value
        if updates:
            set_clause = ", ".join([f"{key} = COALESCE({key}, ?)" for key in updates])
            values = list(updates.values()) + [now, cliente_id]
            conn.execute(
                f"UPDATE clientes SET {set_clause}, updated_at = datetime(?) WHERE id = ?",
                values,
            )
    link = conn.execute(
        """
        SELECT id FROM clientes_empresas
        WHERE cliente_id = ? AND empresa_id = ? AND servicio = ?
        """,
        (cliente_id, empresa_id, "financiaciones"),
    ).fetchone()
    if not link:
        conn.execute(
            """
            INSERT INTO clientes_empresas (
              id, cliente_id, empresa_id, servicio, estado,
              fecha_inicio, fecha_fin, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                cliente_id,
                empresa_id,
                "financiaciones",
                "Activo",
                None,
                None,
                now,
                now,
            ),
        )
    return cliente_id


def get_empresa_by_nombre(conn, nombre):
    nombre = str(nombre or "").strip()
    if not nombre:
        return None
    return conn.execute(
        "SELECT * FROM empresas WHERE nombre = ? LIMIT 1",
        (nombre,),
    ).fetchone()


def build_financiacion_context_note(inmueble_row, action_row):
    parts = []
    direccion = str((inmueble_row or {}).get("direccion") or "").strip()
    if direccion:
        parts.append(f"Inmueble: {direccion}")
    if inmueble_row:
        precio = parse_money_value(inmueble_row.get("precio_objetivo"))
        if precio > 0:
            parts.append(f"Precio objetivo: {precio:.2f} EUR")
    if action_row:
        fecha = str(action_row.get("fecha") or "").strip()
        if fecha:
            parts.append(f"Cita origen: {fecha}")
    return " | ".join(parts)


def ensure_financiacion_opportunity_from_inmo(
    conn,
    fin_empresa_id,
    inmueble_row,
    cliente_row,
    action_row,
    now,
):
    cliente_id = str((cliente_row or {}).get("id") or "").strip()
    inmueble_id = str((inmueble_row or {}).get("id") or "").strip()
    action_id = str((action_row or {}).get("id") or "").strip()
    if not fin_empresa_id or not cliente_id:
        return None
    existing = conn.execute(
        """
        SELECT id
        FROM acciones
        WHERE servicio = 'financiaciones'
          AND empresa_id = ?
          AND cliente_id = ?
          AND inmueble_id = ?
          AND tipo = 'Oportunidad hipotecaria'
          AND notas LIKE ?
        LIMIT 1
        """,
        (fin_empresa_id, cliente_id, inmueble_id or None, f"%Acción origen: {action_id}%"),
    ).fetchone()
    if existing:
        return existing["id"]
    context_note = build_financiacion_context_note(inmueble_row, action_row)
    notas = f"Lead generado desde visita inmobiliaria. Acción origen: {action_id}."
    if context_note:
        notas = f"{notas} {context_note}"
    opportunity_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO acciones (
          id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
          fecha, hora, tipo, responsable, estado, notas, created_at, updated_at
        ) VALUES (
          ?, ?, 'financiaciones', ?, ?, ?, date('now'), '10:00', ?, ?, 'Pendiente', ?, datetime(?), datetime(?)
        )
        """,
        (
            opportunity_id,
            fin_empresa_id,
            cliente_id,
            inmueble_id or None,
            str((cliente_row or {}).get("nombre") or "").strip(),
            "Oportunidad hipotecaria",
            str((action_row or {}).get("responsable") or "").strip() or None,
            notas,
            now,
            now,
        ),
    )
    return opportunity_id


def ensure_financiacion_asesoramiento_from_inmo(
    conn,
    fin_empresa_id,
    inmueble_row,
    cliente_row,
    action_row,
    now,
    *,
    fin_data=None,
):
    cliente_id = str((cliente_row or {}).get("id") or "").strip()
    inmueble_id = str((inmueble_row or {}).get("id") or "").strip()
    action_id = str((action_row or {}).get("id") or "").strip()
    if not fin_empresa_id or not cliente_id:
        return None, []
    existing = conn.execute(
        """
        SELECT *
        FROM asesoramientos_financiacion
        WHERE empresa_id = ?
          AND cliente1_id = ?
          AND COALESCE(inmueble_id, '') = ?
          AND COALESCE(accion_origen_id, '') = ?
        LIMIT 1
        """,
        (fin_empresa_id, cliente_id, inmueble_id, action_id),
    ).fetchone()
    profesion = conn.execute(
        """
        SELECT actividad
        FROM cliente_profesional
        WHERE cliente_id = ?
        ORDER BY principal DESC, created_at ASC
        LIMIT 1
        """,
        (cliente_id,),
    ).fetchone()
    fin_data = fin_data or {}
    context_note = build_financiacion_context_note(inmueble_row, action_row)
    notas = "Asesoramiento generado desde Inmobiliaria."
    if context_note:
        notas = f"{notas} {context_note}"
    notas_extra = str(fin_data.get("notas") or "").strip()
    if notas_extra:
        notas = f"{notas} {notas_extra}"
    ingreso1_val = parse_money_value(fin_data.get("cliente1_ingresos"))
    ingreso2_val = parse_money_value(fin_data.get("cliente2_ingresos"))
    ingresos_conjuntos_val = parse_money_value(fin_data.get("ingresos_conjuntos"))
    if ingresos_conjuntos_val <= 0:
        ingresos_conjuntos_val = round((ingreso1_val or 0.0) + (ingreso2_val or 0.0), 2)
    aportacion_val = parse_money_value(fin_data.get("aportacion_cv"))
    if existing:
        updates = {}
        for field in (
            "cliente1_nombre",
            "cliente1_dni",
            "cliente1_telefono",
            "cliente1_email",
            "cliente1_fecha_nacimiento",
            "cliente1_estado_civil",
            "cliente1_hijos",
            "cliente1_profesion",
            "cliente1_tipo_contrato",
            "cliente1_tiempo_contrato",
            "cliente1_patrimonio",
            "cliente1_prestamos",
            "cliente2_nombre",
            "cliente2_dni",
            "cliente2_telefono",
            "cliente2_email",
            "cliente2_fecha_nacimiento",
            "cliente2_estado_civil",
            "cliente2_hijos",
            "cliente2_profesion",
            "cliente2_tipo_contrato",
            "cliente2_tiempo_contrato",
            "cliente2_patrimonio",
            "cliente2_prestamos",
            "entidades_financieras",
            "avalistas",
        ):
            incoming = str(fin_data.get(field) or "").strip()
            if incoming and not str(existing[field] or "").strip():
                updates[field] = incoming
        if ingreso1_val > 0 and not parse_money_value(existing["cliente1_ingresos"]):
            updates["cliente1_ingresos"] = ingreso1_val
        if ingreso2_val > 0 and not parse_money_value(existing["cliente2_ingresos"]):
            updates["cliente2_ingresos"] = ingreso2_val
        if ingresos_conjuntos_val > 0 and not parse_money_value(existing["ingresos_conjuntos"]):
            updates["ingresos_conjuntos"] = ingresos_conjuntos_val
        if aportacion_val > 0 and not parse_money_value(existing["aportacion_cv"]):
            updates["aportacion_cv"] = aportacion_val
        if not str(existing["cliente1_profesion"] or "").strip() and profesion and str(profesion["actividad"] or "").strip():
            updates["cliente1_profesion"] = str(profesion["actividad"] or "").strip()
        if notas and not str(existing["notas"] or "").strip():
            updates["notas"] = notas
        if updates:
            set_clause = ", ".join([f"{key} = ?" for key in updates])
            values = list(updates.values()) + [now, existing["id"]]
            conn.execute(
                f"UPDATE asesoramientos_financiacion SET {set_clause}, updated_at = datetime(?) WHERE id = ?",
                values,
            )
        asesoramiento_id = existing["id"]
    else:
        asesoramiento_id = os.urandom(16).hex()
        conn.execute(
            """
            INSERT INTO asesoramientos_financiacion (
              id, empresa_id, origen, inmueble_id, accion_origen_id, inmobiliaria_asesor, asesor, fecha, estado,
              cliente1_id, cliente1_nombre, cliente1_dni, cliente1_telefono, cliente1_email,
              cliente1_fecha_nacimiento, cliente1_estado_civil, cliente1_hijos, cliente1_profesion, cliente1_tipo_contrato,
              cliente1_tiempo_contrato, cliente1_ingresos, cliente1_patrimonio, cliente1_prestamos,
              cliente2_nombre, cliente2_dni, cliente2_telefono, cliente2_email, cliente2_fecha_nacimiento,
              cliente2_estado_civil, cliente2_hijos, cliente2_profesion, cliente2_tipo_contrato, cliente2_tiempo_contrato,
              cliente2_ingresos, cliente2_patrimonio, cliente2_prestamos,
              ingresos_conjuntos, entidades_financieras, avalistas, aportacion_cv, notas, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                asesoramiento_id,
                fin_empresa_id,
                "Inmobiliaria",
                inmueble_id or None,
                action_id or None,
                str((action_row or {}).get("responsable") or "").strip() or None,
                None,
                str((action_row or {}).get("fecha") or "").strip() or datetime.now().strftime("%Y-%m-%d"),
                "En estudio",
                cliente_id,
                str(fin_data.get("cliente1_nombre") or (cliente_row or {}).get("nombre") or "").strip() or None,
                normalize_nif(fin_data.get("cliente1_dni") or (cliente_row or {}).get("nif")),
                str(fin_data.get("cliente1_telefono") or (cliente_row or {}).get("telefono") or "").strip() or None,
                normalize_email(fin_data.get("cliente1_email") or (cliente_row or {}).get("email")),
                str(fin_data.get("cliente1_fecha_nacimiento") or (cliente_row or {}).get("fecha_nacimiento") or "").strip() or None,
                str(fin_data.get("cliente1_estado_civil") or "").strip() or None,
                str(fin_data.get("cliente1_hijos") or "").strip() or None,
                str(fin_data.get("cliente1_profesion") or (profesion["actividad"] if profesion else "") or "").strip() or None,
                str(fin_data.get("cliente1_tipo_contrato") or "").strip() or None,
                str(fin_data.get("cliente1_tiempo_contrato") or "").strip() or None,
                ingreso1_val or None,
                str(fin_data.get("cliente1_patrimonio") or "").strip() or None,
                str(fin_data.get("cliente1_prestamos") or "").strip() or None,
                str(fin_data.get("cliente2_nombre") or "").strip() or None,
                normalize_nif(fin_data.get("cliente2_dni")),
                str(fin_data.get("cliente2_telefono") or "").strip() or None,
                normalize_email(fin_data.get("cliente2_email")),
                str(fin_data.get("cliente2_fecha_nacimiento") or "").strip() or None,
                str(fin_data.get("cliente2_estado_civil") or "").strip() or None,
                str(fin_data.get("cliente2_hijos") or "").strip() or None,
                str(fin_data.get("cliente2_profesion") or "").strip() or None,
                str(fin_data.get("cliente2_tipo_contrato") or "").strip() or None,
                str(fin_data.get("cliente2_tiempo_contrato") or "").strip() or None,
                ingreso2_val or None,
                str(fin_data.get("cliente2_patrimonio") or "").strip() or None,
                str(fin_data.get("cliente2_prestamos") or "").strip() or None,
                ingresos_conjuntos_val or None,
                str(fin_data.get("entidades_financieras") or "").strip() or None,
                str(fin_data.get("avalistas") or "").strip() or None,
                aportacion_val or None,
                notas,
                now,
                now,
            ),
        )
    row = conn.execute(
        "SELECT * FROM asesoramientos_financiacion WHERE id = ? LIMIT 1",
        (asesoramiento_id,),
    ).fetchone()
    missing = fin_missing_fields(row) if row else []
    fin_sync_missing_action(
        conn,
        fin_empresa_id,
        asesoramiento_id,
        cliente_id,
        str((cliente_row or {}).get("nombre") or "").strip(),
        missing,
        now,
    )
    return asesoramiento_id, missing

