def ensure_usuarios_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS usuarios (
          id TEXT PRIMARY KEY,
          nombre TEXT NOT NULL,
          apellido TEXT,
          usuario TEXT UNIQUE,
          email TEXT UNIQUE,
          servicio TEXT,
          rol TEXT,
          password_hash TEXT,
          activo INTEGER DEFAULT 1,
          invite_token TEXT,
          invite_expires_at TEXT,
          invite_sent_at TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        )
        """
    )
    ensure_column(conn, "usuarios", "apellido", "apellido TEXT")
    ensure_column(conn, "usuarios", "usuario", "usuario TEXT")
    ensure_column(conn, "usuarios", "email", "email TEXT")
    ensure_column(conn, "usuarios", "servicio", "servicio TEXT")
    ensure_column(conn, "usuarios", "password_hash", "password_hash TEXT")
    ensure_column(conn, "usuarios", "invite_token", "invite_token TEXT")
    ensure_column(conn, "usuarios", "invite_expires_at", "invite_expires_at TEXT")
    ensure_column(conn, "usuarios", "invite_sent_at", "invite_sent_at TEXT")
    users_count = conn.execute("SELECT COUNT(*) AS total FROM usuarios").fetchone()
    total_users = 0
    if users_count:
        try:
            total_users = users_count["total"]
        except (TypeError, KeyError, IndexError):
            total_users = users_count[0]
    if total_users == 0:
        conn.execute(
            "INSERT INTO usuarios (id, nombre, apellido, usuario, email, servicio, rol, activo, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))",
            (os.urandom(16).hex(), "Administrador", "General", "admin", "admin@liv.local", "Administración", "Administrador", 1),
        )


