def parse_workspace_automation_config(raw):
    if raw in (None, ""):
        return {}
    if isinstance(raw, dict):
        return raw
    try:
        value = json.loads(str(raw))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _normalize_to_list(value):
    if value in (None, "", []):
        return []
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    return [item.strip() for item in str(value).split(",") if item.strip()]


def workspace_automation_matches(config, context):
    conditions = config.get("conditions") if isinstance(config.get("conditions"), dict) else {}
    servicios = {normalize_service_key(item) for item in _normalize_to_list(conditions.get("servicios"))}
    servicio = normalize_service_key(context.get("servicio") or "")
    if servicios and servicio not in servicios:
        return False, "servicio fuera de condición"
    metodos = {item.lower() for item in _normalize_to_list(conditions.get("metodos"))}
    metodo = str(context.get("metodo") or "").strip().lower()
    if metodos and metodo not in metodos:
        return False, "método fuera de condición"
    estados = {item.lower() for item in _normalize_to_list(conditions.get("estados"))}
    estado = str(context.get("estado") or "").strip().lower()
    if estados and estado not in estados:
        return False, "estado fuera de condición"
    required_keys = _normalize_to_list(conditions.get("required_keys"))
    for key in required_keys:
        if not context.get(key):
            return False, f"falta {key}"
    min_importe = conditions.get("min_importe")
    if min_importe not in (None, ""):
        if float(context.get("importe") or context.get("total") or 0.0) < float(min_importe):
            return False, "importe por debajo del mínimo"
    return True, ""


def apply_workspace_automation_effects(conn, workspace_id, automation_row, config, context, now):
    actions = config.get("actions") if isinstance(config.get("actions"), dict) else {}
    if not actions and any(key in config for key in ("inbox_estado", "portal_request", "create_action")):
        actions = dict(config)
    effect_count = 0
    if actions.get("create_action", True):
        empresa_id = context.get("empresa_id") or fetch_workspace_company_ids(conn, workspace_id)[:1]
        empresa_id = empresa_id[0] if isinstance(empresa_id, list) else empresa_id
        if empresa_id:
            detalle = (automation_row["action_summary"] or "").strip() or f"Automatización {automation_row['nombre']}"
            conn.execute(
                """
                INSERT INTO acciones (
                  id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
                  fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
                ) VALUES (
                  ?, ?, ?, ?, ?, ?, date(?), time(?), ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    (automation_row["modulo_key"] or context.get("servicio") or "gestoria").strip(),
                    context.get("cliente_id"),
                    context.get("inmueble_id"),
                    context.get("cliente_nombre"),
                    now,
                    now,
                    automation_row["nombre"],
                    actions.get("responsable") or context.get("responsable"),
                    actions.get("action_estado") or "Pendiente",
                    detalle,
                    int(actions.get("recordatorio_min") or 60),
                    now,
                    now,
                ),
            )
            effect_count += 1
    inbox_estado = (actions.get("inbox_estado") or "").strip()
    if inbox_estado and context.get("document_id"):
        conn.execute(
            "UPDATE workspace_documentos_inbox SET estado = ?, updated_at = datetime(?) WHERE id = ? AND workspace_id = ?",
            (inbox_estado, now, context.get("document_id"), workspace_id),
        )
        effect_count += 1
    portal_request = actions.get("portal_request")
    if isinstance(portal_request, dict) and context.get("portal_cliente_id"):
        due_days = int(portal_request.get("days_due") or 0)
        due_date = None
        if due_days > 0:
            try:
                due_date = (datetime.fromisoformat(str(now).replace("Z", "")) + timedelta(days=due_days)).date().isoformat()
            except Exception:
                due_date = None
        conn.execute(
            """
            INSERT INTO workspace_portal_requerimientos (
              id, workspace_id, portal_cliente_id, cliente_id, servicio, titulo, descripcion,
              prioridad, estado, fecha_limite, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                context.get("portal_cliente_id"),
                context.get("cliente_id"),
                (portal_request.get("servicio") or context.get("servicio") or "").strip() or None,
                (portal_request.get("titulo") or automation_row["nombre"]).strip(),
                (portal_request.get("descripcion") or automation_row["action_summary"] or "").strip() or None,
                (portal_request.get("prioridad") or "Normal").strip(),
                (portal_request.get("estado") or "Pendiente").strip(),
                due_date or (portal_request.get("fecha_limite") or None),
                now,
                now,
            ),
        )
        effect_count += 1
    return effect_count


def run_workspace_automations(conn, workspace_id, trigger_key, context, now):
    rows = conn.execute(
        """
        SELECT id, nombre, trigger_key, modulo_key, enabled, action_summary, config_json
        FROM workspace_automatizaciones
        WHERE workspace_id = ? AND trigger_key = ? AND COALESCE(enabled, 1) = 1
        ORDER BY updated_at DESC, created_at DESC
        """,
        (workspace_id, trigger_key),
    ).fetchall()
    created = 0
    for row in rows:
        config = parse_workspace_automation_config(row["config_json"])
        matches, reason = workspace_automation_matches(config, context)
        detalle = (row["action_summary"] or "").strip() or f"Automatización {row['nombre']}"
        if matches:
            created += apply_workspace_automation_effects(conn, workspace_id, row, config, context, now)
        conn.execute(
            """
            INSERT INTO workspace_automatizacion_logs (
              id, workspace_id, automatizacion_id, trigger_key, estado, detalle, payload_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
            """,
            (
                os.urandom(16).hex(),
                workspace_id,
                row["id"],
                trigger_key,
                "ejecutada" if matches else "omitida",
                detalle if matches else f"{detalle} · {reason}",
                json.dumps(context, ensure_ascii=False),
                now,
            ),
        )
    return created


def fetch_workspace_portal_public(conn, token):
    row = conn.execute(
        """
        SELECT
          p.workspace_id,
          p.cliente_id,
          p.estado,
          p.token,
          p.ultimo_acceso_at,
          c.nombre AS cliente_nombre,
          COALESCE(c.email, '') AS email,
          w.nombre AS workspace_nombre
        FROM workspace_portal_clientes p
        JOIN clientes c ON c.id = p.cliente_id
        JOIN workspaces w ON w.id = p.workspace_id
        WHERE p.token = ?
        LIMIT 1
        """,
        (token,),
    ).fetchone()
    if not row:
        return None
    conn.execute(
        "UPDATE workspace_portal_clientes SET ultimo_acceso_at = datetime(?) WHERE token = ?",
        (datetime.now(timezone.utc).isoformat(), token),
    )
    conn.commit()
    docs = conn.execute(
        """
        SELECT nombre, clasificacion, estado, created_at
        FROM workspace_documentos_inbox
        WHERE workspace_id = ? AND COALESCE(cliente_id, suggested_cliente_id) = ?
        ORDER BY updated_at DESC, created_at DESC
        LIMIT 10
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    bills = conn.execute(
        """
        SELECT id, concepto, fecha_emision, total, estado, cobrada
        FROM workspace_facturacion
        WHERE workspace_id = ? AND cliente_id = ?
        ORDER BY COALESCE(fecha_emision, created_at) DESC
        LIMIT 10
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    requests = conn.execute(
        """
        SELECT id, titulo, descripcion, clasificacion, prioridad, estado, fecha_limite, completed_at
        FROM workspace_portal_requerimientos
        WHERE workspace_id = ? AND cliente_id = ?
        ORDER BY
          CASE COALESCE(estado, 'Pendiente')
            WHEN 'Pendiente' THEN 0
            WHEN 'Enviado' THEN 1
            WHEN 'Recibido' THEN 2
            WHEN 'Completado' THEN 3
            ELSE 9
          END,
          COALESCE(fecha_limite, created_at) ASC
        LIMIT 12
        """,
        (row["workspace_id"], row["cliente_id"]),
    ).fetchall()
    return {
        "workspace": row["workspace_nombre"],
        "cliente": row["cliente_nombre"],
        "estado": row["estado"],
        "email": row["email"],
        "docs": [dict(item) for item in docs],
        "facturas": [dict(item) for item in bills],
        "requerimientos": [dict(item) for item in requests],
    }


def fetch_workspace_invoice_pdf_payload(conn, invoice_id, workspace_id=None, token=None):
    portal_scope = None
    if token:
        portal_scope = conn.execute(
            """
            SELECT workspace_id, cliente_id
            FROM workspace_portal_clientes
            WHERE token = ?
            LIMIT 1
            """,
            (token,),
        ).fetchone()
        if not portal_scope:
            return None
        workspace_id = portal_scope["workspace_id"]
    if not invoice_id or not workspace_id:
        return None
    invoice = conn.execute(
        """
        SELECT wf.*, COALESCE(w.nombre, '') AS workspace_nombre, COALESCE(e.nombre, '') AS empresa_nombre,
               COALESCE(c.nombre, '') AS cliente_nombre, COALESCE(c.nif, '') AS cliente_nif, COALESCE(c.email, '') AS cliente_email
        FROM workspace_facturacion wf
        LEFT JOIN workspaces w ON w.id = wf.workspace_id
        LEFT JOIN empresas e ON e.id = wf.empresa_id
        LEFT JOIN clientes c ON c.id = wf.cliente_id
        WHERE wf.id = ? AND wf.workspace_id = ?
        LIMIT 1
        """,
        (invoice_id, workspace_id),
    ).fetchone()
    if not invoice:
        return None
    if portal_scope and str(invoice["cliente_id"] or "") != str(portal_scope["cliente_id"] or ""):
        return None
    collections = conn.execute(
        """
        SELECT fecha_cobro, metodo, importe, referencia
        FROM workspace_facturacion_cobros
        WHERE factura_id = ?
        ORDER BY COALESCE(fecha_cobro, created_at) ASC
        """,
        (invoice_id,),
    ).fetchall()
    return {
        "invoice": dict(invoice),
        "workspace": {"nombre": invoice["workspace_nombre"]},
        "company": {"nombre": invoice["empresa_nombre"]},
        "client": {"nombre": invoice["cliente_nombre"], "nif": invoice["cliente_nif"], "email": invoice["cliente_email"]},
        "collections": [dict(row) for row in collections],
    }


def fetch_workspace_budget_pdf_payload(conn, budget_id, workspace_id=None):
    if not budget_id or not workspace_id:
        return None
    budget = conn.execute(
        """
        SELECT
          p.*,
          COALESCE(w.nombre, '') AS workspace_nombre,
          COALESCE(w.primary_color, '') AS workspace_primary_color,
          COALESCE(w.accent_color, '') AS workspace_accent_color,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(e.logo_url, '') AS empresa_logo_url,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE(c.email, '') AS cliente_email,
          COALESCE(c.telefono, '') AS cliente_telefono
        FROM workspace_presupuestos p
        LEFT JOIN workspaces w ON w.id = p.workspace_id
        LEFT JOIN empresas e ON e.id = p.empresa_id
        LEFT JOIN clientes c ON c.id = p.cliente_id
        WHERE p.id = ? AND p.workspace_id = ?
        LIMIT 1
        """,
        (budget_id, workspace_id),
    ).fetchone()
    if not budget:
        return None
    lineas = conn.execute(
        """
        SELECT orden, categoria, concepto, cantidad, unidad, precio_unitario, descuento_pct, total_linea
        FROM workspace_presupuesto_lineas
        WHERE presupuesto_id = ?
        ORDER BY orden ASC, created_at ASC
        """,
        (budget_id,),
    ).fetchall()
    return {
        "budget": dict(budget),
        "workspace": {
            "nombre": budget["workspace_nombre"],
            "primary_color": budget["workspace_primary_color"],
            "accent_color": budget["workspace_accent_color"],
        },
        "company": {"nombre": budget["empresa_nombre"], "logo_url": budget["empresa_logo_url"]},
        "client": {
            "nombre": budget["cliente_nombre"],
            "nif": budget["cliente_nif"],
            "email": budget["cliente_email"],
            "telefono": budget["cliente_telefono"],
        },
        "lineas": [dict(row) for row in lineas],
    }


def fetch_workspace_budget_encargo_payload(conn, budget_id, workspace_id=None):
    return fetch_workspace_budget_pdf_payload(conn, budget_id, workspace_id=workspace_id)


def fetch_workspace_detail(conn, workspace_id):
    workspace = conn.execute(
        """
        SELECT id, nombre, slug, estado, plan, descripcion, logo_url, primary_color, accent_color
        FROM workspaces
        WHERE id = ?
        LIMIT 1
        """,
        (workspace_id,),
    ).fetchone()
    if not workspace:
        return None
    companies = conn.execute(
        """
        SELECT e.id, e.nombre, COALESCE(we.rol, '') AS rol, COALESCE(e.activo, 1) AS activo
        FROM workspace_empresas we
        JOIN empresas e ON e.id = we.empresa_id
        WHERE we.workspace_id = ?
        ORDER BY e.nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    modules = conn.execute(
        """
        SELECT id, modulo_key, modulo_nombre, categoria, enabled, sort_order, config_json
        FROM workspace_modulos
        WHERE workspace_id = ?
        ORDER BY sort_order ASC, modulo_nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    module_rows = [dict(row) for row in modules]
    enabled_keys = [row["modulo_key"] for row in module_rows if int(row.get("enabled") or 0) == 1]
    plan_name = str(workspace["plan"] or "Enterprise")
    package = dict(WORKSPACE_PLAN_PACKAGES.get(plan_name, WORKSPACE_PLAN_PACKAGES["Enterprise"]))
    package["enabled_focus_total"] = sum(1 for key in package.get("focus", []) if key in enabled_keys)
    package["enabled_modules_total"] = len(enabled_keys)
    permission_matrix = []
    profiles = [
        ("Dirección", {"crm360", "dashboard", "documental", "gestoria", "seguros", "inmobiliaria", "financiacion", "fincas", "facturacion", "facturas_recibidas", "portal_cliente", "registro_horario", "automatizaciones"}),
        ("Operaciones", {"crm360", "dashboard", "documental", "gestoria", "facturacion", "facturas_recibidas", "portal_cliente", "registro_horario"}),
        ("Comercial", {"crm360", "dashboard", "documental", "seguros", "inmobiliaria", "financiacion", "portal_cliente"}),
        ("Backoffice", {"crm360", "documental", "gestoria", "facturacion", "facturas_recibidas", "fincas", "registro_horario"}),
    ]
    for role_name, allowed_modules in profiles:
        granted = [row["modulo_nombre"] for row in module_rows if row["modulo_key"] in enabled_keys and row["modulo_key"] in allowed_modules]
        permission_matrix.append(
            {
                "perfil": role_name,
                "modules_total": len(granted),
                "modules": granted,
            }
        )
    return {
        "workspace": dict(workspace),
        "companies": [dict(row) for row in companies],
        "modules": module_rows,
        "commercial_package": package,
        "permission_matrix": permission_matrix,
    }


def fetch_workspace_billing_summary(conn, workspace_id):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {
            "facturas_emitidas": 0,
            "facturacion_total": 0.0,
            "cobrado_total": 0.0,
            "pendiente_total": 0.0,
            "potencial_operativo": 0.0,
            "cobros_registrados": 0,
            "remesas_total": 0.0,
            "servicios": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    fact_rows = conn.execute(
        f"""
        SELECT
          COALESCE(servicio, 'sin_servicio') AS servicio,
          COUNT(*) AS total_facturas,
          SUM(COALESCE(total, 0)) AS total_facturado,
          SUM(CASE WHEN COALESCE(cobrada, 0) = 1 THEN COALESCE(total, 0) ELSE 0 END) AS total_cobrado
        FROM workspace_facturacion
        WHERE workspace_id = ?
          AND empresa_id IN ({placeholders})
        GROUP BY COALESCE(servicio, 'sin_servicio')
        ORDER BY total_facturado DESC
        """,
        [workspace_id, *empresa_ids],
    ).fetchall()
    facturas_emitidas = sum(int(row["total_facturas"] or 0) for row in fact_rows)
    facturacion_total = round(sum(float(row["total_facturado"] or 0.0) for row in fact_rows), 2)
    cobrado_total = round(sum(float(row["total_cobrado"] or 0.0) for row in fact_rows), 2)
    pendiente_total = round(max(facturacion_total - cobrado_total, 0.0), 2)

    potential_rows = []
    seguros = conn.execute(
        f"""
        SELECT 'seguros' AS servicio, SUM(COALESCE(comision, 0)) AS total
        FROM seguros
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if seguros and seguros["total"] is not None:
        potential_rows.append({"servicio": "seguros", "total": float(seguros["total"] or 0.0)})
    inmo = conn.execute(
        f"""
        SELECT 'inmobiliaria' AS servicio, SUM(COALESCE(honorarios, 0)) AS total
        FROM operaciones_inmobiliarias
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if inmo and inmo["total"] is not None:
        potential_rows.append({"servicio": "inmobiliaria", "total": float(inmo["total"] or 0.0)})
    fin = conn.execute(
        f"""
        SELECT 'financiacion' AS servicio, SUM(COALESCE(comision, 0)) AS total
        FROM hipotecas
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if fin and fin["total"] is not None:
        potential_rows.append({"servicio": "financiacion", "total": float(fin["total"] or 0.0)})
    gest = conn.execute(
        f"""
        SELECT 'gestoria' AS servicio, SUM(COALESCE(importe, 0)) AS total
        FROM gestoria_trabajos
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    if gest and gest["total"] is not None:
        potential_rows.append({"servicio": "gestoria", "total": float(gest["total"] or 0.0)})
    potencial_operativo = round(sum(float(item["total"] or 0.0) for item in potential_rows), 2)
    cobros = conn.execute(
        """
        SELECT COUNT(*) AS total_cobros, SUM(CASE WHEN COALESCE(metodo, '') = 'Remesa' THEN COALESCE(importe, 0) ELSE 0 END) AS total_remesas
        FROM workspace_facturacion_cobros
        WHERE workspace_id = ?
        """,
        (workspace_id,),
    ).fetchone()
    services = [
        {
            "servicio": row["servicio"],
            "facturas": int(row["total_facturas"] or 0),
            "facturado": round(float(row["total_facturado"] or 0.0), 2),
            "cobrado": round(float(row["total_cobrado"] or 0.0), 2),
        }
        for row in fact_rows
    ]
    potential_map = {item["servicio"]: round(float(item["total"] or 0.0), 2) for item in potential_rows}
    for service_name, total in potential_map.items():
        existing = next((item for item in services if item["servicio"] == service_name), None)
        if existing:
            existing["potencial"] = total
        else:
            services.append(
                {
                    "servicio": service_name,
                    "facturas": 0,
                    "facturado": 0.0,
                    "cobrado": 0.0,
                    "potencial": total,
                }
            )
    services.sort(key=lambda item: float(item.get("facturado") or item.get("potencial") or 0.0), reverse=True)
    return {
        "facturas_emitidas": facturas_emitidas,
        "facturacion_total": facturacion_total,
        "cobrado_total": cobrado_total,
        "pendiente_total": pendiente_total,
        "potencial_operativo": potencial_operativo,
        "cobros_registrados": int((cobros["total_cobros"] if cobros else 0) or 0),
        "remesas_total": round(float((cobros["total_remesas"] if cobros else 0) or 0.0), 2),
        "servicios": services,
    }


def fetch_workspace_billing_rows(conn, workspace_id, limit=25):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {"rows": []}
    placeholders = ",".join(["?"] * len(empresa_ids))
    rows = conn.execute(
        f"""
        SELECT
          wf.id,
          wf.workspace_id,
          wf.empresa_id,
          wf.cliente_id,
          wf.servicio,
          wf.origen_tipo,
          wf.origen_id,
          wf.serie,
          wf.numero,
          wf.fecha_emision,
          wf.fecha_vencimiento,
          wf.concepto,
          wf.subtotal,
          wf.impuestos,
          wf.total,
          wf.estado,
          wf.remesa_id,
          wf.conciliacion_estado,
          wf.cobrada,
          wf.fecha_cobro,
          wf.forma_cobro,
          wf.responsable,
          wf.notas,
          wf.created_at,
          wf.updated_at,
          COALESCE(e.nombre, '') AS empresa_nombre,
          COALESCE(c.nombre, '') AS cliente_nombre,
          COALESCE(c.nif, '') AS cliente_nif,
          COALESCE((SELECT SUM(COALESCE(col.importe, 0)) FROM workspace_facturacion_cobros col WHERE col.factura_id = wf.id AND COALESCE(col.estado, 'Aplicado') != 'Devuelto'), 0) AS cobrado_total,
          MAX(COALESCE(wf.total, 0) - COALESCE((SELECT SUM(COALESCE(col.importe, 0)) FROM workspace_facturacion_cobros col WHERE col.factura_id = wf.id AND COALESCE(col.estado, 'Aplicado') != 'Devuelto'), 0), 0) AS saldo_pendiente
        FROM workspace_facturacion wf
        LEFT JOIN empresas e ON e.id = wf.empresa_id
        LEFT JOIN clientes c ON c.id = wf.cliente_id
        WHERE wf.workspace_id = ?
          AND wf.empresa_id IN ({placeholders})
        ORDER BY COALESCE(wf.fecha_emision, wf.created_at) DESC, wf.updated_at DESC
        LIMIT ?
        """,
        [workspace_id, *empresa_ids, max(1, min(int(limit or 25), 100))],
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def fetch_workspace_health(conn, workspace_id):
    workspace_detail = fetch_workspace_detail(conn, workspace_id)
    if not workspace_detail:
        return None
    workspace = workspace_detail["workspace"]
    modules = workspace_detail["modules"]
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {
            "readiness_score": 0,
            "checklist": [],
            "module_health": [],
            "summary": {
                "clientes": 0,
                "documentos": 0,
                "facturas": 0,
            },
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    clientes_total = conn.execute(
        f"""
        SELECT COUNT(DISTINCT ce.cliente_id)
        FROM clientes_empresas ce
        WHERE ce.empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()[0]
    docs_summary = fetch_workspace_document_hub(conn, workspace_id, limit=5)["summary"]
    billing_rows = fetch_workspace_billing_rows(conn, workspace_id, limit=5)["rows"]
    presupuesto_rows = fetch_workspace_presupuestos(conn, workspace_id, limit=5)["rows"]
    inbox_rows = fetch_workspace_inbox_queue(conn, workspace_id, limit=5)["rows"]
    portal_rows = fetch_workspace_portal_clients(conn, workspace_id, limit=5)["rows"]
    portal_requests = fetch_workspace_portal_requests(conn, workspace_id, limit=5)["rows"]
    automation_rows = fetch_workspace_automations(conn, workspace_id, limit=5)["rows"]
    billing_collections = fetch_workspace_billing_collections(conn, workspace_id, limit=5)["rows"]
    remittance_rows = fetch_workspace_remesas(conn, workspace_id, limit=5)["rows"]
    time_rows = fetch_workspace_time_entries(conn, workspace_id, limit=5)["rows"]
    fincas_communities = fetch_workspace_fincas_comunidades(conn, workspace_id, limit=5)["rows"]
    fincas_incidents = fetch_workspace_fincas_incidencias(conn, workspace_id, limit=5)["rows"]
    fincas_providers = fetch_workspace_fincas_proveedores(conn, workspace_id, limit=5)["rows"]
    fincas_meetings = fetch_workspace_fincas_juntas(conn, workspace_id, limit=5)["rows"]
    series_rows = fetch_workspace_series(conn, workspace_id)["rows"]
    facturas_total = conn.execute(
        f"""
        SELECT COUNT(*)
        FROM workspace_facturacion
        WHERE workspace_id = ? AND empresa_id IN ({placeholders})
        """,
        [workspace_id, *empresa_ids],
    ).fetchone()[0]
    seguros_total = conn.execute(
        f"SELECT COUNT(*) FROM seguros WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    gestoria_total = conn.execute(
        f"SELECT COUNT(*) FROM gestoria_trabajos WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    inmuebles_total = conn.execute(
        f"SELECT COUNT(*) FROM inmuebles WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    operaciones_total = conn.execute(
        f"SELECT COUNT(*) FROM operaciones_inmobiliarias WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    hipotecas_total = conn.execute(
        f"SELECT COUNT(*) FROM hipotecas WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    facturas_recibidas_total = conn.execute(
        f"SELECT COUNT(*) FROM gestoria_facturas WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()[0]
    enabled_modules = [row for row in modules if int(row.get("enabled") or 0) == 1]
    branding_ready = bool((workspace.get("descripcion") or "").strip() and (workspace.get("primary_color") or "").strip())
    checklist = [
        {
            "label": "Branding",
            "done": 1 if branding_ready else 0,
            "hint": "Nombre, descripción y colores definidos.",
        },
        {
            "label": "Empresas",
            "done": 1 if len(empresa_ids) > 0 else 0,
            "hint": f"{len(empresa_ids)} sociedades vinculadas al tenant.",
        },
        {
            "label": "Módulos activos",
            "done": 1 if len(enabled_modules) >= 3 else 0,
            "hint": f"{len(enabled_modules)} módulos habilitados.",
        },
        {
            "label": "Base CRM",
            "done": 1 if int(clientes_total or 0) > 0 else 0,
            "hint": f"{int(clientes_total or 0)} clientes dentro del workspace.",
        },
        {
            "label": "Documental",
            "done": 1 if int(docs_summary.get('documentos_total') or 0) > 0 else 0,
            "hint": f"{int(docs_summary.get('documentos_total') or 0)} documentos agregados.",
        },
        {
            "label": "Facturación",
            "done": 1 if int(facturas_total or 0) > 0 else 0,
            "hint": f"{int(facturas_total or 0)} movimientos transversales registrados.",
        },
        {
            "label": "Presupuestos",
            "done": 1 if len(presupuesto_rows) > 0 else 0,
            "hint": f"{len(presupuesto_rows)} propuestas comerciales cargadas.",
        },
        {
            "label": "Series",
            "done": 1 if len(series_rows) > 0 else 0,
            "hint": f"{len(series_rows)} series de facturación configuradas.",
        },
        {
            "label": "Portal cliente",
            "done": 1 if len(portal_rows) > 0 else 0,
            "hint": f"{len(portal_rows)} accesos de portal activados.",
        },
        {
            "label": "Automatizaciones",
            "done": 1 if len(automation_rows) > 0 else 0,
            "hint": f"{len(automation_rows)} reglas definidas en el workspace.",
        },
        {
            "label": "Inbox entrada",
            "done": 1 if len(inbox_rows) > 0 else 0,
            "hint": f"{len(inbox_rows)} documentos registrados en la bandeja de entrada.",
        },
    ]
    readiness_score = round((sum(item["done"] for item in checklist) / max(len(checklist), 1)) * 100)
    onboarding_actions = []
    if not branding_ready:
        onboarding_actions.append({"label": "Completar branding del tenant", "target": "workspaceForm", "priority": "alta"})
    if len(enabled_modules) < 3:
        onboarding_actions.append({"label": "Activar módulos núcleo y verticales mínimas", "target": "workspaceModules", "priority": "alta"})
    if int(clientes_total or 0) == 0:
        onboarding_actions.append({"label": "Cargar primeros clientes del tenant", "target": "workspaceLauncher", "priority": "alta"})
    if int(docs_summary.get("documentos_total") or 0) == 0:
        onboarding_actions.append({"label": "Subir documentación inicial al inbox", "target": "workspaceInboxForm", "priority": "media"})
    if int(facturas_total or 0) == 0:
        onboarding_actions.append({"label": "Emitir la primera factura transversal", "target": "workspaceBillingForm", "priority": "media"})
    if len(portal_rows) == 0:
        onboarding_actions.append({"label": "Invitar al menos un cliente al portal", "target": "workspacePortalForm", "priority": "media"})
    if len(automation_rows) == 0:
        onboarding_actions.append({"label": "Configurar la primera automatización del tenant", "target": "workspaceAutomationForm", "priority": "media"})
    go_live_status = "listo" if readiness_score >= 85 else ("implantacion" if readiness_score >= 60 else "bloqueado")
    metrics_by_module = {
        "crm360": (clientes_total, "clientes activos en el tenant", "Importar o crear clientes base."),
        "documental": (docs_summary.get("documentos_total") or 0, "documentos unificados", "Subir documentos y revisar asignaciones."),
        "dashboard": (len(billing_rows) + len(presupuesto_rows) + int(clientes_total or 0), "fuentes listas para cuadros de mando", "Conectar más datos operativos y facturación."),
        "gestoria": (gestoria_total, "trabajos de gestoría", "Cargar trabajos/campañas y responsables."),
        "seguros": (seguros_total, "pólizas o expedientes de seguros", "Importar cartera o cargar pólizas activas."),
        "inmobiliaria": (inmuebles_total + operaciones_total, "inmuebles y operaciones", "Cargar captaciones, inmuebles u operaciones."),
        "financiacion": (hipotecas_total, "hipotecas registradas", "Activar expedientes y pipeline financiero."),
        "fincas": (len(fincas_communities) + len(fincas_incidents) + len(fincas_providers) + len(fincas_meetings), "comunidades, incidencias y operativa de fincas", "Cargar comunidades, proveedores e incidencias."),
        "facturacion": (facturas_total + len(remittance_rows) + len(billing_collections), "facturas, cobros y remesas", "Emitir primeras facturas del tenant."),
        "facturas_recibidas": (facturas_recibidas_total + len(inbox_rows), "facturas recibidas o inbox", "Activar inbox de proveedores."),
        "portal_cliente": (len(portal_rows) + len(portal_requests), "clientes y requerimientos de portal", "Invitar clientes clave y crear requerimientos."),
        "registro_horario": (len(time_rows), "fichajes registrados", "Activar fichajes y política laboral."),
        "automatizaciones": (len(automation_rows), "automatizaciones configuradas", "Definir reglas por evento."),
    }
    module_health = []
    for module in modules:
        key = module.get("modulo_key") or ""
        metric_value, metric_label, next_step = metrics_by_module.get(key, (0, "sin métrica", "Completar configuración."))
        enabled = int(module.get("enabled") or 0) == 1
        status = "disabled"
        if enabled and metric_value:
            status = "operativo"
        elif enabled:
            status = "configuracion"
        module_health.append(
            {
                "key": key,
                "nombre": module.get("modulo_nombre") or key,
                "enabled": 1 if enabled else 0,
                "status": status,
                "metric_value": int(metric_value or 0),
                "metric_label": metric_label,
                "next_step": next_step,
            }
        )
    return {
        "readiness_score": readiness_score,
        "checklist": checklist,
        "go_live_status": go_live_status,
        "onboarding_actions": onboarding_actions[:6],
        "module_health": module_health,
        "summary": {
            "clientes": int(clientes_total or 0),
            "documentos": int(docs_summary.get("documentos_total") or 0),
            "facturas": int(facturas_total or 0),
            "presupuestos": len(presupuesto_rows),
            "cobros": len(billing_collections),
            "portal_requerimientos": len(portal_requests),
            "fichajes": len(time_rows),
            "comunidades": len(fincas_communities),
            "remesas": len(remittance_rows),
        },
    }


def suggest_workspace_document_cliente(candidates, text):
    normalized_text = normalize_lookup_text(text)
    if len(normalized_text) < 6:
        return None
    best = None
    best_score = 0
    stopwords = {"DE", "DEL", "LA", "LAS", "LOS", "Y", "EL"}
    for candidate in candidates:
        name = candidate.get("nombre") or ""
        nif = normalize_lookup_text(candidate.get("nif") or "")
        name_norm = normalize_lookup_text(name)
        score = 0
        if nif and len(nif) >= 6 and nif in normalized_text:
            score = 1000 + len(nif)
        elif name_norm and len(name_norm) >= 8 and name_norm in normalized_text:
            score = 100 + len(name_norm)
        else:
            tokens = [token for token in name_norm.split() if len(token) >= 4 and token not in stopwords]
            matched = [token for token in tokens if token in normalized_text]
            if len(matched) >= 2:
                score = sum(len(token) for token in matched)
        if score > best_score:
            best_score = score
            best = candidate
    if best_score < 8:
        return None
    return {
        "id": best["id"],
        "nombre": best.get("nombre") or "",
        "nif": best.get("nif") or "",
        "score": best_score,
    }


def fetch_workspace_document_hub(conn, workspace_id, limit=20):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {"rows": [], "summary": {"documentos_total": 0}}
    placeholders = ",".join(["?"] * len(empresa_ids))
    rows = conn.execute(
        f"""
        SELECT *
        FROM (
          SELECT
            d.id,
            'gestoria_docs' AS source_table,
            d.empresa_id,
            COALESCE(e.nombre, '') AS empresa,
            COALESCE(c.nombre, '') AS cliente,
            d.cliente_id,
            COALESCE(NULLIF(d.referencia_tipo, ''), 'gestoria') AS referencia_tipo,
            COALESCE(NULLIF(d.referencia_tipo, ''), d.tipo, 'gestoria') AS servicio,
            d.nombre,
            d.tipo,
            d.fecha,
            d.estado,
            d.notas,
            d.doc_key,
            d.doc_url,
            d.created_at AS sort_date
          FROM gestoria_docs d
          LEFT JOIN clientes c ON c.id = d.cliente_id
          LEFT JOIN empresas e ON e.id = d.empresa_id
          WHERE d.empresa_id IN ({placeholders})
          UNION ALL
          SELECT
            idoc.id,
            'inmueble_docs' AS source_table,
            i.empresa_id,
            COALESCE(e.nombre, '') AS empresa,
            COALESCE(i.direccion, '') AS cliente,
            NULL AS cliente_id,
            'inmobiliaria' AS referencia_tipo,
            'inmobiliaria' AS servicio,
            COALESCE(idoc.nombre, 'Documento inmueble') AS nombre,
            COALESCE(idoc.tipo, 'Inmueble') AS tipo,
            COALESCE(idoc.created_at, '') AS fecha,
            '' AS estado,
            '' AS notas,
            NULL AS doc_key,
            COALESCE(idoc.url, '') AS doc_url,
            idoc.created_at AS sort_date
          FROM inmueble_docs idoc
          JOIN inmuebles i ON i.id = idoc.inmueble_id
          LEFT JOIN empresas e ON e.id = i.empresa_id
          WHERE i.empresa_id IN ({placeholders})
        )
        ORDER BY COALESCE(fecha, sort_date) DESC, sort_date DESC
        LIMIT ?
        """,
        [*empresa_ids, *empresa_ids, max(1, min(int(limit or 20), 100))],
    ).fetchall()
    candidates = conn.execute(
        f"""
        SELECT DISTINCT c.id, c.nombre, COALESCE(c.nif, '') AS nif
        FROM clientes c
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id IN ({placeholders})
        ORDER BY LENGTH(COALESCE(c.nombre, '')) DESC, c.nombre COLLATE NOCASE ASC
        LIMIT 500
        """,
        empresa_ids,
    ).fetchall()
    candidate_rows = [dict(row) for row in candidates]
    processed_rows = []
    pending_assignments = 0
    for row in rows:
        item = dict(row)
        item["assignable"] = 1 if item.get("source_table") == "gestoria_docs" else 0
        item["suggested_cliente_id"] = ""
        item["suggested_cliente"] = ""
        if item["assignable"] and not item.get("cliente_id"):
            suggestion = suggest_workspace_document_cliente(
                candidate_rows,
                " ".join(
                    part
                    for part in [item.get("nombre"), item.get("notas"), item.get("tipo"), item.get("servicio")]
                    if part
                ),
            )
            if suggestion:
                item["suggested_cliente_id"] = suggestion["id"]
                item["suggested_cliente"] = suggestion["nombre"]
                pending_assignments += 1
        processed_rows.append(item)
    total_docs = conn.execute(
        f"""
        SELECT
          (SELECT COUNT(*) FROM gestoria_docs WHERE empresa_id IN ({placeholders}))
          +
          (SELECT COUNT(*) FROM inmueble_docs idoc JOIN inmuebles i ON i.id = idoc.inmueble_id WHERE i.empresa_id IN ({placeholders}))
          AS total
        """,
        [*empresa_ids, *empresa_ids],
    ).fetchone()
    return {
        "rows": processed_rows,
        "summary": {
            "documentos_total": int(total_docs["total"] or 0) if total_docs else 0,
            "pendientes_asignacion": pending_assignments,
        },
    }


def json_response(handler, data, status=200, cookies=None, extra_headers=None):
    payload = json.dumps(data, ensure_ascii=False).encode("utf-8")
    handler.send_response(status)
    handler.send_header("Access-Control-Allow-Origin", "*")
    handler.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
    handler.send_header("Access-Control-Allow-Headers", "Content-Type")
    for key, value in (extra_headers or []):
        handler.send_header(key, value)
    for cookie_value in (cookies or []):
        handler.send_header("Set-Cookie", cookie_value)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(payload)))
    handler.end_headers()
    handler.wfile.write(payload)


def binary_response(handler, data, content_type="application/octet-stream", filename=None, status=200):
    payload = data or b""
    handler.send_response(status)
    handler.send_header("Access-Control-Allow-Origin", "*")
    handler.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
    handler.send_header("Access-Control-Allow-Headers", "Content-Type")
    handler.send_header("Content-Type", content_type)
    if filename:
        handler.send_header("Content-Disposition", f'attachment; filename="{filename}"')
    handler.send_header("Content-Length", str(len(payload)))
    handler.end_headers()
    handler.wfile.write(payload)


def _pdf_escape(value):
    return str(value or "").replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def format_eur(value):
    amount = float(value or 0.0)
    raw = f"{amount:,.2f}"
    return raw.replace(",", "X").replace(".", ",").replace("X", ".") + " EUR"


def build_workspace_invoice_pdf(invoice, workspace, company, client, collections):
    lines = [
        workspace.get("nombre") or "Workspace",
        company.get("nombre") or "Empresa",
        "",
        f"Factura: {'-'.join(part for part in [invoice.get('serie'), invoice.get('numero')] if part) or invoice.get('id') or '-'}",
        f"Fecha emisión: {invoice.get('fecha_emision') or '-'}",
        f"Fecha vencimiento: {invoice.get('fecha_vencimiento') or '-'}",
        f"Estado: {invoice.get('estado') or '-'}",
        f"Cliente: {client.get('nombre') or '-'}",
        f"NIF: {client.get('nif') or '-'}",
        "",
        f"Concepto: {invoice.get('concepto') or '-'}",
        f"Servicio: {invoice.get('servicio') or '-'}",
        "",
        f"Subtotal: {format_eur(invoice.get('subtotal'))}",
        f"Impuestos: {format_eur(invoice.get('impuestos'))}",
        f"Total: {format_eur(invoice.get('total'))}",
        f"Cobrado: {format_eur(sum(float(item.get('importe') or 0.0) for item in collections))}",
        f"Pendiente: {format_eur(max(float(invoice.get('total') or 0.0) - sum(float(item.get('importe') or 0.0) for item in collections), 0.0))}",
        "",
    ]
    if collections:
        lines.append("Cobros aplicados:")
        for item in collections[:8]:
            lines.append(
                f"- {item.get('fecha_cobro') or '-'} · {item.get('metodo') or '-'} · {format_eur(item.get('importe'))}"
            )
        lines.append("")
    if invoice.get("notas"):
        lines.append(f"Notas: {invoice.get('notas')}")
    font_obj = "1 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj\n"
    page_lines = []
    y = 800
    for raw in lines[:38]:
        page_lines.append(f"BT /F1 11 Tf 48 {y} Td ({_pdf_escape(raw)}) Tj ET")
        y -= 18
    content_stream = "\n".join(page_lines).encode("latin-1", "replace")
    objects = []
    objects.append("1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n")
    objects.append("2 0 obj << /Type /Pages /Count 1 /Kids [3 0 R] >> endobj\n")
    objects.append(
        "3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >> endobj\n"
    )
    objects.append(font_obj)
    objects.append(f"5 0 obj << /Length {len(content_stream)} >> stream\n".encode("latin-1") + content_stream + b"\nendstream\nendobj\n")
    pdf = bytearray(b"%PDF-1.4\n")
    offsets = [0]
    for obj in objects:
        offsets.append(len(pdf))
        pdf.extend(obj if isinstance(obj, bytes) else obj.encode("latin-1"))
    xref_pos = len(pdf)
    pdf.extend(f"xref\n0 {len(offsets)}\n".encode("latin-1"))
    pdf.extend(b"0000000000 65535 f \n")
    for offset in offsets[1:]:
        pdf.extend(f"{offset:010d} 00000 n \n".encode("latin-1"))
    pdf.extend(f"trailer << /Size {len(offsets)} /Root 1 0 R >>\nstartxref\n{xref_pos}\n%%EOF\n".encode("latin-1"))
    return bytes(pdf)


def build_workspace_budget_pdf(budget, workspace, company, client, lineas):
    def hex_to_rgb(value, fallback):
        raw = str(value or "").strip().lstrip("#")
        if len(raw) == 3:
            raw = "".join(ch * 2 for ch in raw)
        if len(raw) != 6:
            return fallback
        try:
            return tuple(int(raw[i:i + 2], 16) for i in (0, 2, 4))
        except Exception:
            return fallback

    def draw_label_value(draw, x, y, width, label, value, label_font, value_font, label_fill, value_fill):
        draw.text((x, y), str(label or "").upper(), fill=label_fill, font=label_font)
        label_box = draw.textbbox((x, y), str(label or "").upper(), font=label_font)
        current_y = label_box[3] + 8
        wrapped = _pdf_wrap_lines(value, width=max(20, int(width / 11)))
        draw.multiline_text((x, current_y), "\n".join(wrapped), fill=value_fill, font=value_font, spacing=6)
        sample_box = draw.textbbox((x, current_y), "Ag", font=value_font)
        line_height = sample_box[3] - sample_box[1] + 6
        return current_y + max(line_height * len(wrapped), line_height)

    calc = {}
    try:
        calc = json.loads(budget.get("calculo_json") or "{}") if budget.get("calculo_json") else {}
        if not isinstance(calc, dict):
            calc = {}
    except Exception:
        calc = {}
    primary = hex_to_rgb(workspace.get("primary_color"), (60, 110, 113))
    accent = hex_to_rgb(workspace.get("accent_color"), (143, 155, 116))
    ink = (35, 40, 44)
    muted = (104, 111, 117)
    soft = (244, 246, 247)
    border = (223, 228, 231)
    page_width, page_height = 1240, 1754
    margin_x, top_margin, bottom_margin = 84, 72, 84
    logo = _load_brand_logo(company.get("logo_url"), max_width=360)
    font_title = _document_font(44, bold=True)
    font_subtitle = _document_font(20, bold=False)
    font_chip = _document_font(16, bold=True)
    font_section = _document_font(22, bold=True)
    font_label = _document_font(14, bold=True)
    font_value = _document_font(20, bold=False)
    font_table_head = _document_font(15, bold=True)
    font_table = _document_font(16, bold=False)
    font_total = _document_font(28, bold=True)
    font_footer = _document_font(14, bold=False)
    pages = []
    servicio_label = normalize_service_key(budget.get("servicio") or "") or "-"
    ref_label = budget.get("id") or "-"

    def new_page(include_cards=False):
        image = Image.new("RGB", (page_width, page_height), "white")
        draw = ImageDraw.Draw(image)
        draw.rounded_rectangle((0, 0, page_width, 250), radius=0, fill=primary)
        draw.polygon([(page_width - 220, 0), (page_width, 0), (page_width, 180)], fill=accent)
        draw.text((margin_x, top_margin), "PRESUPUESTO", fill="white", font=font_title)
        draw.text((margin_x, top_margin + 62), company.get("nombre") or workspace.get("nombre") or "Workspace", fill=(240, 246, 248), font=font_subtitle)
        chip_y = top_margin + 116
        chips = [
            f"REF {ref_label[:12]}",
            f"FECHA {budget.get('fecha') or '-'}",
            f"ESTADO {budget.get('estado') or 'Borrador'}",
            f"SERVICIO {servicio_label.upper()}",
        ]
        chip_x = margin_x
        for chip in chips:
            box = draw.textbbox((chip_x, chip_y), chip, font=font_chip)
            chip_w = (box[2] - box[0]) + 30
            draw.rounded_rectangle((chip_x, chip_y - 8, chip_x + chip_w, chip_y + 26), radius=18, fill=(94, 137, 139), outline=(255, 255, 255))
            draw.text((chip_x + 15, chip_y), chip, fill="white", font=font_chip)
            chip_x += chip_w + 12
        if logo:
            image.paste(logo, (page_width - margin_x - logo.width, top_margin + 8), logo)
        current_y = 296
        if include_cards:
            left = (margin_x, current_y, margin_x + 560, current_y + 250)
            right = (page_width - margin_x - 420, current_y, page_width - margin_x, current_y + 250)
            draw.rounded_rectangle(left, radius=28, fill=soft, outline=border)
            draw.rounded_rectangle(right, radius=28, fill=(250, 247, 240), outline=border)
            draw.text((left[0] + 24, left[1] + 22), "CLIENTE", fill=primary, font=font_section)
            y_client = left[1] + 64
            y_client = draw_label_value(draw, left[0] + 24, y_client, 500, "Nombre", client.get("nombre") or "-", font_label, font_value, muted, ink)
            y_client = draw_label_value(draw, left[0] + 24, y_client + 10, 220, "NIF", client.get("nif") or "-", font_label, font_value, muted, ink)
            y_client = draw_label_value(draw, left[0] + 250, left[1] + 64, 250, "Teléfono", client.get("telefono") or "-", font_label, font_value, muted, ink)
            draw_label_value(draw, left[0] + 250, left[1] + 150, 250, "Email", client.get("email") or "-", font_label, _document_font(16, False), muted, ink)
            draw.text((right[0] + 24, right[1] + 22), "RESUMEN ECONÓMICO", fill=primary, font=font_section)
            draw.text((right[0] + 24, right[1] + 82), "TOTAL", fill=muted, font=font_label)
            draw.text((right[0] + 24, right[1] + 108), format_eur(budget.get("total") or 0), fill=ink, font=font_total)
            draw.text((right[0] + 24, right[1] + 170), f"Subtotal {format_eur(budget.get('subtotal') or 0)}", fill=ink, font=font_table)
            draw.text((right[0] + 24, right[1] + 198), f"Impuestos {format_eur(budget.get('impuestos') or 0)}", fill=ink, font=font_table)
            draw.text((right[0] + 24, right[1] + 226), f"Pago {budget.get('forma_pago') or 'Pendiente'}", fill=ink, font=font_table)
            current_y = left[3] + 34
        return image, draw, current_y

    image, draw, y = new_page(include_cards=True)
    usable_bottom = page_height - bottom_margin

    def ensure_space(required_height):
        nonlocal image, draw, y
        if y + required_height <= usable_bottom:
            return
        pages.append(image)
        image, draw, y = new_page(include_cards=False)

    if normalize_service_key(budget.get("servicio") or "") == "administracion fincas":
        ensure_space(120)
        box = (margin_x, y, page_width - margin_x, y + 100)
        draw.rounded_rectangle(box, radius=24, fill=(247, 250, 242), outline=border)
        draw.text((box[0] + 24, box[1] + 18), "BASE DE CÁLCULO COMUNIDAD", fill=primary, font=font_section)
        base_text = (
            f"{calc.get('num_vecinos') or 0} vecinos · "
            f"{calc.get('num_locales') or 0} locales · "
            f"{calc.get('num_trasteros') or 0} trasteros · "
            f"{calc.get('num_aparcamientos') or 0} aparcamientos · "
            f"Base sugerida {format_eur(calc.get('cuota_sugerida') or 0)}"
        )
        draw.text((box[0] + 24, box[1] + 58), base_text, fill=ink, font=font_table)
        y = box[3] + 24

    ensure_space(70)
    draw.text((margin_x, y), "PARTIDAS PRESUPUESTADAS", fill=primary, font=font_section)
    y += 42
    columns = {
        "concepto": (margin_x, 650),
        "cantidad": (770, 90),
        "precio": (880, 130),
        "dto": (1028, 72),
        "total": (1114, 110),
    }
    header_h = 40
    draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + header_h), radius=16, fill=primary)
    draw.text((columns["concepto"][0] + 18, y + 10), "PARTIDA", fill="white", font=font_table_head)
    draw.text((columns["cantidad"][0], y + 10), "CANT.", fill="white", font=font_table_head)
    draw.text((columns["precio"][0], y + 10), "PRECIO", fill="white", font=font_table_head)
    draw.text((columns["dto"][0], y + 10), "DTO", fill="white", font=font_table_head)
    draw.text((columns["total"][0], y + 10), "TOTAL", fill="white", font=font_table_head)
    y += header_h + 10
    row_fill = (249, 250, 251)
    for index, line in enumerate(lineas or [{"categoria": "Partida", "concepto": budget.get("titulo") or "-", "cantidad": 1, "unidad": "", "precio_unitario": budget.get("subtotal") or budget.get("total") or 0, "descuento_pct": 0, "total_linea": budget.get("subtotal") or budget.get("total") or 0}], start=1):
        concept = f"{line.get('categoria') or 'Partida'} · {line.get('concepto') or '-'}"
        concept_lines = _pdf_wrap_lines(concept, width=54)
        row_h = 54 + max(0, len(concept_lines) - 1) * 20
        ensure_space(row_h + 12)
        fill = row_fill if index % 2 else (255, 255, 255)
        draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + row_h), radius=14, fill=fill, outline=border)
        draw.multiline_text((columns["concepto"][0] + 18, y + 12), "\n".join(concept_lines), fill=ink, font=font_table, spacing=4)
        qty_text = f"{_pdf_format_number(line.get('cantidad'), 2) or '0'} {line.get('unidad') or ''}".strip()
        draw.text((columns["cantidad"][0], y + 16), qty_text, fill=ink, font=font_table)
        draw.text((columns["precio"][0], y + 16), format_eur(line.get("precio_unitario") or 0), fill=ink, font=font_table)
        draw.text((columns["dto"][0], y + 16), f"{_pdf_format_number(line.get('descuento_pct'), 2) or '0'}%", fill=ink, font=font_table)
        draw.text((columns["total"][0], y + 16), format_eur(line.get("total_linea") or 0), fill=ink, font=font_table)
        y += row_h + 10

    ensure_space(180)
    totals_box = (page_width - margin_x - 360, y + 10, page_width - margin_x, y + 170)
    draw.rounded_rectangle(totals_box, radius=26, fill=soft, outline=border)
    draw.text((totals_box[0] + 24, totals_box[1] + 22), "CIERRE ECONÓMICO", fill=primary, font=font_section)
    draw.text((totals_box[0] + 24, totals_box[1] + 72), f"Subtotal  {format_eur(budget.get('subtotal') or 0)}", fill=ink, font=font_table)
    draw.text((totals_box[0] + 24, totals_box[1] + 102), f"Impuestos {format_eur(budget.get('impuestos') or 0)}", fill=ink, font=font_table)
    draw.text((totals_box[0] + 24, totals_box[1] + 132), f"Total     {format_eur(budget.get('total') or 0)}", fill=ink, font=_document_font(20, True))
    left_text_top = y + 18
    draw.text((margin_x, left_text_top), "RESPONSABLE", fill=muted, font=font_label)
    draw.text((margin_x, left_text_top + 24), budget.get("responsable") or "-", fill=ink, font=font_table)
    draw.text((margin_x, left_text_top + 68), "FORMA DE PAGO", fill=muted, font=font_label)
    draw.text((margin_x, left_text_top + 92), budget.get("forma_pago") or "Pendiente de definir", fill=ink, font=font_table)
    y = totals_box[3] + 24

    if budget.get("observaciones"):
        ensure_space(160)
        draw.text((margin_x, y), "OBSERVACIONES", fill=primary, font=font_section)
        y += 36
        obs_lines = _pdf_wrap_lines(budget.get("observaciones"), width=98)
        draw.rounded_rectangle((margin_x, y, page_width - margin_x, y + 38 + len(obs_lines) * 22), radius=20, fill=(252, 252, 252), outline=border)
        draw.multiline_text((margin_x + 20, y + 18), "\n".join(obs_lines), fill=ink, font=font_table, spacing=6)
        y += 50 + len(obs_lines) * 22

    footer_text = f"Documento emitido por {company.get('nombre') or workspace.get('nombre') or 'Workspace'}. Presupuesto editable y sujeto a aceptación expresa del cliente."
    footer_lines = _pdf_wrap_lines(footer_text, width=108)
    draw.line((margin_x, page_height - bottom_margin - 28, page_width - margin_x, page_height - bottom_margin - 28), fill=border, width=2)
    draw.multiline_text((margin_x, page_height - bottom_margin), "\n".join(footer_lines), fill=muted, font=font_footer, spacing=4)

    pages.append(image)
    buffer = BytesIO()
    if len(pages) == 1:
        pages[0].save(buffer, format="PDF", resolution=150.0)
    else:
        pages[0].save(buffer, format="PDF", resolution=150.0, save_all=True, append_images=pages[1:])
    return buffer.getvalue()


