        if path == "/api/compraventas":
            empresa_id = params.get("empresa_id", [""])[0]
            q = params.get("q", [""])[0].strip()
            if not empresa_id:
                json_response(self, {"error": "empresa_id requerido"}, status=400)
                return
            where = ["empresa_id = ?", "LOWER(COALESCE(tipo_operacion, 'venta')) = 'venta'"]
            values = [empresa_id]
            if q:
                where.append(
                    "("
                    "direccion LIKE ? OR referencia_catastral LIKE ? OR "
                    "propietario1_nombre LIKE ? OR propietario2_nombre LIKE ? OR contraparte_nombre LIKE ? OR "
                    "responsable_gestion LIKE ? OR agente LIKE ? OR oficina LIKE ? OR estado LIKE ? OR origen LIKE ?"
                    ")"
                )
                values.extend([f"%{q}%"] * 10)
            rows = conn.execute(
                f"""
                SELECT
                  id,
                  direccion,
                  referencia_catastral,
                  TRIM(
                    COALESCE(propietario1_nombre, '')
                    || CASE WHEN TRIM(COALESCE(propietario2_nombre, '')) <> '' THEN ' | ' || TRIM(propietario2_nombre) ELSE '' END
                  ) AS vendedores,
                  contraparte_nombre AS compradores,
                  fecha_encargo,
                  fecha_propuesta,
                  fecha_contrato,
                  fecha_escritura,
                  precio_encargo,
                  CASE
                    WHEN COALESCE(precio_contrato, 0) >= 10000 THEN precio_contrato
                    WHEN COALESCE(precio_propuesta, 0) >= 10000 THEN precio_propuesta
                    ELSE NULL
                  END AS precio_venta,
                  precio_propuesta,
                  precio_contrato,
                  precio_escritura,
                  desviacion_euros,
                  desviacion_pct,
                  dias_hasta_venta,
                  num_visitas,
                  honorarios,
                  agente,
                  responsable_gestion,
                  estado,
                  origen,
                  origen_inmueble,
                  estado_documental
                FROM operaciones_inmobiliarias
                WHERE {' AND '.join(where)}
                ORDER BY COALESCE(NULLIF(fecha_escritura, ''), NULLIF(fecha_operacion, ''), updated_at, created_at) DESC
                """,
                values,
            ).fetchall()
            kpis_row = conn.execute(
                """
                SELECT
                  COUNT(*) AS total,
                  COUNT(CASE WHEN TRIM(COALESCE(fecha_escritura, '')) <> '' THEN 1 END) AS cerradas,
                  ROUND(AVG(CASE WHEN precio_escritura > 0 THEN precio_escritura END), 2) AS ticket_medio,
                  ROUND(AVG(CASE WHEN dias_hasta_venta > 0 THEN dias_hasta_venta END), 1) AS dias_medios
                FROM operaciones_inmobiliarias
                WHERE empresa_id = ? AND LOWER(COALESCE(tipo_operacion, 'venta')) = 'venta'
                """,
                (empresa_id,),
            ).fetchone()
            json_response(
                self,
                {
                    "rows": [dict(r) for r in rows],
                    "kpis": dict(kpis_row) if kpis_row else {},
                },
            )
            return

